('You be careful!', '', 193192, 0, 0, 0, 64, 0, 153149, 0, 0, 0, 0, 0, 0, 0, 39653),
('Jrokgar go now.', '', 193191, 0, 0, 0, 64, 0, 153148, 0, 0, 0, 0, 0, 0, 0, 39653),
