('', 'Accessing journal entries.', 178259, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I want to read Wrathion\'s journal.', 'I want to read Wrathion\'s journal.', 178258, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('No, don\'t sanitize! Champion, ye\'ve got to get back to the Chamber right now!', '', 178257, 0, 0, 0, 64, 0, 139074, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Old God contamination detected. Initiating sanitization protocol.', 178256, 0, 0, 0, 64, 0, 0, 139081, 0, 0, 0, 0, 0, 0, 39653),
