('', 'DNT', 177429, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What has Overspark gotten me into?', '', 177428, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Cast all doubt from your mind. It will be wondrous!', 177427, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
