('', 'Do be careful.', 176599, 0, 0, 0, 64, 0, 0, 133972, 0, 0, 0, 0, 0, 0, 39653),
('', 'This way, mortal.', 176598, 0, 0, 0, 64, 0, 0, 133971, 0, 0, 0, 0, 0, 0, 39653),
('', 'You will serve your queen.', 176597, 0, 0, 0, 64, 0, 0, 133970, 0, 0, 0, 0, 0, 0, 39653),
('', 'Prove that you are worthy.', 176596, 0, 0, 0, 64, 0, 0, 133969, 0, 0, 0, 0, 0, 0, 39653),
('', 'Do not keep me waiting.', 176595, 0, 0, 0, 64, 0, 0, 133968, 0, 0, 0, 0, 0, 0, 39653),
('Ol\' Big Tusk\'s challenging roar echoes across the island.', '', 176594, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('ETA: Ahead of schedule. Details superfluous.', '', 176593, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
