('', 'Come closer! Our journey through time is just about to begin.', 175737, 0, 0, 0, 64, 0, 0, 139252, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'m so glad you could join us today!', 175736, 0, 0, 0, 64, 0, 0, 139251, 0, 0, 0, 0, 0, 0, 39653),
