('Weapons free!', '', 174739, 0, 0, 0, 64, 0, 132199, 0, 0, 0, 0, 0, 0, 0, 39653),
('All cannons, fire!', '', 174738, 0, 0, 0, 64, 0, 132198, 0, 0, 0, 0, 0, 0, 0, 39653),
('Deploy the reinforcements!', '', 174737, 0, 0, 0, 64, 0, 132201, 0, 0, 0, 0, 0, 0, 0, 39653),
('Reinforcements to these coordinates!', '', 174736, 0, 0, 0, 64, 0, 132200, 0, 0, 0, 0, 0, 0, 0, 39653),
('Prepare for annihilation!', '', 174735, 0, 0, 0, 64, 0, 132197, 0, 0, 0, 0, 0, 0, 0, 39653),
('Impertinent imbeciles! You will pay for this!', '', 174734, 0, 0, 0, 64, 0, 132203, 0, 0, 0, 0, 0, 0, 0, 39653),
('Nothing can topple my technology.', '', 174733, 0, 0, 0, 64, 0, 132206, 0, 0, 0, 0, 0, 0, 0, 39653),
('Atomized!', '', 174732, 0, 0, 0, 64, 0, 132205, 0, 0, 0, 0, 0, 0, 0, 39653),
('Eradicated!', '', 174731, 0, 0, 0, 64, 0, 132204, 0, 0, 0, 0, 0, 0, 0, 39653),
('I can teach you how to brew potions, cut gems, scribe scrolls, or enchant armor.\n\nDo you seek training?', '', 174730, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Excellent! Target practice!', '', 174729, 0, 0, 0, 64, 0, 132202, 0, 0, 0, 0, 0, 0, 0, 39653),
('Caution! Avoid contamination!', '', 174728, 0, 0, 0, 64, 0, 132008, 0, 0, 0, 0, 0, 0, 0, 39653),
('Warning! Hazard approaching!', '', 174726, 0, 0, 0, 64, 0, 132007, 0, 0, 0, 0, 0, 0, 0, 39653),
('Error. Mobility compromised.', '', 174725, 0, 0, 0, 64, 0, 132010, 0, 0, 0, 0, 0, 0, 0, 39653),
('Toxic substances detected!', '', 174724, 0, 0, 0, 64, 0, 132012, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sanitation required.', '', 174723, 0, 0, 0, 64, 0, 132009, 0, 0, 0, 0, 0, 0, 0, 39653),
('Toxicity levels rising!', '', 174722, 0, 0, 0, 64, 0, 132011, 0, 0, 0, 0, 0, 0, 0, 39653),
