('Long... live... the resistance...', 'Long... live... the resistance...', 173603, 0, 0, 0, 64, 0, 130712, 130713, 0, 0, 0, 0, 0, 0, 39653),
('', 'Let \'em have it!', 173601, 0, 0, 1, 64, 0, 0, 135406, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'m quick like an eel!', 173600, 0, 0, 0, 64, 0, 0, 135405, 0, 0, 0, 0, 0, 0, 39653),
('', 'This is kinda fun!', 173599, 0, 0, 0, 64, 0, 0, 135404, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'m counting on ya, $n!', 173598, 0, 0, 1, 64, 0, 0, 135403, 0, 0, 0, 0, 0, 0, 39653),
