('', 'You\'ll never break us.', 173594, 0, 0, 4, 64, 0, 0, 135422, 0, 0, 0, 0, 0, 0, 39653),
('', 'That one was for my friends.', 173593, 0, 0, 1, 64, 0, 0, 135421, 0, 0, 0, 0, 0, 0, 39653),
('', 'It had to be done.', 173592, 0, 0, 1, 64, 0, 0, 135420, 0, 0, 0, 0, 0, 0, 39653),
('', 'Our people are a little safer now.', 173591, 0, 0, 5, 64, 0, 0, 135423, 0, 0, 0, 0, 0, 0, 39653),
