('Blue bad!', '', 172499, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Mak! Are you okay?', '', 172498, 0, 0, 1, 64, 0, 134322, 0, 0, 0, 0, 0, 0, 0, 39653),
('Taking Pamphlet', 'Taking Pamphlet', 172497, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Which Shrine are you interested in?', 'Which Shrine are you interested in?', 172496, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your deeds are renowned, $p.\n\n<The dark ranger continues to fire shots into the target as he speaks.>', 'Your deeds are renowned, $p.\n\n<The dark ranger continues to fire shots into the target as he speaks.>', 172495, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
