('Darkness comin\' for you....', '', 170974, 0, 0, 0, 65, 0, 128411, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your soul gonna bleed!', '', 170973, 0, 0, 0, 65, 0, 128412, 0, 0, 0, 0, 0, 0, 0, 39653),
('Dis not... da end for me!', '', 170972, 0, 0, 0, 65, 0, 128413, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let your mind be clouded.', '', 170971, 0, 0, 0, 65, 0, 128414, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stare into the darkness of your soul.', '', 170970, 0, 0, 0, 65, 0, 128415, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is... where I belong.', '', 170969, 0, 0, 0, 65, 0, 128416, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will pay with your life!', '', 170968, 0, 0, 0, 65, 0, 128417, 0, 0, 0, 0, 0, 0, 0, 39653),
('There is no turning back now!', '', 170967, 0, 0, 0, 65, 0, 128418, 0, 0, 0, 0, 0, 0, 0, 39653),
('Serve your penitence!', '', 170966, 0, 0, 0, 65, 0, 128419, 0, 0, 0, 0, 0, 0, 0, 39653),
('These walls will be your tomb!', '', 170965, 0, 0, 0, 65, 0, 128420, 0, 0, 0, 0, 0, 0, 0, 39653),
('Now you\'ll stay... for eternity.', '', 170964, 0, 0, 0, 65, 0, 128421, 0, 0, 0, 0, 0, 0, 0, 39653),
('Common... such a crude language. Bandal!', '', 170963, 0, 0, 0, 65, 0, 128370, 0, 0, 0, 0, 0, 0, 0, 39653),
('Shorel\'aran.', '', 170962, 0, 0, 0, 65, 0, 128371, 0, 0, 0, 0, 0, 0, 0, 39653),
