('$n has assaulted Lemor\'athra Spire!', '$n has assaulted Lemor\'athra Spire!', 168954, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Horde has taken Lemor\'athra Spire!', 'The Horde has taken Lemor\'athra Spire!', 168953, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n has defended Lemor\'athra Spire!', '$n has defended Lemor\'athra Spire!', 168952, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n has assaulted Lemor\'athra Spire!', '$n has assaulted Lemor\'athra Spire!', 168951, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
