('Shatter your defiance!', '', 166091, 0, 0, 0, 64, 0, 122555, 0, 0, 0, 0, 0, 0, 0, 39653),
('Crush you!', '', 166090, 0, 0, 0, 64, 0, 122554, 0, 0, 0, 0, 0, 0, 0, 39653),
('Chilled to your bones!', '', 166089, 0, 0, 0, 64, 0, 122557, 0, 0, 0, 0, 0, 0, 0, 39653),
('Freeze your souls!', '', 166088, 0, 0, 0, 64, 0, 122556, 0, 0, 0, 0, 0, 0, 0, 39653),
('Embrace the rising tide!', '', 166087, 0, 0, 0, 64, 0, 122560, 0, 0, 0, 0, 0, 0, 0, 39653),
('The sea has claimed its due.', '', 166086, 0, 0, 0, 64, 0, 122566, 0, 0, 0, 0, 0, 0, 0, 39653),
('The unworthy have been drowned.', '', 166085, 0, 0, 0, 64, 0, 122565, 0, 0, 0, 0, 0, 0, 0, 39653),
('The depths... call...', '', 166084, 0, 0, 0, 64, 0, 122562, 0, 0, 0, 0, 0, 0, 0, 39653),
