('Grong strong! STROOONG GRONG!', '', 166000, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am Grong. I am helping.', '', 165999, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
