('', 'Warriors of Zandalar! De Alliance is attacking us from Nazmir, move out and kill them all!', 165075, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'They... they didn\'t come.', 165074, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
