('', '<Death Line.>', 164985, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My guards have secured the door.\n\nNow let us discuss your assignment.', 164984, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sorry, cap\'n...', '', 164983, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('For the money... and the Horde!', '', 164982, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I knew you didn\'t have it in you.', '', 164981, 0, 0, 0, 64, 0, 122218, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'For Zandalar!', 164980, 0, 0, 0, 64, 0, 0, 120907, 0, 0, 0, 0, 0, 0, 39653),
('', 'Loa grant me strength!', 164979, 0, 0, 0, 64, 0, 0, 120908, 0, 0, 0, 0, 0, 0, 39653),
('', 'Fall, outsider!', 164978, 0, 0, 0, 64, 0, 0, 120913, 0, 0, 0, 0, 0, 0, 39653),
('', 'Victory for de loa!', 164977, 0, 0, 0, 64, 0, 0, 120914, 0, 0, 0, 0, 0, 0, 39653),
('', 'May de Light have mercy on your souls... though it is more than you deserve!', 164976, 0, 0, 0, 64, 0, 0, 120915, 0, 0, 0, 0, 0, 0, 39653),
('', 'Light guide me... to de... Other Side...', 164975, 0, 0, 0, 64, 0, 0, 120912, 0, 0, 0, 0, 0, 0, 39653),
('', 'Zandalar forever!', 164974, 0, 0, 0, 64, 0, 0, 120911, 0, 0, 0, 0, 0, 0, 39653),
('', 'De Light judges all!', 164973, 0, 0, 0, 64, 0, 0, 120906, 0, 0, 0, 0, 0, 0, 39653),
('', 'To arms! Drive dese outsiders from Zuldazar!', 164972, 0, 0, 0, 64, 0, 0, 120903, 0, 0, 0, 0, 0, 0, 39653),
('', 'Retribution for de fallen!', 164971, 0, 0, 0, 64, 0, 0, 120905, 0, 0, 0, 0, 0, 0, 39653),
('', 'De reckoning is at hand!', 164970, 0, 0, 0, 64, 0, 0, 120904, 0, 0, 0, 0, 0, 0, 39653),
('', 'You trespass upon sacred ground, outsiders. You will not defile Zuldazar with your filth!', 164969, 0, 0, 0, 64, 0, 0, 120909, 0, 0, 0, 0, 0, 0, 39653),
('', 'Retreat while ye can, Horde! The Alliance holds this city.', 164968, 0, 0, 0, 64, 0, 0, 120700, 0, 0, 0, 0, 0, 0, 39653);
