('', 'The reckonin\' is at hand!', 164967, 0, 0, 0, 64, 0, 0, 120695, 0, 0, 0, 0, 0, 0, 39653),
('', 'Retribution fer the fallen!', 164966, 0, 0, 0, 64, 0, 0, 120696, 0, 0, 0, 0, 0, 0, 39653),
('', 'Tae arms! Drive back this wretched Horde!', 164965, 0, 0, 0, 64, 0, 0, 120693, 0, 0, 0, 0, 0, 0, 39653),
