('', 'Where... is she...?', 164201, 0, 0, 0, 64, 0, 0, 122516, 0, 0, 0, 0, 0, 0, 39653),
('', 'Soon she will be here, and she will tear you to pieces.', 164200, 0, 0, 0, 64, 0, 0, 122518, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ash\'al theradas!', 164199, 0, 0, 0, 64, 0, 0, 122515, 0, 0, 0, 0, 0, 0, 39653),
('', 'Scamper back to your Banshee Queen. We are coming for you.', 164198, 0, 0, 0, 64, 0, 0, 122513, 0, 0, 0, 0, 0, 0, 39653),
('', 'You will not win. We follow your every step.', 164197, 0, 0, 0, 64, 0, 0, 122512, 0, 0, 0, 0, 0, 0, 39653),
