('', 'Rise, and serve once again.', 164195, 0, 65932, 0, 64, 0, 0, 121561, 0, 0, 0, 0, 0, 0, 39653),
('', 'Death calls you home.', 164194, 0, 65932, 0, 64, 0, 0, 121560, 0, 0, 0, 0, 0, 0, 39653),
('', 'You have been given another chance.', 164193, 0, 65932, 0, 64, 0, 0, 121559, 0, 0, 0, 0, 0, 0, 39653),
('Ah, the hero has arrived. Good. We have work to do.', '', 164192, 0, 0, 0, 64, 0, 122209, 0, 0, 0, 0, 0, 0, 0, 39653),
('When the night elves lie dead at your feet, call on Brynja to raise them.', '', 164191, 0, 0, 0, 64, 0, 122211, 0, 0, 0, 0, 0, 0, 0, 39653),
