('', 'I coulda made... captain...', 162541, 0, 0, 0, 64, 0, 0, 121035, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ol\' Mr. Flaps died for nothin\' if you lose the loot!', 162540, 0, 0, 0, 64, 0, 0, 121034, 0, 0, 0, 0, 0, 0, 39653),
('', 'They\'re trying to steal our treasure, boys! Get \'em!', 162539, 0, 0, 25, 64, 0, 0, 121033, 0, 0, 0, 0, 0, 0, 39653),
('', 'You bilge rat!', 162538, 0, 0, 1, 64, 0, 0, 121032, 0, 0, 0, 0, 0, 0, 39653),
