INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('It\'s weird up here on the surface.', '', 162451, 0, 0, 0, 64, 0, 120440, 0, 0, 0, 0, 0, 0, 0, 39653),
('That don\'t... feel good...', '', 162450, 0, 0, 0, 64, 0, 120439, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hah! I got ye!', '', 162449, 0, 0, 0, 64, 0, 120445, 0, 0, 0, 0, 0, 0, 0, 39653),
('Of all the new and exciting places to explore, the Horde had to show up here?', '', 162448, 0, 0, 0, 64, 0, 120444, 0, 0, 0, 0, 0, 0, 0, 39653),
('Look at this wildlife! Ye could make a fine helmet out of it. Maybe decorate it with the Horde\'s teeth...', '', 162447, 0, 0, 0, 64, 0, 120443, 0, 0, 0, 0, 0, 0, 0, 39653),
('Time fer a poundin\'!', '', 162446, 0, 0, 0, 64, 0, 120438, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ye ever been huntin\' with a Dark Iron before?', 162445, 0, 0, 0, 64, 0, 0, 120434, 0, 0, 0, 0, 0, 0, 39653),
('', 'Bury me... under the mountain...', 162444, 0, 0, 0, 64, 0, 0, 120433, 0, 0, 0, 0, 0, 0, 39653),
('', 'Blaze! Feedin\' time!', 162443, 0, 0, 0, 64, 0, 0, 120437, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh good, the Horde! I was lookin\' fer some new bones to play fetch with me hound.', 162442, 0, 0, 0, 64, 0, 0, 120436, 0, 0, 0, 0, 0, 0, 39653),
('', 'Finally, some dry land! Now tae soak it with some salty Horde tears.', 162441, 0, 0, 0, 64, 0, 0, 120435, 0, 0, 0, 0, 0, 0, 39653),
('', 'Sic \'em, Blaze!', 162440, 0, 0, 0, 64, 0, 0, 120432, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ve been collecting these skulls since before I was dead!', 162439, 0, 0, 0, 64, 0, 0, 120427, 0, 0, 0, 0, 0, 0, 39653),
('', 'Not... the first time... I\'ve died...', 162438, 0, 0, 0, 64, 0, 0, 120426, 0, 0, 0, 0, 0, 0, 39653),
('', 'Another skull fer me!', 162437, 0, 0, 0, 64, 0, 0, 120431, 0, 0, 0, 0, 0, 0, 39653),
('', 'All right, Dark Irons! There\'s treasure for us here! And death for the Horde.', 162436, 0, 0, 0, 64, 0, 0, 120430, 0, 0, 0, 0, 0, 0, 39653),
('', 'Finally off the boat! Drinks are on the Horde, everyone! After we loot their corpses, of course.', 162435, 0, 0, 0, 64, 0, 0, 120429, 0, 0, 0, 0, 0, 0, 39653),
('Death to the Alliance!', '', 162434, 0, 0, 0, 64, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('', 'Hah! New Horde skulls fer my collection! Just what I needed!', 162433, 0, 0, 0, 64, 0, 0, 120428, 0, 0, 0, 0, 0, 0, 39653),
('Kul Tiras will burn!', '', 162432, 0, 0, 0, 64, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('Blood and thunder!', '', 162431, 0, 0, 0, 64, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('', 'Gimme that skull!', 162430, 0, 0, 0, 64, 0, 0, 120425, 0, 0, 0, 0, 0, 0, 39653),
('For the Warchief! For the Horde!', '', 162429, 0, 0, 0, 64, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('Lok-tar ogar!', '', 162428, 0, 0, 0, 64, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('Get in there! We\'ve got Alliance to kill!', '', 162427, 0, 0, 0, 64, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('Go, go, go!', '', 162426, 0, 0, 0, 64, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('Get in that portal, grunts!', '', 162425, 0, 0, 0, 64, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('My family will sing songs of your bravery!', 'My family will sing songs of your bravery!', 162424, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I thought I was done for! Thank you!', 'I thought I was done for! Thank you!', 162423, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Many blessings upon you!', 'Many blessings upon you!', 162422, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The naga have never been so bold!', 'The naga have never been so bold!', 162421, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll tell the others of your kindness!', 'I\'ll tell the others of your kindness!', 162420, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'ve saved my life! I won\'t forget this!', 'You\'ve saved my life! I won\'t forget this!', 162419, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I love the thrill of the drill!', '', 162418, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'No, no, silly $r...', 162417, 0, 0, 0, 70, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'No one rides the Lady!', 162416, 0, 0, 0, 102, 4000, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Fools.', '', 162414, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Together! For Quel\'Thalas!', 'Together! For Quel\'Thalas!', 162413, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Now, riders!', 162412, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I just wanted to drop... bombs...', 'I just wanted to drop... bombs...', 162411, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve got a bomb to drop on you!', '', 162410, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gilneas will remember your courage forever, Liam.', '', 162409, 0, 0, 0, 70, 0, 19497, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You were a true man of the people, Liam.  Unlike any Royal I ever met.  We\'ll make them pay for this.', 162408, 0, 0, 0, 70, 0, 0, 19686, 0, 0, 0, 0, 0, 0, 39653),
('We\'ll return, Liam.  I swear this to you.', '', 162407, 0, 0, 0, 70, 0, 19715, 0, 0, 0, 0, 0, 0, 0, 39653),
('It is here, surrounded by the heroes and patriots of Gilneas where he belongs.', '', 162406, 0, 0, 0, 70, 0, 19714, 0, 0, 0, 0, 0, 0, 0, 39653),
('May the Light bless the spirits of our ancestors, for they\'ve chosen to allow my son to rest upon this holy ground.', '', 162405, 0, 0, 0, 70, 0, 19713, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Stand tall, brothers and sisters! We must hold the line until reinforcements arrive! For Quel\'Thalas!', 162404, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Keep firing!  The spirits will guide our shots.', '', 162403, 0, 0, 5, 64, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('The wind is with us, the target is in sight!', '', 162402, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Get up there and stop that Horde Airship!', 162401, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '$n, the gryphon is all ready to go!', 162400, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aLor\'danel Landing is under attack!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aLor\'danel Landing is under attack!', 162399, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aLornesta Mine is under attack!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aLornesta Mine is under attack!', 162398, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aCinderfall Grove is under attack!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aCinderfall Grove is under attack!', 162397, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aGloomtide Strand is under attack!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aGloomtide Strand is under attack!', 162396, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aAshwood Depot is under attack!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aAshwood Depot is under attack!', 162395, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aForlorn Crossing is under attack!', '|A:Warfronts-FieldMapIcons-Alliance-Banner-Minimap:25:23:0:0|aForlorn Crossing is under attack!', 162394, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aBitterstone Quarry is under attack!', '|A:Warfronts-FieldMapIcons-Alliance-Mine-Minimap:25:23:0:0|aBitterstone Quarry is under attack!', 162393, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aWithering Thicket is under attack!', '|A:Warfronts-FieldMapIcons-Alliance-LumberMill-Minimap:25:23:0:0|aWithering Thicket is under attack!', 162392, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'This is where we make our stand. Darkshore belongs to the kaldorei!', 162391, 0, 0, 22, 64, 0, 0, 122403, 0, 0, 0, 0, 0, 0, 39653),
('', 'Prepare yourselves.', 162390, 0, 0, 22, 64, 0, 0, 122404, 0, 0, 0, 0, 0, 0, 39653),
('', 'Take out those catapults at once!', 162389, 0, 0, 22, 64, 0, 0, 122405, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\INV_Misc_Herb_AncientLichenPetal.blp:20|tIvus |cFFFF0000|Hspell:282615|h[Petrifies]|h|r his bark, defeat the Wisps to end the spell!', '', 162388, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My battles... are finished...', 'My battles... are finished...', 162387, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Taste my steel!', 'Taste my steel!', 162386, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Good work. Now get back to Kul Tiras in one piece.', '', 162384, 0, 0, 0, 64, 0, 122901, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'No matter what we face, no matter whose souls you desecrate, you will not defeat us!', 162381, 0, 0, 22, 64, 0, 0, 122414, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your death is at hand, Maiev! Dark rangers, attack!', 162380, 0, 0, 22, 64, 0, 0, 122472, 0, 0, 0, 0, 0, 0, 39653),
('', 'None can evade the strike of a true warden. You should know that better than anyone!', 162379, 0, 0, 22, 64, 0, 0, 122388, 0, 0, 0, 0, 0, 0, 39653),
('', 'There is no hope for you, Maiev. The forces of death are endless. You will watch your pathetic base crumble into dust.', 162378, 0, 0, 22, 64, 0, 0, 122468, 0, 0, 0, 0, 0, 0, 39653),
('', 'We have lost contact with Auberdine, and I want to know why! Go!', 162377, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Sira... What has that banshee done to you?', 162376, 0, 0, 22, 64, 0, 0, 122408, 0, 0, 0, 0, 0, 0, 39653),
('', 'Darkshore remains in the Horde\'s grasp. We must return to fight another day.', 162375, 0, 0, 22, 64, 0, 0, 122418, 0, 0, 0, 0, 0, 0, 39653),
('', 'Victory is ours, heroes. We have reclaimed Darkshore, but at great cost. Sylvanas will suffer for this atrocity. I swear it.', 162374, 0, 0, 22, 64, 0, 0, 122419, 0, 0, 0, 0, 0, 0, 39653),
('', 'With the Horde\'s gunships on the retreat, we now have a clear path to Sira herself. Take a hippogryph. It is time to finish this.', 162373, 0, 0, 22, 64, 0, 0, 122415, 0, 0, 0, 0, 0, 0, 39653),
('', 'Who are you to judge me? Have you forgotten how you betrayed your sisters? Come and meet your death!', 162372, 0, 0, 22, 64, 0, 0, 122471, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your defenses are failing and your armies are shattered, Sira! Soon you will face judgment!', 162371, 0, 0, 22, 64, 0, 0, 122413, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Glaiveworks is ready. Use it to build glaive throwers that can destroy the machines blocking our path to Lor\'danel.', 162370, 0, 0, 22, 64, 0, 0, 122402, 0, 0, 0, 0, 0, 0, 39653),
('', 'We now have a Tree of Eternity on our side. Recruit additional forces and take the fight to Sira!', 162369, 0, 0, 22, 64, 0, 0, 122401, 0, 0, 0, 0, 0, 0, 39653),
('', 'Our Tree of Life has become a Tree of Ages. It is time to start building the Glaiveworks.', 162368, 0, 0, 22, 64, 0, 0, 122400, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Ancient of War has joined our cause. Now we can have Jarod bring more troops to Bashal\'Aran.', 162367, 0, 0, 22, 64, 0, 0, 122399, 0, 0, 0, 0, 0, 0, 39653),
('', 'We have finished building the Hunter\'s Hall. Provide it with the resources it needs to improve our weapons and armor.', 162366, 0, 0, 22, 64, 0, 0, 122398, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Altar of Elders is complete. Tap into it to empower yourself, or to take the form of a potent ally.', 162365, 0, 0, 22, 64, 0, 0, 122397, 0, 0, 0, 0, 0, 0, 39653),
('', 'Lor\'danel is ours, but Sira still awaits us on that goblin monstrosity. Protect our glaive throwers as they bring down its defenses.', 162364, 0, 0, 22, 64, 0, 0, 122391, 0, 0, 0, 0, 0, 0, 39653),
('', 'We have captured Forlorn Crossing. Hold the crossroads and protect Bashal\'Aran!', 162363, 0, 0, 22, 64, 0, 0, 122390, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ashwood Depot belongs to the Alliance. Now we can quickly traverse the battlefield and call chimaera to aid us.', 162362, 0, 0, 22, 64, 0, 0, 122389, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Alliance holds Gloomtide Strand. We can now recruit druids into our ranks, and invoke the aid of a powerful archdruid.', 162361, 0, 0, 22, 64, 0, 0, 122394, 0, 0, 0, 0, 0, 0, 39653),
('', 'Still you have the nerve to command me? You who abandoned the Watchers in your selfish pursuit of a single prisoner?', 162360, 0, 0, 22, 64, 0, 0, 122473, 0, 0, 0, 0, 0, 0, 39653),
('', 'Sira! Cease this madness and submit yourself to a clean death. You cannot stop the tide of vengeance.', 162359, 0, 0, 22, 64, 0, 0, 122417, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Ruins of Lornesta belong to us now. The iron in their vicinity will benefit our soldiers.', 162358, 0, 0, 22, 64, 0, 0, 122396, 0, 0, 0, 0, 0, 0, 39653),
('', 'We have seized Bitterstone Quarry! Mine its iron so we can strengthen our forces.', 162357, 0, 0, 22, 64, 0, 0, 122395, 0, 0, 0, 0, 0, 0, 39653),
('', 'The lumber mill at Cinderfall Grove is under our control. With its wood, we can improve our buildings and reinforce our base.', 162356, 0, 0, 22, 64, 0, 0, 122393, 0, 0, 0, 0, 0, 0, 39653),
('', 'We have taken the lumber mill at Withering Thicket. Gather its wood to help rebuild our outposts.', 162355, 0, 0, 22, 64, 0, 0, 122392, 0, 0, 0, 0, 0, 0, 39653),
('', 'Well done. With Bashal\'Aran secured, we will bolster our forces and strike at the Horde. Fight for every resource from here to Lor\'danel.', 162354, 0, 0, 22, 64, 0, 0, 122387, 0, 0, 0, 0, 0, 0, 39653),
('', 'We have established a foothold at Auberdine. Do not relent! Press on and gather as many resources as you can.', 162353, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Heroes! Today, we retake Darkshore from the despicable Horde. To arms!', 162352, 0, 0, 22, 64, 0, 0, 122416, 53, 0, 0, 0, 0, 0, 39653),
('|TInterface\\ICONS\\INV_SWORD_48.BLP:20|t You are targeted for |cFFF00000|Hspell:282618|h[Heart Strike]|h|r!', '', 162351, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You make Princess Theradras look like a world wonder!', '', 162342, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hey you... ogre breath! Over here!', '', 162341, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve fought TROGGS smarter than you!', '', 162340, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Horde has taken control of Forlorn Crossing!', 'The Horde has taken control of Forlorn Crossing!', 162339, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n has captured Forlorn Crossing!', '$n has captured Forlorn Crossing!', 162338, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The stones... crumble...', 'The stones... crumble...', 162337, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stone of the earth, heed my call! Come to my aid!', 'Stone of the earth, heed my call! Come to my aid!', 162336, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Woodfang swoops into the Aerie with a triumphant screech.', '', 162335, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The thicket is ours!', 162334, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Protect the grove!', '', 162333, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There, in the shadows....', 'There, in the shadows....', 162332, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What was that?', 'What was that?', 162331, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You can\'t hide from me....', 'You can\'t hide from me....', 162330, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Someone\'s sneaking around....', 'Someone\'s sneaking around....', 162329, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Who goes there?', 'Who goes there?', 162328, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re about as attractive as a Leper Gnome!', '', 162327, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve seen Tortollans faster than you!', '', 162326, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your mother is a MURLOC!', '', 162325, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Da spirits... leave... me...', 'Da spirits... leave... me...', 162324, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I gonna bring da Warchief ya head!', 'I gonna bring da Warchief ya head!', 162323, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Huhahuuuuu!', '', 162320, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('They\'ll... catch you....', '', 162319, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Assassin! Guards!', '', 162318, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, the shipments are in order. These will greatly help our effort against the Horde.', '', 162317, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Selama... ashal\'anore...', 'Selama... ashal\'anore...', 162316, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Shorel\'aran kim\'jael!', 'Shorel\'aran kim\'jael!', 162315, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I want a NON flying aura, for jumping.', 'I want a NON flying aura, for jumping.', 162314, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I want a flying aura!', 'I want a flying aura!', 162313, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Good work, mon. Now get out of dere, quickly!', '', 162307, 0, 0, 0, 64, 0, 121648, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our scouts be sayin\' we got a prime target nearby. Find \'em and eliminate \'em.', '', 162306, 0, 0, 0, 64, 0, 121639, 0, 0, 0, 0, 0, 0, 0, 39653),
('The pain... gone now...', 'The pain... gone now...', 162304, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
