('No touching!', 'No touching!', 160827, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll swab the decks with your blood!', 'I\'ll swab the decks with your blood!', 160826, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll stop this $pr!', 'I\'ll stop this $pr!', 160825, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Whatever you\'re doing, cut it out!', 'Whatever you\'re doing, cut it out!', 160824, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What has de loa brought me today?', 'What has de loa brought me today?', 160823, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hands off the supplies!', 'Hands off the supplies!', 160822, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653);
