('|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aNewstead has been lost!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aNewstead has been lost!', 158205, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
