('Arrraagh!', '', 155296, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Garoooo...', '', 155295, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This trogg land! You leave!', '', 155294, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Aaaraauuh! Trogg kill you!', '', 155293, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Break you into pebbles!', '', 155292, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ve kept things running smoothly all across Kul Tiras. How can I help you?', 155291, 7, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Shiny rocks belong to trogg! Go away!', '', 155290, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Graaaaraah! Destroy!', '', 155289, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
