('Korthek brought this war upon us.', '', 153015, 0, 0, 0, 64, 0, 106009, 0, 0, 0, 0, 0, 0, 0, 39653),
('We must remain strong.', '', 153014, 0, 0, 0, 64, 0, 106008, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you here to help?', '', 153013, 0, 0, 0, 64, 0, 106007, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We really shouldn\'t have saved you. Wait! I didn\'t mean that...', 153012, 0, 0, 0, 64, 0, 0, 105992, 0, 0, 0, 0, 0, 0, 39653),
('', 'You did not just do that again...', 153011, 0, 0, 0, 64, 0, 0, 105991, 0, 0, 0, 0, 0, 0, 39653),
('', 'You should probably stop that.', 153010, 0, 0, 0, 64, 0, 0, 105990, 0, 0, 0, 0, 0, 0, 39653),
('', 'What are you doing?', 153009, 0, 0, 0, 64, 0, 0, 105989, 0, 0, 0, 0, 0, 0, 39653),
('', 'You\'ll be back, right?', 153008, 0, 0, 0, 64, 0, 0, 105984, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hey, don\'t die out there!', 153007, 0, 0, 0, 64, 0, 0, 105983, 0, 0, 0, 0, 0, 0, 39653),
