('', 'It\'s direct.', 152450, 0, 0, 1, 64, 0, 0, 109760, 0, 0, 0, 0, 0, 0, 39653),
('', 'Is that... good?', 152449, 0, 0, 669, 64, 0, 0, 111716, 0, 0, 0, 0, 0, 0, 39653),
('', 'Tidesages walk this ceremonial path on their way to be blessed at the shrine.', 152448, 0, 0, 1, 64, 0, 0, 109759, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your wounds cannot mend so long as the curse has you!', 152447, 0, 0, 0, 64, 0, 0, 103119, 0, 0, 0, 0, 0, 0, 39653),
('', 'This cannot be the end.', 152446, 0, 0, 0, 64, 0, 0, 103122, 0, 0, 0, 0, 0, 0, 39653),
