('You buyin\' or sellin\'?', '', 151944, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'This doesn\'t look good...', 151943, 0, 0, 1, 64, 0, 0, 112108, 0, 0, 0, 0, 0, 0, 39653),
('With pleasure. They shall suffer in your name!', '', 151942, 0, 0, 0, 64, 0, 113786, 0, 0, 0, 0, 0, 0, 0, 39653),
('Contagion detected. Sanitize.', '', 151941, 0, 0, 0, 64, 0, 104790, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pestilent explosion!', '', 151940, 0, 0, 0, 64, 0, 102962, 0, 0, 0, 0, 0, 0, 0, 39653),
('Engaging final safeguard. Destroy virulent source.', '', 151939, 0, 0, 0, 64, 0, 104791, 0, 0, 0, 0, 0, 0, 0, 39653),
