INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('Just a few broken bones... nothing important.', '', 151934, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Lead de way to de vulpera camp, $p. We\'ll haul de treasure.', '', 151933, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Blood expulsion!', '', 151932, 0, 0, 0, 64, 0, 102961, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Lay down your arms! You don\'t have to do this!', 151931, 0, 0, 396, 64, 0, 0, 110207, 0, 0, 0, 0, 0, 0, 39653),
('Must... spread...', '', 151930, 0, 0, 0, 64, 0, 102966, 0, 0, 0, 0, 0, 0, 0, 39653),
('Blight touched!', '', 151929, 0, 0, 0, 64, 0, 102968, 0, 0, 0, 0, 0, 0, 0, 39653),
('Infected!', '', 151928, 0, 0, 0, 64, 0, 102967, 0, 0, 0, 0, 0, 0, 0, 39653),
('Corrupt flesh.', '', 151927, 0, 0, 0, 64, 0, 102969, 0, 0, 0, 0, 0, 0, 0, 39653),
('Consume!', '', 151926, 0, 0, 0, 64, 0, 102965, 0, 0, 0, 0, 0, 0, 0, 39653),
('Must spread!', '', 151925, 0, 0, 0, 64, 0, 102964, 0, 0, 0, 0, 0, 0, 0, 39653),
('Jus\' don\'t ya go forgettin\' your end o\' da bargain, now...', '', 151924, 0, 0, 25, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hahahaha! See, Ya Majesty? Bwonsamdi always makes good on his deals!', '', 151923, 0, 0, 11, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Rise... rise! Don\'t be lazy now! Take up ya spears again and FIGHT!', '', 151922, 0, 0, 15, 64, 0, 110169, 0, 0, 0, 0, 0, 0, 0, 39653),
('Easy now, ya Majesty. Bwonsamdi are always helping friend...', '', 151921, 0, 0, 661, 64, 0, 110168, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ya needn\'t be watchin\' me work from dere. We both got jobs to do.', 151920, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('De boat\'s ready to go when we are.', '', 151919, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Dese traitors stand between me and my kingdom, yet where is de aid you promised? Do you intend to keep your word?', '', 151918, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ye did well, champion. I can feel Azeroth recoverin\' her strength, thanks tae ye.', '', 151916, 0, 0, 0, 64, 0, 110221, 0, 0, 0, 0, 0, 0, 0, 39653),
('Several Azerite wounds lay exposed nearby. Use the Heart of Azeroth tae mend \'em!', '', 151915, 0, 0, 0, 64, 0, 110220, 0, 0, 0, 0, 0, 0, 0, 39653),
('Run away while you still can!', '', 151913, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tsk, tsk! Not a respectful tone ta take with ya loa, Ya Majesty. But I suppose de souls I be collectin\' today more than make up for it!', '', 151912, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We in dis together now, $p.\n\nMutiny or de yard arm.', '', 151911, 0, 0, 0, 64, 0, 0, 0, 669, 0, 0, 0, 0, 0, 39653),
('Bwonsamdi, show yourself!', '', 151910, 0, 0, 0, 64, 0, 110174, 0, 0, 0, 0, 0, 0, 0, 39653),
('Too many sided with Zul. Dere is only one path forward...', '', 151909, 0, 0, 0, 64, 0, 110173, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s eyes |cFFFF0000$n|r and prepares to |cFFFF0000|Hspell:266951|h[Barrel Through]|h|r!', '|TInterface\\Icons\\ABILITY_MONK_CLASHINGOXCHARGE:20|t%s eyes |cFFFF0000$n|r and prepares to |cFFFF0000|Hspell:266951|h[Barrel Through]|h|r!', 151908, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The ancient wards defending the heart of Sethraliss have been disabled by a group of Zandalari...', 'The ancient wards defending the heart of Sethraliss have been disabled by a group of Zandalari...', 151907, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, Cesi can count on my support.', '', 151906, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Get to it you lazy goblins; I want that Base in a Box set up now!', 'Get to it you lazy goblins; I want that Base in a Box set up now!', 151905, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Will your support Cesi Loosecannon?', 'Will your support Cesi Loosecannon?', 151904, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hmmmmm. Yes. Let me look.\n\n<Kooda rummages around for a long while before pulling out a jar from the depths of the pack.>\n\nBought this a couple hundred years ago. I\'d forgotten about it. I suppose I could sell it.', '', 151902, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Have you ever heard of something called \'Century Sauce\' ? Do you have any?', 'Have you ever heard of something called \'Century Sauce\' ? Do you have any?', 151901, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hello $r. Do you have anything interesting to sell?', '', 151900, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('By the tide, it comes!', 'By the tide, it comes!', 151899, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hunger insatiable, the king feasts.', '', 151898, 0, 0, 0, 64, 0, 102860, 0, 0, 0, 0, 0, 0, 0, 39653),
('The wound festers. The world putrefies.', '', 151897, 0, 0, 0, 64, 0, 102859, 0, 0, 0, 0, 0, 0, 0, 39653),
('We have always been in your mind.', '', 151896, 0, 0, 0, 64, 0, 102858, 0, 0, 0, 0, 0, 0, 0, 39653),
('The rotted screams will herald his arrival.', '', 151895, 0, 0, 0, 64, 0, 102857, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|tZanazal the Wise begins to cast |cFFFF0000|Hspell:267273|h[Poison Nova]|h|r!', '|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_02:20|tZanazal the Wise begins to cast |cFFFF0000|Hspell:267273|h[Poison Nova]|h|r!', 151894, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The crawling ones have awakened!', 151893, 0, 0, 0, 64, 0, 0, 103100, 0, 0, 0, 0, 0, 0, 39653),
('', 'Kril lax qutholil!', 151892, 0, 0, 0, 64, 0, 0, 103099, 0, 0, 0, 0, 0, 0, 39653),
('You have faced the naga as my avatar and brought an end to the assault on my temple.', '', 151890, 0, 0, 0, 64, 0, 109630, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh! I\'ve wanted to use Century Sauce for ages! It\'s a cooking paste made of several ingredients all blended together and then allowed to ferment for centuries. The longer it ferments the more complex the flavor profile. It is said to add a distinctive spice and tang to any dish.\n\nThere are rumors some of the Tortollan traders carry it, but it is rare and wildly expensive.\n\n<Xun Xun sighs wistfully>\n\nIt is a chef\'s dream ingredient!', 151889, 0, 0, 4, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have an extensive pantry. Is there anything missing from your spice rack?', 'You have an extensive pantry. Is there anything missing from your spice rack?', 151888, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'A new face! And a friendly one, I think. Care to try something special? Or perhaps you are looking for rare spices or recipes?', 151887, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Heart of Azeroth is stronger now, thanks tae ye. We\'re one step closer tae curing Azeroth of her wounds.', '', 151886, 0, 0, 0, 64, 0, 110219, 0, 0, 0, 0, 0, 0, 0, 39653),
('I can sense Azerite nearby... and those who would seek tae abuse it for their own ends. Ye\'ve got tae stop \'em!', '', 151885, 0, 0, 0, 64, 0, 110218, 0, 0, 0, 0, 0, 0, 0, 39653),
('Come, little sapling. Calm your heart and help me heal this man.', '', 151884, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Blood pours forth in the depths.', 151883, 0, 0, 0, 64, 0, 0, 103106, 0, 0, 0, 0, 0, 0, 39653),
('', 'Beneath the tides, your truth awaits.', 151882, 0, 0, 0, 64, 0, 0, 103105, 0, 0, 0, 0, 0, 0, 39653),
('', 'Listen to the music of the drowned.', 151881, 0, 0, 0, 64, 0, 0, 103104, 0, 0, 0, 0, 0, 0, 39653),
('', 'Darkness roots. Pestilence spreads. The doorway is open.', 151880, 0, 0, 0, 64, 0, 0, 103098, 0, 0, 0, 0, 0, 0, 39653),
('', 'The fathoms will devour your screams!', 151879, 0, 0, 0, 64, 0, 0, 103109, 0, 0, 0, 0, 0, 0, 39653),
('', 'I reside within your lungs!', 151878, 0, 0, 0, 64, 0, 0, 103110, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will await you... in the dark...', 151877, 0, 0, 0, 64, 0, 0, 103112, 0, 0, 0, 0, 0, 0, 39653),
('', 'You are mine!', 151876, 0, 0, 0, 64, 0, 0, 103115, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your allies enjoyed watching you die.', 151875, 0, 0, 0, 64, 0, 0, 103116, 0, 0, 0, 0, 0, 0, 39653),
('', 'We are bound forever in the vastness of the deep.', 151874, 0, 0, 0, 64, 0, 0, 103118, 0, 0, 0, 0, 0, 0, 39653),
