('|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aNewstead is under attack!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aNewstead is under attack!', 150859, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aCircle of Elements is under attack!', '|A:Warfronts-FieldMapIcons-Horde-Banner-Minimap:25:23:0:0|aCircle of Elements is under attack!', 150858, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
