('Hey, that tickles!', '', 150300, 0, 0, 0, 64, 0, 104069, 0, 0, 0, 0, 0, 0, 0, 39653),
('Blow you down!', '', 150299, 0, 0, 0, 64, 0, 104071, 0, 0, 0, 0, 0, 0, 0, 39653),
