('My machines are at your command!', '', 148218, 0, 0, 0, 64, 0, 105263, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'As you wish. Champions, with me!', 148217, 0, 0, 0, 64, 0, 0, 105259, 0, 0, 0, 0, 0, 0, 39653),
('Jaina, Genn, help me with Blightcaller and Lor\'themar.', '', 148216, 0, 0, 0, 64, 0, 105311, 0, 0, 0, 0, 0, 0, 0, 39653),
('Indubitably! I brought some extra machines for backup. Feel free to give \'em a spin!', '', 148215, 0, 0, 0, 64, 0, 105262, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I am known for my timing, your majesty. Mekkatorque, are you ready for battle?', 148214, 0, 0, 0, 64, 0, 0, 105258, 0, 0, 0, 0, 0, 0, 39653),
('Alleria! Thank the Light you\'ve made it!', '', 148213, 0, 0, 0, 64, 0, 105310, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'G\'huun be everywhere!', 148212, 0, 0, 0, 64, 0, 0, 101025, 0, 0, 0, 0, 0, 0, 39653),
