('', 'I\'M NOT GONNA BE AFRAID ANYMORE!', 145159, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My light is super strong!', 145158, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Me waan go home.', '', 145157, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'And as long as my light is with me, there\'s no way the darkness can win!', 145156, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Mama told me the Light would always find me. That\'s you, friend. You\'re my light!', 145155, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'F-friend, you\'re here! You didn\'t leave me!', 145154, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
