('I will feast on your bones!', 'I will feast on your bones!', 145145, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Death to the living!', 'Death to the living!', 145144, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('For Sylvanas!', 'For Sylvanas!', 145143, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Uuna wraps her arms around herself and begins to cry.', 145142, 0, 0, 18, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I--I can\'t do it! I just wanna go home!', 145141, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Friend? Are you still there? I\'m scared!', 145140, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
