('', '<Kiss sound>', 145116, 0, 0, 0, 64, 0, 0, 99873, 0, 0, 0, 0, 0, 0, 39653),
('\"Thank you, my friend,\" Arom said to the stag.', '\"Thank you, my friend,\" Arom said to the stag.', 145115, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '<Laughing sounds>', 145114, 0, 0, 0, 64, 0, 0, 99874, 0, 0, 0, 0, 0, 0, 39653),
