('', '<Making a raspberry sound--Pfffthblth!>', 145112, 0, 0, 0, 64, 0, 0, 99876, 0, 0, 0, 0, 0, 0, 39653),
('Together Arom and the White Stag fought the warriors and defeated them.', 'Together Arom and the White Stag fought the warriors and defeated them.', 145111, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '<Roar of dominance>', 145110, 0, 0, 0, 64, 0, 0, 99877, 0, 0, 0, 0, 0, 0, 39653),
('', '<Variant roar>', 145109, 0, 0, 0, 64, 0, 0, 99878, 0, 0, 0, 0, 0, 0, 39653),
