('Unit Hezrel online. Goal: corruption containment.', '', 144618, 0, 0, 0, 64, 0, 104763, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your behavior is getting old... even older than me!', 144617, 0, 0, 0, 64, 0, 0, 98562, 0, 0, 0, 0, 0, 0, 39653),
