('', 'Ugh. What is it?', 144610, 0, 0, 0, 64, 0, 0, 98556, 0, 0, 0, 0, 0, 0, 39653),
('', 'Do you really need to talk to me?', 144609, 0, 0, 0, 64, 0, 0, 98555, 0, 0, 0, 0, 0, 0, 39653),
