('', 'G\'huun!', 144280, 0, 0, 0, 64, 0, 0, 98372, 0, 0, 0, 0, 0, 0, 39653),
('<Tsunga grunts affectionately at you.>', '', 144279, 0, 54659, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
