('Good. Good! Once more!', '', 144269, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stop fidgeting.', '', 144268, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ll help reinforce the village\'s defenses. I will meet you there!', 144266, 0, 0, 1, 64, 0, 0, 103331, 0, 0, 0, 0, 0, 0, 39653),
('', 'We\'ve broken them. Come! We should speak with Mayor Royston.', 144265, 0, 0, 0, 64, 0, 0, 103339, 0, 0, 0, 0, 0, 0, 39653),
('', 'Alleria sighs, her brow furrowed.', 144264, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
