('Nigel! There you are!', '', 141500, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'What\'s explorin\' without a little danger? Didn\'t even get a scratch.', 141499, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'And that\'s about all I could drag out by meself.', 141498, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
