('Forgive me, my queen.', '', 140964, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My queen... I have failed you!', '', 140963, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('None may approach de queen!', '', 140962, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('De queen\'s rest must not be interrupted!', '', 140961, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am de queen\'s eternal protector! Begone!', '', 140960, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'By de loa... No! Now we see de true power of de blood trolls. Oh father... why did you ignore dem for so long?!', 140959, 0, 0, 0, 64, 0, 0, 101734, 0, 0, 0, 0, 0, 0, 39653),
('', 'Prepare yourself, $n. We have no idea what may be ahead.', 140958, 0, 0, 0, 64, 0, 0, 101733, 0, 0, 0, 0, 0, 0, 39653),
