('', 'Let\'s go back to my ship and twist our nethers.', 140953, 0, 0, 0, 64, 0, 0, 91263, 0, 0, 0, 0, 0, 0, 39653),
('', 'You must be descended from the naaru... \'cause you\'ve got a heavenly body.', 140952, 0, 0, 0, 64, 0, 0, 91262, 0, 0, 0, 0, 0, 0, 39653),
