('Target my enemy!', '', 139403, 0, 0, 0, 64, 0, 91932, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Target my foe!', 139402, 0, 0, 0, 64, 0, 0, 91745, 0, 0, 0, 0, 0, 0, 39653),
