('', 'Foolish loa! Ya be findin\' only death here!', 136140, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Our home... what has it become?', 136139, 0, 0, 20, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Vindicaar is yours to command.', '', 136138, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
