('', 'Pheta thones gamera.', 134139, 0, 0, 0, 64, 0, 0, 86267, 0, 0, 0, 0, 0, 0, 39653),
('', 'Bring me the injured. I shall heal their wounds and purge this filth with a single prayer!', 134138, 0, 0, 0, 64, 0, 0, 86567, 0, 0, 0, 0, 0, 0, 39653),
('', 'Wretched souls! Your defeat shall come swiftly.', 134137, 0, 0, 0, 64, 0, 0, 86562, 0, 0, 0, 0, 0, 0, 39653),
