('', 'Arkonos vi acahachi!', 134133, 0, 0, 0, 64, 0, 0, 86560, 0, 0, 0, 0, 0, 0, 39653),
('', 'We will destroy you, no matter the cost!', 134131, 0, 0, 0, 64, 0, 0, 86557, 0, 0, 0, 0, 0, 0, 39653),
('', 'Shall you die to my magic or my blade?', 134130, 0, 0, 0, 64, 0, 0, 86554, 0, 0, 0, 0, 0, 0, 39653),
('', 'I have sacrified too much to lose!', 134129, 0, 0, 0, 64, 0, 0, 86551, 0, 0, 0, 0, 0, 0, 39653),
('', 'My glaive will cut you down like grain.', 134128, 0, 0, 0, 64, 0, 0, 86592, 0, 0, 0, 0, 0, 0, 39653),
