INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('Sound effect for troops', '', 130514, 0, 0, 0, 64, 0, 84354, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sound effect for troops', 'Sound effect for troops', 130513, 0, 0, 0, 64, 0, 84379, 84379, 0, 0, 0, 0, 0, 0, 39653),
('I want to participate in the Trial of Style!', 'I want to participate in the Trial of Style!', 130512, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We can currently obtain Artifact Knowledge for you as quickly as you can bring me the resources required to produce them.', 'We can currently obtain Artifact Knowledge for you as quickly as you can bring me the resources required to produce them.', 130511, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I want to transmogrify my gear.', 'I want to transmogrify my gear.', 130510, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have all the tools necessary to adjust the appearance of your weapons and armor.\n\nShall we begin?', '', 130509, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Archmage Khadgar has a lead on how we can continue our artifact knowledge research. Seek him out at Deliverance Point on the Broken Shore.', 'Archmage Khadgar has a lead on how we can continue our artifact knowledge research. Seek him out at Deliverance Point on the Broken Shore.', 130508, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We have reached the maximum Artifact Knowledge available to us at this time.', 'We have reached the maximum Artifact Knowledge available to us at this time.', 130507, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Orders are sharing their resources, and you are no longer required to research Artifact Knowledge. We will gain further Knowledge each week.', 'The Orders are sharing their resources, and you are no longer required to research Artifact Knowledge. We will gain further Knowledge each week.', 130506, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Why can\'t I research Artifact Knowledge?', 'Why can\'t I research Artifact Knowledge?', 130505, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Whatever happens, we stand together.', '', 130504, 0, 0, 0, 64, 0, 86121, 0, 0, 0, 0, 0, 0, 0, 39653),
('More flesh for the taking!', '', 130503, 0, 0, 0, 64, 0, 86169, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your flesh will fuel these pits for eternity!', '', 130502, 0, 0, 0, 64, 0, 86168, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our chains hunger for your flesh!', '', 130501, 0, 0, 0, 64, 0, 86167, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will kneel or you will die!', '', 130500, 0, 0, 0, 64, 0, 86166, 0, 0, 0, 0, 0, 0, 0, 39653),
('Feeble and weak! You dare enter our lair?', '', 130499, 0, 0, 0, 64, 0, 86165, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your supple flesh will satisfy my hunger!', '', 130498, 0, 0, 0, 64, 0, 86164, 0, 0, 0, 0, 0, 0, 0, 39653),
('Crunchy bones. So brittle and tasty!', '', 130497, 0, 0, 0, 64, 0, 86163, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will feast upon your soul.', '', 130496, 0, 0, 0, 64, 0, 86162, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Free! We gotta move, hop on!', 130494, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'More of my soldiers, but de path goes further. So must we.', 130490, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My people... slaughtered! You see now de evil we are fighting, $n. De blood trolls are monsters!', 130485, 0, 0, 22, 64, 0, 0, 101779, 0, 0, 0, 0, 0, 0, 39653),
('Insolent mortal! Come... face your death!', '', 130483, 0, 0, 0, 64, 0, 86202, 0, 0, 0, 0, 0, 0, 0, 39653),
('Over here, $p. Keep your head down.', '', 130482, 0, 0, 0, 64, 0, 86134, 0, 0, 0, 0, 0, 0, 0, 39653),
('That\'s right... today\'s contest has no theme. Wear whatever you want!', '', 130481, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pristine white robes and glimmering armor are the order of the day!', '', 130480, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('As you know, epic armor is ALWAYS purple. Wrap yourselves up in the bottom of the rainbow!', '', 130479, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Will you be a farmer? A chef? A scientist? A pirate? Ooh... I can\'t WAIT to see what they come up with!', '', 130478, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Will you represent Theramore? The Kirin Tor? Talk to Nellie if you need a spare tabard!', '', 130477, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It\'s time to have fun and get a little crazy with your costumes!', '', 130476, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Show us your sparkles with your most wizardly wear! And don\'t forget the enchantments!', '', 130475, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pandarian fashion just SCREAMS harmoniousness. Show us your inner peace!', '', 130474, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('For the Horde! For the Alliance! Let\'s see your team colors.', '', 130473, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Show us your more sinister styles!', '', 130472, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Frighten the fashion out of us with your creepiest costumes. Oooh... I\'m getting chills already!', '', 130471, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Have a little fun and put together the most garish ensemble you can dream up!', '', 130470, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Be still my heart! Don\'t be afraid to show a little skin!', '', 130469, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take off that makeup and put on that war paint!', '', 130468, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bundle up! Let\'s see what you wear on the frozen shores of Northrend!', '', 130467, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The theme of today\'s competition is... Freestyle!', 130466, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The theme of today\'s competition is... Champions of the Light!', 130465, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The theme of today\'s competition is... Epic Purples!', 130464, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The theme of today\'s competition is... Everyday Heroes!', 130463, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The theme of today\'s competition is... Tabard Time!', 130462, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
