('|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t The Fallen Avatar casts |cFFFF0404|Hspell:234418|h[Rain of the Destroyer]|h|r!', '|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t The Fallen Avatar casts |cFFFF0404|Hspell:234418|h[Rain of the Destroyer]|h|r!', 130362, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
