INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('$n activated an Unstable Nether Portal in Felbreach Hollow!', '$n activated an Unstable Nether Portal in Felbreach Hollow!', 130168, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n activated an Unstable Nether Portal in Deadwood Landing!', '$n activated an Unstable Nether Portal in Deadwood Landing!', 130167, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n activated an Unstable Nether Portal in Dark Stockades!', '$n activated an Unstable Nether Portal in Dark Stockades!', 130166, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n activated an Unstable Nether Portal in Crescent Ruins!', '$n activated an Unstable Nether Portal in Crescent Ruins!', 130165, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n activated an Unstable Nether Portal in Coast of Anguish!', '$n activated an Unstable Nether Portal in Coast of Anguish!', 130164, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n activated an Unstable Nether Portal in Cinder Run!', '$n activated an Unstable Nether Portal in Cinder Run!', 130163, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I don\'t have words... You\'ve made me the happiest person!  To our next adventure!', '', 130162, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I... I understand.', '', 130161, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you?... You ARE!  I have so much to tell you!  Where do I get started? \n\nSince our first adventure, I could no longer focus on anything but when our next adventure would be.  My friends would tell me that you weren\'t real, that I was acting crazy, that you\'re only in the dream.  I knew they couldn\'t be right! The feelings I have are far more than a dream!\n\nEvery adventure we\'ve been on, every foe we\'ve slain, and every chat we\'ve had has brought me to one question for you...', '', 130160, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll keep waiting, I know they\'ll come!', '', 130159, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Before you ask, I don\'t know what this person looks like. In my first dream they were a night elf, in the second they were a tauren, and in the third a night elf again. In these dreams we\'d adventure across Azeroth and Draenor fighting demons, dragons, old gods, and even murlocs! \n\nI\'d never had a connection like this before.  It seemed so real to me.  In my last dream, I asked them to meet me here.', '', 130158, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Is it you?!  The person I\'ve been dreaming about?!', '', 130157, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Shawn looks at you expectantly>', '', 130156, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Something is desperately wrong here. I fear my power alone will not be enough.', '', 130155, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, Prophet.', 'Yes, Prophet.', 130154, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you read to proceed, my friend?', '', 130153, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I- I cannot... see...', '', 130152, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Velen gasps for air.>', '', 130151, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Such terrible darkness!', '', 130150, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Velen cries out.>', '', 130149, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Such... darkness!', '', 130148, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Pained groan.>', '', 130147, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Acheon phetar, give me the clarity I seek. Show me where they are!', '', 130146, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Strained breathing.>', '', 130145, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I do not understand. Why can I not sense them?', '', 130144, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Half-heard prayers.>', '', 130143, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('May the Light guide my sight. Pheta vi acahachi.', '', 130142, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We leave the protection of the barrier behind. Remain on guard, my friend.', '', 130141, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ages ago I stood on this very spot and called the Draenei to me. It is here I will seek the other fragments.', '', 130139, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('With the Crown once more in our possession we can avoid the Xenedar\'s fate.', '', 130138, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My brothers abandoned their shards when Sargeras arrived. They are still here, in Mac\'Aree.', '', 130137, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Crown was a conduit. A unifying force. We each carried but one part of the whole.', '', 130136, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It certainly wasn\'t easy, but we were able to procure you a piece of equipment for your Champions of the highest quality.\n\nUnfortunately our supplies are extremely limited, so we must be careful with how many we pass out.', '', 130135, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Earthmother is with you, hero! Step within the circle of totems and obtain her blessing.', 'The Earthmother is with you, hero! Step within the circle of totems and obtain her blessing.', 130134, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('When you are ready to depart, Battlelord, this portal will return you to Skyhold.', '', 130133, 0, 0, 0, 70, 0, 83747, 0, 0, 0, 0, 0, 0, 0, 39653),
('REAVER HAS ARRIVED', 'REAVER HAS ARRIVED', 130129, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Kick! Punch! Burn!', '', 130128, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Actually, I\'d like to watch your show.', 'Actually, I\'d like to watch your show.', 130127, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Could you be quiet?', 'Could you be quiet?', 130126, 0, 0, 0, 64, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('WARNING: ENEMY DETECTED', 'WARNING: ENEMY DETECTED', 130125, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You again?\n\nLook, I don\'t come to your place and tell you how to $c, so why don\'t you just scram?', '', 130124, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I would like to look at your wares.', 'I would like to look at your wares.', 130123, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I only deal with the most elite gladiators.', 'I only deal with the most elite gladiators.', 130122, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'As you wish.', 130121, 0, 0, 1, 94, 0, 0, 112101, 0, 0, 0, 0, 0, 0, 39653),
('You will answer to her for your crimes against Kul Tiras.', '', 130120, 0, 0, 1, 94, 0, 111676, 0, 0, 0, 0, 0, 0, 0, 39653),
('We\'re taking you to Katherine, all right.', '', 130119, 0, 0, 1, 94, 0, 111675, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do... not... give in!', '', 130118, 0, 0, 0, 68, 0, 86129, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am. In no small part thanks to our friend here. But Alleria... there\'s something else.', '', 130117, 0, 0, 1, 68, 0, 86132, 0, 0, 0, 0, 0, 0, 0, 39653),
('Minions of the flame! Feast upon their flesh!', '', 130116, 0, 0, 0, 64, 0, 86128, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hey buddy, don\'t you know better than to interrupt a performer during his show?', '', 130115, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Culling the numbers of those vile worms helps restore the balance on these shores. You have my thanks, hero.', '', 130114, 0, 0, 0, 64, 0, 83677, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Dog\'s coat is gleaming, and it looks quite healthy. Breanni is clearly taking very good care of it.>\n\n<But how did it get here?>', '', 130113, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Show the stone from Dalaran\'s streets to the dog.>', '<Show the stone from Dalaran\'s streets to the dog.>', 130112, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Dog sniffs the stone and licks your hand reassuringly.>', '', 130111, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Dog wags its tail, trying very hard to stay seated and not jump on you. It\'s happy to see you again after so long.>', '', 130110, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Behold the triumph of the draenei--the Exodar!', '', 130109, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My artificers have been preparing for that for quite some time.', '', 130108, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('How will we get to Argus in one piece with the Legion bearing down on us like this?', '', 130107, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('L\'ura...', '', 130106, 0, 0, 603, 64, 0, 87898, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am ready.', 'I am ready.', 130105, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We have been waiting so long for this day.', '', 130104, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('My people have been waiting for this day.', '', 130103, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Just be careful, $n. Too many reinforcements from the Sentinax, and you might find yourself in a fight that you can\'t win...', 130102, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'However, if you\'re looking for a fight -- or, if you\'re looking for nethershards -- using these beacons might not be a bad idea.', 130101, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'These beacons send requests for backup directly to the Sentinax. That could be dangerous.', 130100, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Short talky moment where I laugh at Zul and demean him, tell my daughter she abandoned her post>', '', 130099, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ha! Smoked them! Will I be fired for this? One has to keep up one\'s spirits somehow. Well done, champion, as usual.', '', 130098, 0, 0, 0, 64, 0, 83679, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Legion seeks to extend its fiery reach. We would appreciate your aid in extinguishing this threat, commander.', '', 130097, 0, 0, 0, 64, 0, 83678, 0, 0, 0, 0, 0, 0, 0, 39653),
('You should know dat our king has survived one hundred and twenty three assassination attempts.$b$bDe heads of those who have tried now decorate de throne room.', '', 130096, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Use |TInterface\\Icons\\SPELL_SHADOW_ENSLAVEDEMON.BLP:20|t |cFFFF0000|Hspell:111771|h[Enslave Demon]|h|r to subdue the Wrathsteed!', 'Use |TInterface\\Icons\\spell_warlock_demonicportal_green.blp:20|t |cFFFF0000|Hspell:111771|h[Demonic Portal]|h|r to get past Ariden\'s barrier!', 130095, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We sent Minerva ahead to scout. Take the Death Gate and meet her in the citadel.', '', 130094, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Give yourself to the Legion.', 'Give yourself to the Legion.', 130092, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My soul for the power of the fel!', 'My soul for the power of the fel!', 130091, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I willingly serve the Legion.', 'I willingly serve the Legion.', 130090, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The naga will prevail...', 130089, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Legion promises us strength, greater than even Lady Azshara can provide!', 130088, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Severe the heads from their mortal bodies!', '', 130087, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Legion will never defeat us!', 130086, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We\'re under attack from the land and the sky, watch your head!', 130085, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m ready to face Sigryn. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'I\'m ready to face Sigryn. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 130084, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m ready to face Kruul. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'I\'m ready to face Kruul. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 130083, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m ready to face Raest. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'I\'m ready to face Raest. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 130082, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You be wantin\' to see da King? Well then, go ring the gong an we be sendin\' a proper challenge for you.', 130081, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m ready to take on Xylem. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'I\'m ready to take on Xylem. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 130080, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Take your blessing and begone. If you return your life be forfeit.', 130079, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take me to Agatha... |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Take me to Agatha... |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 130078, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take me to Agatha... (100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Take me to Agatha... (100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 130077, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let the shadows win!', '', 130076, 0, 0, 0, 64, 0, 83656, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'How be ol\' Vol\'jin these days? Dead I hear. Ah too bad. Some of us be havin\' dreams of killin\' him ourselves.', 130075, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Give in! Let it take you!', '', 130074, 0, 0, 0, 64, 0, 83659, 0, 0, 0, 0, 0, 0, 0, 39653),
('Fall into darkness!', '', 130073, 0, 0, 0, 64, 0, 83658, 0, 0, 0, 0, 0, 0, 0, 39653),
('Send me to Shadowsong. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'Send me to Shadowsong. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 130072, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Argus! My beloved homeworld... what have they done to you?', '', 130071, 0, 0, 0, 64, 0, 83661, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m ready to face Tugar Bloodtotem. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 'I\'m ready to face Tugar Bloodtotem. |cFFFF0000(100 Nethershards |TINTERFACE\\ICONS\\inv_datacrystal01.blp\n:16|t)', 130070, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Begin confrontation with Gharsul the Remorseless.', 'Begin confrontation with Gharsul the Remorseless.', 130069, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tonight we dine on mortal flesh!', '', 130068, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Greetings, $c. I must complete my research.\n\nWill you aid me?', 130067, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The naga must learn that any bargain made with the Legion will end in pain.', '', 130066, 0, 0, 0, 64, 0, 83605, 0, 0, 0, 0, 0, 0, 0, 39653),
('The leader of these naga has made a pact with the Legion, trading her people\'s lives for power. The fools go willingly, unaware of the price they must pay. Show them.', '', 130065, 0, 0, 0, 64, 0, 83604, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your souls will soon know oblivion!', '', 130064, 0, 0, 0, 64, 0, 83652, 0, 0, 0, 0, 0, 0, 0, 39653),
('Limitless destruction is at my command!', '', 130063, 0, 0, 0, 64, 0, 83651, 0, 0, 0, 0, 0, 0, 0, 39653),
('Feel the chaos consume you!', '', 130062, 0, 0, 0, 64, 0, 83650, 0, 0, 0, 0, 0, 0, 0, 39653),
('Slaughter the mortals and bring me their broken corpses!', '', 130061, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll get you to those ships, heroes! Take them out, before the Deceiver grows stronger!', '', 130060, 0, 0, 0, 64, 0, 83642, 0, 0, 0, 0, 0, 0, 0, 39653),
('Give up! There is still time to join us and serve the master!', '', 130059, 0, 0, 0, 64, 0, 83647, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your fate will be no different than all the rest!', '', 130058, 0, 0, 0, 64, 0, 83646, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Burning Legion has come for your souls!', '', 130057, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Every world that resisted us has fallen.', '', 130056, 0, 0, 0, 64, 0, 83645, 0, 0, 0, 0, 0, 0, 0, 39653),
('Velen\'s defiance so long ago paved the way for your downfall.', '', 130055, 0, 0, 0, 64, 0, 83644, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your lives are petty and insignificant! We are eternal!', '', 130054, 0, 0, 0, 64, 0, 83643, 0, 0, 0, 0, 0, 0, 0, 39653),
('We are ready to depart, Prophet Velen.', '', 130053, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Face your destiny!', '', 130052, 0, 0, 0, 64, 0, 83639, 0, 0, 0, 0, 0, 0, 0, 39653),
('Give in to your fears! Your desires!', '', 130051, 0, 0, 0, 64, 0, 83638, 0, 0, 0, 0, 0, 0, 0, 39653),
('Be careful, $ct. Demons are out there on the prowl.', 'Be careful, $ct. Demons are out there on the prowl.', 130050, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will cut you down myself!', '', 130049, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Who will share your fate?', '', 130048, 0, 0, 0, 64, 0, 83626, 0, 0, 0, 0, 0, 0, 0, 39653),
('Consume them all!', '', 130047, 0, 0, 0, 64, 0, 83624, 0, 0, 0, 0, 0, 0, 0, 39653),
('Smolder! Suffer!', '', 130046, 0, 0, 0, 64, 0, 83628, 0, 0, 0, 0, 0, 0, 0, 39653),
