('How can I help?', '', 127776, 0, 0, 0, 64, 0, 80748, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hello.', '', 127775, 0, 0, 0, 64, 0, 80747, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Silly me for thinking Roland was the annoying one.', 127774, 0, 0, 0, 64, 0, 0, 80746, 0, 0, 0, 0, 0, 0, 39653),
('', 'This will not end well for you.', 127773, 0, 0, 0, 64, 0, 0, 80745, 0, 0, 0, 0, 0, 0, 39653),
('', 'Begone from my sight!', 127772, 0, 0, 0, 64, 0, 0, 80744, 0, 0, 0, 0, 0, 0, 39653),
('', 'Shoo!', 127771, 0, 0, 0, 64, 0, 0, 80743, 0, 0, 0, 0, 0, 0, 39653),
('', 'Do you think yourself clever?', 127770, 0, 0, 0, 64, 0, 0, 80742, 0, 0, 0, 0, 0, 0, 39653),
('', 'You are testing my patience.', 127769, 0, 0, 0, 64, 0, 0, 80741, 0, 0, 0, 0, 0, 0, 39653),
('', 'Farewell.', 127768, 0, 0, 0, 64, 0, 0, 80740, 0, 0, 0, 0, 0, 0, 39653),
('', 'May the Shadows embrace you.', 127767, 0, 0, 0, 64, 0, 0, 80739, 0, 0, 0, 0, 0, 0, 39653),
('', 'Take care.', 127766, 0, 0, 0, 64, 0, 0, 80738, 0, 0, 0, 0, 0, 0, 39653),
