('Elune-adore.', '', 127742, 0, 0, 0, 64, 0, 80790, 0, 0, 0, 0, 0, 0, 0, 39653),
('Safe travels.', '', 127741, 0, 0, 0, 64, 0, 80789, 0, 0, 0, 0, 0, 0, 0, 39653),
('It is good to see you.', '', 127740, 0, 0, 0, 64, 0, 80788, 0, 0, 0, 0, 0, 0, 0, 39653),
('Greetings, friend.', '', 127739, 0, 0, 0, 64, 0, 80787, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ishnu-alah.', '', 127738, 0, 0, 0, 64, 0, 80786, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'If you will not honor me, then I will break you! Champion, help me put down this cur!', 127737, 0, 0, 0, 64, 0, 0, 82936, 0, 0, 0, 0, 0, 0, 39653),
('', 'So, you will not face me in single combat? The hallowed bones of our ancestors would balk at such dishonor!', 127736, 0, 0, 1, 64, 0, 0, 82935, 0, 0, 0, 0, 0, 0, 39653),
('Foolish girl. These bones answer to me, not your misguided honor!', '', 127735, 0, 0, 0, 64, 0, 82574, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will do what is asked of me.', '', 127734, 0, 0, 0, 64, 0, 80785, 0, 0, 0, 0, 0, 0, 0, 39653),
('I fight for the Highlord!', '', 127733, 0, 0, 0, 64, 0, 80784, 0, 0, 0, 0, 0, 0, 0, 39653),
('You must continue on without me.', '', 127732, 0, 0, 0, 64, 0, 80783, 0, 0, 0, 0, 0, 0, 0, 39653),
('I require a moment\'s rest.', '', 127731, 0, 0, 0, 64, 0, 80782, 0, 0, 0, 0, 0, 0, 0, 39653),
('My spirit weakens...', '', 127730, 0, 0, 0, 64, 0, 80781, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our will is strong.', '', 127729, 0, 0, 0, 64, 0, 80780, 0, 0, 0, 0, 0, 0, 0, 39653),
('We will prevail.', '', 127728, 0, 0, 0, 64, 0, 80779, 0, 0, 0, 0, 0, 0, 0, 39653),
('Judgment must be swift and true.', '', 127727, 0, 0, 0, 64, 0, 80778, 0, 0, 0, 0, 0, 0, 0, 39653),
