INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('What do you need?', '', 121135, 0, 0, 0, 64, 0, 70342, 0, 0, 0, 0, 0, 0, 0, 39653),
('Okay, that\'s it. I\'m puttin\' a contract out on your head.', '', 121134, 0, 0, 0, 64, 0, 70341, 0, 0, 0, 0, 0, 0, 0, 39653),
('Maybe you\'d prefer some of my goons rough you up?', '', 121133, 0, 0, 0, 64, 0, 70340, 0, 0, 0, 0, 0, 0, 0, 39653),
('I don\'t have to take this. I\'m the Baron of Gadgetzan.', '', 121132, 0, 0, 0, 64, 0, 70339, 0, 0, 0, 0, 0, 0, 0, 39653),
('Amateur!', '', 121131, 0, 0, 0, 64, 0, 70338, 0, 0, 0, 0, 0, 0, 0, 39653),
('I don\'t have time for this!', '', 121130, 0, 0, 0, 64, 0, 70337, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yeah, very funny.', '', 121129, 0, 0, 0, 64, 0, 70336, 0, 0, 0, 0, 0, 0, 0, 39653),
('You scratch my back, I\'ll pay someone to scratch yours.', '', 121128, 0, 0, 0, 64, 0, 70335, 0, 0, 0, 0, 0, 0, 0, 39653),
('All\'s fair in love and business.', '', 121127, 0, 0, 0, 64, 0, 70334, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hurry back.', '', 121126, 0, 0, 0, 64, 0, 70333, 0, 0, 0, 0, 0, 0, 0, 39653),
('Keep it real.', '', 121125, 0, 0, 0, 64, 0, 70332, 0, 0, 0, 0, 0, 0, 0, 39653),
('Heh, heh, glad I could help.', '', 121124, 0, 0, 0, 64, 0, 70331, 0, 0, 0, 0, 0, 0, 0, 39653),
('Can\'t you see I\'m busy here?', '', 121123, 0, 0, 0, 64, 0, 70330, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wassup?', '', 121122, 0, 0, 0, 64, 0, 70329, 0, 0, 0, 0, 0, 0, 0, 39653),
('Talk to me.', '', 121121, 0, 0, 0, 64, 0, 70328, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yo!', '', 121120, 0, 0, 0, 64, 0, 70327, 0, 0, 0, 0, 0, 0, 0, 39653),
('Time is money, friend.', '', 121119, 0, 0, 0, 64, 0, 70326, 0, 0, 0, 0, 0, 0, 0, 39653),
('I can still feel their claws in my mind.', '', 121118, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wha... What trickery is this?! Was it all in my head?', '', 121117, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bees! I saw bees everywhere! Aaahh!', '', 121116, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('No! No more!', '', 121115, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gaahh! They made me watch my tribe be slaughtered... over and over! Was it all a dream?', '', 121114, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thank you! I could not have lasted much longer!', '', 121113, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It\'s not here. Those beasts must have dragged it into the cave. The search continues!', '', 121111, 0, 0, 0, 64, 0, 70807, 0, 0, 0, 0, 0, 0, 0, 39653),
('Throw Rock now causes enemies to bleed!', 'Throw Rock now causes enemies to bleed!', 121110, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Withered damage increased!', 'Withered damage increased!', 121109, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Unseen Path will return to our calling of helping those who need it most.', 121108, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I miss my wife, and moreso our daughter.\n\nHere, at least, I can remember them in peace.', '', 121107, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This place is... quaint.\n\n<Sylverin adjusts his cuffs>\n\nBut I prefer it to losing my life.\n\nI suppose I ought to thank you, for taking action. I was a coward, but at least Margaux\'s death did not go unanswered.\n\nI am indebted to you.', '', 121106, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There it is! Land at the shoreline and investigate!', '', 121105, 0, 0, 0, 64, 0, 70814, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am doing panda dance!', '', 121104, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Grah!', '', 121103, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bra - hah! Hahah!', '', 121102, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s laughs!', 121101, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Now do a little shuffle. Like this.', 121100, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'No no, put your hands up, like little ears. Like this!', 121099, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Okay, now, try this...', 121098, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Nexus Vault lies deep beneath the main spire. You will find its entrance in the lowest chamber of the spire\'s base.', '', 121097, 0, 0, 0, 64, 0, 70512, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Light will prevail.', '', 121096, 0, 0, 1, 64, 0, 70272, 0, 0, 0, 0, 0, 0, 0, 39653),
('May the Light guide you.', '', 121095, 0, 0, 1, 64, 0, 70271, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Light endures.', '', 121094, 0, 0, 1, 64, 0, 72111, 0, 0, 0, 0, 0, 0, 0, 39653),
('How can I be of service?', '', 121093, 0, 0, 6, 64, 0, 70270, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am Light incarnate.', '', 121092, 0, 0, 1, 64, 0, 72109, 0, 0, 0, 0, 0, 0, 0, 39653),
('I defend the Light.', '', 121091, 0, 0, 1, 64, 0, 72110, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Don\'t make me do something we\'ll both regret.', 121090, 0, 0, 1, 64, 0, 0, 70257, 0, 0, 0, 0, 0, 0, 39653),
('', 'This needs to stop.', 121089, 0, 0, 1, 64, 0, 0, 70256, 0, 0, 0, 0, 0, 0, 39653),
('', 'Where are your manners?', 121088, 0, 0, 6, 64, 0, 0, 70255, 0, 0, 0, 0, 0, 0, 39653),
('', 'You\'re persistent, aren\'t you?', 121087, 0, 0, 6, 64, 0, 0, 70254, 0, 0, 0, 0, 0, 0, 39653),
('', 'What more do you want from me?', 121086, 0, 0, 6, 64, 0, 0, 70253, 0, 0, 0, 0, 0, 0, 39653),
('', 'Haven\'t I suffered enough?', 121085, 0, 0, 6, 64, 0, 0, 70252, 0, 0, 0, 0, 0, 0, 39653),
('', 'You have my attention.', 121084, 0, 0, 1, 64, 0, 0, 70251, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will be redeemed.', 121083, 0, 0, 1, 64, 0, 0, 70250, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will atone.', 121082, 0, 0, 1, 64, 0, 0, 70249, 0, 0, 0, 0, 0, 0, 39653),
('', 'May the Light shine upon you.', 121081, 0, 0, 1, 64, 0, 0, 70248, 0, 0, 0, 0, 0, 0, 39653),
('', '%s glares at $n disapprovingly.', 121080, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'How can I help?', 121079, 0, 0, 6, 64, 0, 0, 70247, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hello.', 121078, 0, 0, 1, 64, 0, 0, 70246, 0, 0, 0, 0, 0, 0, 39653),
('', 'Yes?', 121077, 0, 0, 6, 64, 0, 0, 70245, 0, 0, 0, 0, 0, 0, 39653),
('', 'Silence!', 121076, 0, 0, 603, 64, 0, 0, 70269, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ll send you into the void!', 121075, 0, 0, 603, 64, 0, 0, 70268, 0, 0, 0, 0, 0, 0, 39653),
('', 'Will this ever end?', 121074, 0, 0, 1, 64, 0, 0, 70267, 0, 0, 0, 0, 0, 0, 39653),
('', 'You\'re trying my patience.', 121073, 0, 0, 1, 64, 0, 0, 70266, 0, 0, 0, 0, 0, 0, 39653),
('', 'I don\'t have time for your games.', 121072, 0, 0, 1, 64, 0, 0, 70265, 0, 0, 0, 0, 0, 0, 39653),
('', 'You have my attention.', 121071, 0, 0, 1, 64, 0, 0, 70264, 0, 0, 0, 0, 0, 0, 39653),
('', 'Farewell.', 121070, 0, 0, 1, 64, 0, 0, 70263, 0, 0, 0, 0, 0, 0, 39653),
('', 'The shadows will rise again.', 121069, 0, 0, 1, 64, 0, 0, 70262, 0, 0, 0, 0, 0, 0, 39653),
('', 'Embrace the shadows.', 121068, 0, 0, 1, 64, 0, 0, 70261, 0, 0, 0, 0, 0, 0, 39653),
('', 'Well met.', 121067, 0, 0, 1, 64, 0, 0, 70260, 0, 0, 0, 0, 0, 0, 39653),
('', 'Greetings.', 121066, 0, 0, 1, 64, 0, 0, 70259, 0, 0, 0, 0, 0, 0, 39653),
('', 'Can I help you?', 121065, 0, 0, 6, 64, 0, 0, 70258, 0, 0, 0, 0, 0, 0, 39653),
('Our boats are burning! Help!', 'Our boats are burning! Help!', 121064, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Guards, stop this insanity! What do we pay you for?', 'Guards, stop this insanity! What do we pay you for?', 121063, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Help! Guards! There\'s an arsonist on the loose!', 'Help! Guards! There\'s an arsonist on the loose!', 121062, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It was difficult to get Grash into the cavern here. I\'m not sure the other shaman appreciate him like we do.', 121061, 0, 0, 0, 64, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Don\'t do that!', 'Don\'t do that!', 121060, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('...sure.', '...sure.', 121059, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Grash lowers his head sadly.>$b$bOkay.', '', 121058, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Your answer makes the sea giant very happy.>$b$b<Wavespeaker Adelee gawps at you.>', '', 121057, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n! You are my friend!$b$bNext time Grash grabs a big people-ship from under the water and splits it open and all the people spill out into the sea I will yell at them \"$N IS BEST SHAMAN HA HA HA!\"', '', 121056, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Maybe that will open their eyes to the suffering around them.', '', 121055, 0, 0, 0, 64, 0, 70913, 0, 0, 0, 0, 0, 0, 0, 39653),
('The elites in this city revel in excess, while ordinary people suffer and die. Meet my associate Eo\'vyn in Astravar Harbor and put an end to the party.', '', 121054, 0, 0, 0, 64, 0, 70912, 0, 0, 0, 0, 0, 0, 0, 39653),
('Run! They have weapons!', 'Run! They have weapons!', 121053, 0, 0, 0, 64, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Intruders!', 'Intruders!', 121052, 0, 0, 0, 64, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('How did you get in here?', 'How did you get in here?', 121051, 0, 0, 0, 64, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('You\'re not welcome here!', 'You\'re not welcome here!', 121050, 0, 0, 0, 64, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Outsiders!', 'Outsiders!', 121049, 0, 0, 0, 64, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Here comes, $n... check out those shades!', 'Here comes, $n... check out those shades!', 121048, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Looking good, $n!', 'Looking good, $n!', 121047, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Damn, $n! Back at it again with the sweet shades!', 'Damn, $n! Back at it again with the sweet shades! Nice!', 121046, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wow! Nice shades, $n!', 'Wow! Nice shades, $n!', 121045, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Welcome to The Gnarled Branch! Feel free to browse or speak with me if you\'re looking for anything in specific.', 121044, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n is entering the rumble to prove their might!', '$n is entering the rumble to prove their might!', 121043, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our next rumbler has tested their might over the years on the battlefields.  $n has become a Hero of the Alliance during $12383W seasons!', 'Our next rumbler has tested their might over the years on the battlefields.  $n has become a Hero of the Alliance during $12383W seasons!', 121042, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our next rumbler has tested their might over the years on the battlefields.  $n has become a Hero of the Horde during $12383W seasons!', 'Our next rumbler has tested their might over the years on the battlefields.  $n has become a Hero of the Horde during $12383W seasons!', 121041, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Those blades should be mine! Do not think I will go easy on you!', '', 121040, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Amazing! Ancient Highborne ruins litter the landscape. And there along the coast, it looks to be a vrykul settlement! Fascinating.', '', 121039, 0, 0, 0, 64, 0, 70813, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I pledge my loyalty to you, and to the Unseen Path, for all my days.', 121038, 0, 0, 1, 64, 0, 0, 70476, 0, 0, 0, 0, 0, 0, 39653),
('I should have slaughtered you and your malformed brethren long ago.', '', 121037, 0, 0, 0, 94, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Combatants!  Put your hands together to welcome a $12383W-time Gladiator, $n!.', 'Combatants!  Put your hands together to welcome a $12383W-time Gladiator, $n!.', 121036, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Look there, to the north, $n! Gaze upon the Nighthold of Suramar! What secrets are kept inside?', '', 121035, 0, 0, 0, 64, 0, 70812, 0, 0, 0, 0, 0, 0, 0, 39653),
('Akama. Your duplicity is hardly surprising.', '', 121034, 0, 0, 0, 94, 0, 11463, 0, 0, 0, 0, 0, 0, 0, 39653),
('As with those that came before me, I pledge my service to you and the Unseen Path.', '', 121033, 0, 0, 1, 64, 0, 70475, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re a fine addition to my huntin\' party!', '', 121032, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('The vrykul here tell stories of an unrelenting warrior carving through Stormheim with golden blades. I wonder who that could be?', '', 121030, 0, 0, 1, 64, 0, 71465, 0, 0, 0, 0, 0, 0, 0, 39653),
('The shield bearer arrives at an hour of great need. You will need its strength.', '', 121029, 0, 0, 1, 64, 0, 71466, 0, 0, 0, 0, 0, 0, 0, 39653),
('To stay focused and heal one\'s allies even in the midst of battle - there be no greater honor and no greater challenge for a shaman.$b$bIf you seek to practice your skills as a battle-mender, there be training dummies here in this chamber.$b$bShould you wish to retrain your skills, speak with Tribemother Torra nearby. She has lived through darkness and seen the light.', '', 121028, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Somewhere in those murky waters is our mysterious object. Time to get your feet wet, $n.', '', 121027, 0, 0, 0, 64, 0, 70808, 0, 0, 0, 0, 0, 0, 0, 39653),
('For years I watched and waited at the base of the Alterac Mountains, speaking only to the spirits and forging mighty weapons from elemental power.$b$bI know the whims of the spirits. I know that one\'s destiny can be guided and shaped, if one is willing to make the sacrifice for it.$b$b$ct, build up this sacred space, and I promise to give you the power to shape your own fate.$b$bUntil then, I watch. I wait.', '', 121026, 0, 0, 0, 64, 0, 0, 0, 1, 25, 0, 0, 0, 0, 39653),
('Enough!', '', 121025, 0, 0, 396, 64, 0, 71256, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'He said that the letter was written in an advanced code that will not easily be broken.', 121024, 0, 0, 396, 64, 0, 0, 71258, 0, 0, 0, 0, 0, 0, 39653),
('', 'T\' t\'..t\' plank?', 121023, 0, 0, 396, 64, 0, 0, 70994, 0, 0, 0, 0, 0, 0, 39653),
('', 'Translation please? I cannot understand his incessant pirate gibberish.', 121022, 0, 0, 396, 64, 0, 0, 70993, 0, 0, 0, 0, 0, 0, 39653),
('Ye best watch yer tongue lass or ye\'ll be makin\' a trip t\' t\' plank!', '', 121021, 0, 0, 396, 64, 0, 71257, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do ye know who I be, laddie?', '', 121020, 0, 0, 396, 64, 0, 71259, 0, 0, 0, 0, 0, 0, 0, 39653),
('The spirits be kind, $ct. With the right offerin\', they can be findin\' you some valuable items.', 'The spirits be kind, $ct. With the right offerin\', they can be findin\' you some valuable items.', 121019, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
