('', 'Use Flametongue!', 118173, 0, 0, 0, 64, 0, 0, 65316, 0, 0, 0, 0, 0, 0, 39653),
('', 'Lava Lash is available! Use it now!', 118172, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Use Lava Lash!', 118171, 0, 0, 0, 64, 0, 0, 65314, 0, 0, 0, 0, 0, 0, 39653),
('', 'You have maximum Maelstrom. Use Lava Lash!', 118170, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Use Rockbiter to generate Maelstrom!', 118169, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Use Rockbiter!', 118168, 0, 0, 0, 64, 0, 0, 65311, 0, 0, 0, 0, 0, 0, 39653),
('', 'Stormbringer has triggered! Use Stormstrike now!', 118167, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Use Stormstrike!', 118166, 0, 0, 0, 64, 0, 0, 65309, 0, 0, 0, 0, 0, 0, 39653),
('', 'You share a kinship with animal spirits such as wolves.', 118165, 0, 0, 0, 64, 0, 0, 65308, 0, 0, 0, 0, 0, 0, 39653),
('', 'Should you find yourself in trouble during combat, you can summon two feral wolf spirits to fight at your side.', 118164, 0, 0, 0, 64, 0, 0, 65307, 0, 0, 0, 0, 0, 0, 39653),
