('Great, you have the parts! Just give them to XR9-47 so he can bring them to me.', '', 117063, 0, 0, 1, 64, 0, 66813, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ahhh... Much better!', '', 117062, 0, 0, 603, 64, 0, 0, 0, 603, 0, 0, 0, 0, 0, 39653),
('She will not get away with this!', '', 117061, 0, 0, 0, 64, 0, 68099, 0, 1, 0, 0, 0, 0, 0, 39653),
('She\'s getting away!', '', 117060, 0, 0, 0, 64, 0, 67682, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Enjoy your victory while it lasts. The Legion will tear this world asunder!', 117059, 0, 0, 0, 64, 0, 0, 68610, 0, 0, 0, 0, 0, 0, 39653),
('', 'Enough! I grow weary of you.', 117058, 0, 0, 0, 64, 0, 0, 68609, 0, 0, 0, 0, 0, 0, 39653),
('', 'This chamber... I have never seen anything like it.', 117057, 0, 0, 0, 64, 0, 0, 67383, 0, 0, 0, 0, 0, 0, 39653),
('You found them! I will have them properly preserved and sent somewhere safe immediately.', '', 117056, 0, 0, 603, 64, 0, 66257, 0, 0, 0, 0, 0, 0, 0, 39653),
('Would you like see the temple, say, from the outside?', '', 117055, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Please don\'t smudge me.', '', 117054, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Careful, I can be sharp.', '', 117053, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Goodbye.', '', 117052, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Light reveal your path.', '', 117051, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Walk in light.', '', 117050, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Can the naaru aid you?', '', 117049, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will help you.', '', 117048, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('In the Light we are reborn.', '', 117047, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will take this opportunity to lay traps for the intruders. I am certain we will meet again!', '', 117046, 0, 0, 0, 64, 0, 66360, 0, 0, 0, 0, 0, 0, 0, 39653),
('You look young enough to use this fancy thing. Can you make it work for me?', 'You look young enough to use this fancy thing. Can you make it work for me?', 117044, 0, 0, 0, 64, 0, 65742, 65949, 0, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('I bought this off of a scout patrol. He called it a \"S.E.L.F.I.E. Camera?\" Any idea what that is?', 'I bought this off of a scout patrol. He called it a \"S.E.L.F.I.E. Camera?\" Any idea what that is?', 117043, 0, 0, 0, 64, 0, 65745, 65935, 0, 0, 0, 0, 0, 0, 39653),
