('', 'Come again soon!', 116565, 0, 0, 0, 64, 0, 0, 66310, 0, 0, 0, 0, 0, 0, 39653),
('', 'I hope you enjoyed yourself.', 116564, 0, 0, 0, 64, 0, 0, 66309, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thank you for your visit!', 116563, 0, 0, 0, 64, 0, 0, 66308, 0, 0, 0, 0, 0, 0, 39653),
('', 'We craft only the finest wines.', 116562, 0, 0, 0, 64, 0, 0, 66307, 0, 0, 0, 0, 0, 0, 39653),
('', 'Are you enjoying your stay?', 116561, 0, 0, 0, 64, 0, 0, 66306, 0, 0, 0, 0, 0, 0, 39653),
('', 'It is a great honor to look after the vineyard.', 116560, 0, 0, 0, 64, 0, 0, 66305, 0, 0, 0, 0, 0, 0, 39653),
('', 'I don\'t like your face!', 116559, 0, 0, 0, 64, 0, 0, 66234, 0, 0, 0, 0, 0, 0, 39653),
('', 'No!', 116558, 0, 0, 0, 64, 0, 0, 66233, 0, 0, 0, 0, 0, 0, 39653),
('', 'Go away.', 116557, 0, 0, 0, 64, 0, 0, 66232, 0, 0, 0, 0, 0, 0, 39653),
('', 'Bye-bye.', 116556, 0, 0, 0, 64, 0, 0, 66231, 0, 0, 0, 0, 0, 0, 39653),
('', 'Bye.', 116555, 0, 0, 0, 64, 0, 0, 66230, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hello?', 116554, 0, 0, 0, 64, 0, 0, 66229, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hi...', 116553, 0, 0, 0, 64, 0, 0, 66228, 0, 0, 0, 0, 0, 0, 39653),
('Do you see anyone else hanging around? No? Why do you think that is?', '', 116552, 0, 0, 0, 64, 0, 66206, 0, 0, 0, 0, 0, 0, 0, 39653),
('My time isn\'t free.', '', 116551, 0, 0, 0, 64, 0, 66205, 0, 0, 0, 0, 0, 0, 0, 39653),
('I don\'t give tours. The vineyards are across town.', '', 116550, 0, 0, 0, 64, 0, 66204, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t linger. You\'ll regret it.', '', 116549, 0, 0, 0, 64, 0, 66203, 0, 0, 0, 0, 0, 0, 0, 39653),
('Watch your back.', '', 116548, 0, 0, 0, 64, 0, 66202, 0, 0, 0, 0, 0, 0, 0, 39653),
('Move along.', '', 116547, 0, 0, 0, 64, 0, 66201, 0, 0, 0, 0, 0, 0, 0, 39653),
('State your business.', '', 116546, 0, 0, 0, 64, 0, 66200, 0, 0, 0, 0, 0, 0, 0, 39653),
('Menagerie\'s that way.', '', 116545, 0, 0, 0, 64, 0, 66199, 0, 25, 0, 0, 0, 0, 0, 39653),
('Are you lost?', '', 116544, 0, 0, 0, 64, 0, 66198, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It will be easier for me to travel on the road.', 116542, 0, 0, 0, 64, 0, 0, 65938, 0, 0, 0, 0, 0, 0, 39653),
('They... promised...', '', 116540, 0, 0, 0, 64, 0, 66336, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will not be defeated by the likes of you!', '', 116539, 0, 0, 0, 64, 0, 66335, 0, 0, 0, 0, 0, 0, 0, 39653),
('Kneel before the might of the shal\'dorei!', '', 116538, 0, 0, 0, 64, 0, 66334, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Legion brings us power unending!', '', 116537, 0, 0, 0, 64, 0, 66333, 0, 0, 0, 0, 0, 0, 0, 39653),
('A challenger? Don\'t make me laugh!', '', 116536, 0, 0, 0, 64, 0, 66332, 0, 0, 0, 0, 0, 0, 0, 39653),
('I was... framed...', '', 116535, 0, 0, 0, 64, 0, 66221, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will have what is owed me!', '', 116534, 0, 0, 0, 64, 0, 66220, 0, 0, 0, 0, 0, 0, 0, 39653),
('You cannot match me! I am your better!', '', 116533, 0, 0, 0, 64, 0, 66217, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will wrestle my title from your champion\'s lifeless hands, Ly\'leth!', '', 116532, 0, 0, 0, 64, 0, 66216, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take me with you.  Please!', '', 116531, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Fishing? ...Really?!', '', 116530, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Horde! Fan out! Today we focus our attacks against the Legion. We\'ll deal with the Alliance scum when this is through.', '', 116529, 1, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is not what I signed up for.', '', 116528, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Looks like you caught some drowned mana? I can take that off your hands...', 'Looks like you caught some drowned mana? I can take that off your hands...', 116527, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have 10 drowned mana for you.', 'I have 10 drowned mana for you.', 116526, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will reclaim my honor! I invoke the ancient rite- Tal\'ashar!', '', 116524, 0, 0, 603, 64, 0, 66219, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let us hope this ends swiftly.', '', 116522, 1, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your star fades!', '', 116521, 0, 0, 0, 64, 0, 65733, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ash\'thoras denil.', '', 116520, 0, 0, 0, 64, 0, 65653, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My lord, you have lost your sense of decorum. It is already decided.', 116519, 0, 0, 1, 64, 0, 0, 66265, 0, 0, 0, 0, 0, 0, 39653),
('You impinge upon my honor! You besmirch my name with baseless accusations!', '', 116518, 0, 0, 603, 64, 0, 66214, 0, 0, 0, 0, 0, 0, 0, 39653),
('Filthy backstabbing cretin! That title should have been mine!', '', 116517, 0, 0, 603, 64, 0, 66215, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Yes. I understand. Just be careful. We\'re running out of room here.', 116516, 1, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('', 'I humbly accept this appointment. It is an honor beyond words.', 116515, 0, 0, 0, 64, 0, 0, 66267, 0, 0, 0, 0, 0, 0, 39653),
('', 'You are not the only one with a nose for politics.', 116514, 0, 0, 0, 64, 0, 0, 66266, 0, 0, 0, 0, 0, 0, 39653),
('I like the way you think, Lunastre.', '', 116513, 0, 0, 0, 64, 0, 66190, 0, 0, 0, 0, 0, 0, 0, 39653),
('I accept your gratitude, by the way!', '', 116512, 0, 0, 603, 64, 0, 66189, 0, 0, 0, 0, 0, 0, 0, 39653),
('I... will go home. I have no business among such esteemed individuals.', '', 116511, 0, 0, 1, 64, 0, 66188, 0, 0, 0, 0, 0, 0, 0, 39653),
('Walk in the moonlight.', '', 116510, 0, 0, 0, 64, 0, 65732, 0, 0, 0, 0, 0, 0, 0, 39653),
('Walk in the moonlight.', 'Walk in starlight.', 116509, 0, 0, 0, 64, 0, 65732, 65936, 0, 0, 0, 0, 0, 0, 39653),
('Apologies. I\'m not much for fighting, but I\'m sure Craig and Hans will be more than helpful.', '', 116508, 1, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'This place is crawling. See if you can find the eye. I will cover you from here.', 116507, 0, 0, 0, 64, 0, 0, 69484, 0, 0, 0, 0, 0, 0, 39653),
('In the name of the Dark Lady, rise and defend against the Burning Legion!', '', 116506, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will see you at Ravencourt. Make certain that you are not followed.', 116505, 0, 0, 0, 64, 0, 0, 69483, 0, 0, 0, 0, 0, 0, 39653),
('', 'I do not know how you are going to get onto the Naglfar... the vrykul ship of the dead. But, if we are to confirm my suspicions about the item, you are going to have to find a way to do so. Preferably without dying if you can manage it.', 116504, 0, 0, 0, 64, 0, 0, 69482, 0, 0, 0, 0, 0, 0, 39653),
('I can control it no longer. You must drown!', '', 116503, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I am going to look into something. In the meantime, let us make certain that SI:7 does not catch on to what we are really up to.', 116502, 0, 0, 0, 64, 0, 0, 69481, 0, 0, 0, 0, 0, 0, 39653),
('Avoid taking any damage for as long as you can while staying inside the field.  Good Luck!', 'Avoid taking any damage for as long as you can while staying inside the field.  Good Luck!', 116501, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Rise up, $n! Fight beside Helcular to bring down this Legion threat! Show them the true power of a $c!', '', 116500, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'This place is a haunted tomb. Let us not stay here any longer than is necessary.', 116499, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Show them we\'re not giving up Tarren Mill without a fight!', 116498, 1, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thanks. I left some fresh cuts lying about, but I should get going. I\'m afraid those things would butcher me alive.', '', 116497, 1, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is no place for a tradesman!', '', 116496, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'There\'s a few potions and supplies left about. Do what you must to remove the threat!', 116495, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We work in the shadows.', 'We work in the shadows.', 116494, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The seas be calling!', 'The seas be calling!', 116493, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Follow the path to the end of the maze.', 'Follow the path to the end of the maze.', 116492, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thanks to you, most of our people have returned safely to the Vault of Lights! The time has come to focus your attention on the remaining fel portals and end Rakeesh\'s incursion!', '', 116491, 0, 0, 0, 64, 0, 70899, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have destroyed most of the fel portals, greatly hindering Rakeesh\'s ability to bring in reinforcements. Focus your attention on finding survivors now!', '', 116490, 0, 0, 0, 64, 0, 70898, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hmm... yes, I see. This entry clearly speaks of a void terror. It must have consumed the Eye in the Twisting Nether. Its purpose here is irrelevant. Quickly, let us get to Baradin Hold!', '', 116489, 0, 0, 0, 64, 0, 66452, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oops! You\'ve stepped off of the path!', 'Oops! You\'ve stepped off of the path!', 116488, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There! The unquiet dead bar our path. Get that spirit out of my way, will you?', '', 116487, 0, 0, 0, 64, 0, 66451, 0, 1, 0, 0, 0, 0, 0, 39653),
('I can sense... unrest nearby. Let us investigate. Come along!', '', 116486, 0, 0, 0, 64, 0, 66450, 0, 1, 0, 0, 0, 0, 0, 39653),
('Congratulations, you\'ve successfully navigated the maze!', 'Congratulations, you\'ve successfully navigated the maze!', 116485, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Came up empty? No Nagaz either, I see. Not to worry, we all know how the lower echelons of our group scramble for position. Enough nonsense. What we seek is here!', '', 116484, 0, 0, 0, 64, 0, 66449, 0, 1, 0, 0, 0, 0, 0, 39653),
('The Legion will conquer this world!', '', 116483, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Enjoy your stay in Ulduar! Please remember to fill out a Visitor Satisfaction Survey prior to departing.', '', 116482, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Unfortunately, the walkway is undergoing structural evaluation and is presently inaccessible. We regret any inconvenience this may cause.', '', 116481, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Have a pleasant stay in Ulduar!', '', 116480, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Currently both facilities are closed for cleaning and routine maintenance. Please call again on a future date.', '', 116479, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thank you for your interest in visiting the Observation Ring!', '', 116478, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thank you for your interest in visiting the Assembly of Iron and the Archivum!', '', 116477, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The winds swirl in a new direction, adjust your aim to compensate.', 'The winds swirl in a new direction, adjust your aim to compensate.', 116476, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Lord Kur\'talos Ravencrest stole the eye from the vrykul millennia ago. His lieutenant\'s used it during the War of the Ancients.', 116475, 0, 0, 273, 64, 0, 0, 69480, 0, 0, 0, 0, 0, 0, 39653),
('', 'Exactly right. We are talking about the end of secrets. Well, other people\'s secrets anyway.', 116474, 0, 0, 574, 64, 0, 0, 69479, 0, 0, 0, 0, 0, 0, 39653),
('A merry yarn! But that\'s all she be. The Raven\'s Eye don\'t exist. It never did. It just be some ol\' wives\' tale to scare little rogues who are wantin\' to keep their secrets hidden.', '', 116473, 0, 0, 274, 64, 0, 69478, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'But more to the point, the Raven\'s Eye will give us the means to unlock the secrets hidden in the SI:7 letter. And, we know where it is.', 116472, 0, 0, 1, 64, 0, 0, 69477, 0, 0, 0, 0, 0, 0, 39653),
('', 'The legend is that the gem conveys the power to read any language, follow any map, and most importantly, to decipher any code.', 116471, 0, 0, 6, 64, 0, 0, 69476, 0, 0, 0, 0, 0, 0, 39653),
('', 'It is of a jewel so powerful that no one believes it exists. But I assure you, it does.', 116470, 0, 0, 273, 64, 0, 0, 69475, 0, 0, 0, 0, 0, 0, 39653),
('The others look incredulously at Valeera. Disbelief clearly painted on their faces. Unsurprised, Valeera continues on with her tale.', 'The others look incredulously at Valeera. Disbelief clearly painted on their faces. Unsurprised, Valeera continues on with her tale.', 116469, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Surely everyone here has at one time or another heard the tale of the Raven\'s Eye?', 116468, 0, 0, 6, 64, 0, 0, 69474, 0, 0, 0, 0, 0, 0, 39653),
('', 'There is a myth, a fable, that is whispered of in dark corners and back alleys.', 116467, 0, 0, 1, 64, 0, 0, 69473, 0, 0, 0, 0, 0, 0, 39653),
('', 'As you command, Prophet!', 116466, 0, 0, 0, 64, 0, 0, 70817, 0, 0, 0, 0, 0, 0, 39653),
('', 'We came as soon as we were able! Thank the Light that you are safe, prophet!', 116465, 0, 0, 0, 64, 0, 0, 70816, 0, 0, 0, 0, 0, 0, 39653),
('I\'m done training the withered for today.', 'I\'m done training the withered for today.', 116463, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Vanessa gives you a final look and then walks off.', 116462, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Feel my wrath, fiends!', '', 116461, 0, 0, 0, 64, 0, 68100, 0, 1, 0, 0, 0, 0, 0, 39653),
('The people of Thunder Totem welcome the wielder of Talonclaw!', 'The people of Thunder Totem welcome the wielder of Talonclaw!', 116460, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I should be... the one... at Gul\'dan\'s side...', '', 116459, 0, 0, 0, 64, 0, 66448, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll have that book now... and you\'ll be having a little \"accident\"!', '', 116458, 0, 0, 0, 64, 0, 66447, 0, 0, 0, 0, 0, 0, 0, 39653),
('Anyway, follow me! There\'s something over here I... need your help with.', '', 116457, 0, 0, 0, 64, 0, 66446, 0, 1, 0, 0, 0, 0, 0, 39653),
('Found Tyranis too late, did you? Pity...', '', 116456, 0, 0, 0, 64, 0, 66445, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It is fitting that the bow be in the hands of so skilled a marksman. I trust you will remain worthy of it. Do not disappoint me.', 116455, 0, 0, 0, 64, 0, 0, 66821, 0, 0, 0, 0, 0, 0, 39653),
('', 'Remember, $n, that Thas\'dorah represents my family\'s legacy... MY legacy. The deeds you perform while wielding it reflect upon me.', 116454, 0, 0, 0, 64, 0, 0, 66820, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your destiny lies within my pearl, $R!', 116453, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Peer into my pearl, landwalker!', 116452, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'If you won\'t serve the Queen, then you will die!', 116451, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'If you won\'t serve the Queen, then you will die!', 116450, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My mother passed it down to my eldest sister. May it bring you better fortune than it did her.', 116449, 0, 0, 0, 64, 0, 0, 66819, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thas\'dorah... I have not seen it in years! That\'s a Windrunner family heirloom you have slung across your back.', 116448, 0, 0, 0, 64, 0, 0, 66818, 0, 0, 0, 0, 0, 0, 39653),
('It\'s so shiny. I couldn\'t help myself.', '', 116447, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Get away from there!', '', 116446, 0, 0, 0, 64, 0, 67233, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have come to help Ly\'leth destroy our family! Be gone!', '', 116445, 0, 0, 397, 64, 0, 67234, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ngh! Who ARE you?!', '', 116444, 0, 0, 0, 64, 0, 67235, 0, 0, 0, 0, 0, 0, 0, 39653),
('Just... finish me off.', '', 116443, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('She wants to preach her traitorous ideals to me further? Fine. Let us go.', '', 116442, 0, 0, 0, 64, 0, 67236, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hmph... Someone will notice I am missing! They will come looking for me!', '', 116441, 0, 0, 0, 64, 0, 67237, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will hear no more of your scheming! You endanger everything our father worked for!', '', 116440, 0, 0, 0, 64, 0, 67503, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Ebon order is at your command.', 'The Ebon order is at your command.', 116439, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t worry about us, just clear out these Naga!', '', 116438, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Chopping', 'Chopping', 116437, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Careful! Don\'t touch that pearl!', '', 116436, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let me see what I can... dig up...', 'Let me see what I can... dig up...', 116435, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This cannot be...', 'Inconceivable...', 116434, 0, 0, 0, 64, 0, 65692, 65903, 0, 0, 0, 0, 0, 0, 39653),
('My magic... defeated?', 'Forgive me... Elisande.', 116433, 0, 0, 0, 64, 0, 65691, 65902, 0, 0, 0, 0, 0, 0, 39653),
('Tor\'theras falar!', 'Tor\'theras falar!', 116432, 0, 0, 0, 64, 0, 65690, 65901, 0, 0, 0, 0, 0, 0, 39653),
('Arash-falas...', 'Arash-falas...', 116431, 0, 0, 0, 64, 0, 65689, 65900, 0, 0, 0, 0, 0, 0, 39653),
('The shal\'dorei will rule this world!', 'The Nightborne will rule this world!', 116430, 0, 0, 0, 64, 0, 65698, 65899, 0, 0, 0, 0, 0, 0, 39653),
('Im... impossible.', 'It\'s no use!', 116429, 0, 0, 0, 64, 0, 65688, 65898, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thandae-alah...', 116428, 0, 0, 0, 64, 0, 0, 65617, 0, 0, 0, 0, 0, 0, 39653),
('', 'Trespasser...', 116427, 0, 0, 0, 64, 0, 0, 65616, 0, 0, 0, 0, 0, 0, 39653),
('', 'Desecrator...', 116426, 0, 0, 0, 64, 0, 0, 65615, 0, 0, 0, 0, 0, 0, 39653),
('', 'You will be cold... like us.', 116425, 0, 0, 0, 64, 0, 0, 65614, 0, 0, 0, 0, 0, 0, 39653),
('', 'Feel the chill of the grave!', 116424, 0, 0, 0, 64, 0, 0, 65613, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Magistrix... stop her...', 116423, 0, 0, 0, 64, 0, 0, 65612, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will rest now.', 116422, 0, 0, 0, 64, 0, 0, 65611, 0, 0, 0, 0, 0, 0, 39653),
('', 'Our people... shu dalees-na.', 116421, 0, 0, 0, 64, 0, 0, 65610, 0, 0, 0, 0, 0, 0, 39653),
('', 'What has become of us?', 116420, 0, 0, 0, 64, 0, 0, 65620, 0, 0, 0, 0, 0, 0, 39653),
('', 'Finally, we rest.', 116419, 0, 0, 0, 64, 0, 0, 65619, 0, 0, 0, 0, 0, 0, 39653),
('', 'Peace...', 116418, 0, 0, 0, 64, 0, 0, 65618, 0, 0, 0, 0, 0, 0, 39653),
('', '|TInterface\\Icons\\spell_warlock_demonicportal_purple.blp:20|t%s begins to cast |cFFFF0000|Hspell:219112|h[Shadow Gale]|h|r!', 116417, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\Ability_Warlock_EverlastingAffliction:20|tArchimonde has cast |cFFFF0000|Hspell:219143|h[Shadowfel Burst]|h|ron you! Move to a Pool of Grace!', '|TInterface\\Icons\\Ability_Warlock_EverlastingAffliction:20|tArchimonde has cast |cFFFF0000|Hspell:219143|h[Shadowfel Burst]|h|ron you! Move to a Pool of Grace!', 116416, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Keep back! Don\'t go near that pearl!', '', 116415, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
