INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('You of flesh are not worthy to wield the storms!', '', 109503, 0, 0, 0, 64, 0, 62602, 0, 0, 0, 0, 0, 0, 0, 39653),
('None challenge me and live.', '', 109502, 0, 0, 0, 64, 0, 62601, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thieves! Your heads will decorate my throne!', '', 109501, 0, 0, 0, 64, 0, 62600, 0, 0, 0, 0, 0, 0, 0, 39653),
('There it is! Mission accomplished!', '', 109500, 0, 0, 1, 64, 0, 62593, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Yes. This hero got us to safety, but we MUST get the other tribes back here to help us. We cannot stand divided.', 109499, 0, 0, 1, 64, 0, 0, 58857, 0, 0, 0, 0, 0, 0, 39653),
('', 'Destroyed?', 109498, 0, 0, 1, 64, 0, 0, 58856, 0, 0, 0, 0, 0, 0, 39653),
('', 'Jale! You have returned. Thank the spirits.', 109497, 0, 0, 1, 64, 0, 0, 58855, 0, 0, 0, 0, 0, 0, 39653),
('We seek a powerful artifact. What do you know?', 'We seek a powerful artifact. What do you know?', 109493, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do you remember Suramar before the Sundering?', 'Do you remember Suramar before the Sundering?', 109492, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tell me about Latosius.', 'Tell me about Latosius.', 109491, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s is |cFFFF0404|Hspell:204237|h[Gravely Wounded]|h|r and cannot fight until healed!', '%s is |cFFFF0404|Hspell:204237|h[Gravely Wounded]|h|r and cannot fight until healed!', 109485, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s falls to one knee, gravely wounded.', '%s falls to one knee, gravely wounded.', 109484, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m ready.', 'I\'m ready to enter.', 109483, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Danger still lurks within the tomb. Curse all the meddlers! If you keep us alive, we will clear the way.', '', 109482, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You and I shall lead a small team in first. Let me know when you are ready.', '', 109481, 0, 0, 1, 64, 0, 63365, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will complete the ritual to release the Hammer and collapse the tomb, but we must be quick. I can sense evil emanating from the tomb.', '', 109480, 0, 0, 1, 64, 0, 63364, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ah, there you are. The area was secured at great cost. This cannot continue, we must retrieve the Silver Hand and destroy the entrance to the tomb.', '', 109479, 0, 0, 1, 64, 0, 63363, 0, 0, 0, 0, 0, 0, 0, 39653),
('Drogbar do not come above ground. That is something they just don\'t do.', 'Drogbar do not come above ground. That is something they just don\'t do.', 109478, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bah! The drogbar can\'t win. They are just a bunch of savages.', 'Bah! The drogbar can\'t win. They are just a bunch of savages.', 109477, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Evacuate? But we have tilled this soil for generations.', 'Evacuate? But we have tilled this soil for generations.', 109476, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Argh! Blast this wind!', '', 109475, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We need to get out of here!', 'We need to get out of here!', 109474, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What? The Underking is coming? Oh no!', 'What? The Underking is coming? Oh no!', 109473, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('But... this is our land.', 'But... this is our land.', 109472, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The drogbar are coming?', 'The drogbar are coming?', 109471, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\Ability_Rogue_EnvelopingShadows:20|tIl\'gynoth has almost completed his |cFFFF0000|Hspell:210781|h[Dark Reconstitution]|h|r!', '|TInterface\\Icons\\Achievement_Boss_YoggSaron_01:20|tA Dominator Tentacle faces you and readies |cFFFF0000|Hspell:208689|h[Ground Slam]|h|r!', 109470, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have my gratitude. The stones of Llothien may once again know peace, thanks to you.', '', 109469, 0, 0, 0, 64, 0, 70760, 0, 0, 0, 0, 0, 0, 0, 39653),
('The ancient grounds of Llothien have long been abandoned. Now our ancestral land is overrun with beasts. I cannot bear to see it in such a state! Please make it right again, champion.', '', 109468, 0, 0, 0, 64, 0, 70759, 0, 0, 0, 0, 0, 0, 0, 39653),
('These mortals disrupt our ritual! Put an end to them at once.', 'These mortals disrupt our ritual! Put an end to them at once.', 109467, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Protectors - remove these unwelcome guests!', 'Protectors - remove these unwelcome guests!', 109466, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your world will burn!', 'Your world will burn!', 109465, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('By the might of Sargeras!', 'By the might of Sargeras!', 109464, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The power of Sargeras courses through our veins!', 'The power of Sargeras courses through our veins!', 109463, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your end is only the beginning!', 'Your end is only the beginning!', 109462, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Prepare to meet your end, mortals!', 'Prepare to meet your end, mortals!', 109461, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t give up hope, $n. Keep milling, and inspect your inks for unusual properties. Together, you and I may be able to fill in the gaps where this book is lacking.', '', 109460, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Not down here? Alright then, go ahead and use the ladder to check the upper scribrary.', '', 109459, 0, 39849, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This citizen appears to have been injured by fel magic... his fel-seared wounds look to resist normal recovery.\n\nWith no good way to aid this civilian, you must unfortunately continue along.', 'This citizen appears to have been injured by fel magic... his fel-seared wounds look to resist normal healing.\n\nWith no good way to aid this civilian, you must unfortunately continue along.', 109458, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('While not the best solution, your Tailoring allows you to wrap up these wounds and at least stabilize this civilian.', 'While not the best solution, your Tailoring allows you to wrap up these wounds and at least stabilize this civilian.', 109457, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your skill in First Aid allows you to recognize what is needed to ensure this one does not perish.', 'Your skill in First Aid allows you to recognize what is needed to ensure this one does not perish.', 109456, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This citizen appears to have been injured by fel magic... his fel-seared wounds look to resist normal recovery.', 'This citizen appears to have been injured by fel magic... his fel-seared wounds look to resist normal recovery.', 109455, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your skill in Skinning allows you to recognize the vellum this is inscribed upon despite the water damage. Releasing the magic within should be no problem.', 'Your skill in Skinning allows you to recognize the vellum this is inscribed upon despite the water damage. Releasing the magic within should be no problem.', 109454, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('All is not lost, Tidehunter. If the Elemental Lords unite...', '', 109453, 0, 0, 0, 64, 0, 67047, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oh my stars! Yes, this is it! The lid is attuned to a particular frequency. I just need to transmit a signal like so, and...', '', 109452, 0, 0, 1, 64, 0, 62592, 0, 0, 0, 0, 0, 0, 0, 39653),
('The gun is there? Most curious! Telemetry coming in... the Broken Isles... vrykul tomb... Ah yes, I see it now!', '', 109451, 0, 0, 1, 64, 0, 62591, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Where is Titanstrike, little tinkerer?', 109450, 0, 0, 1, 64, 0, 0, 62590, 0, 0, 0, 0, 0, 0, 39653),
('For the last time, I\'m not Brann!', '', 109449, 0, 0, 603, 64, 0, 62589, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bronzebeard? Ah yes, there you are! My records show this unit has been inactive for millennia. It was stolen from my lab long ago.', '', 109448, 0, 0, 1, 64, 0, 62588, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will not fight alone. The Earthen Ring is with you, and we will gather the other Elemental Lords to our cause!', '', 109447, 0, 0, 0, 64, 0, 67046, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hmmpf! Would you bow to Sargeras and be his slave instead? Pathetic!', '', 109446, 0, 0, 669, 64, 0, 67045, 0, 0, 0, 0, 0, 0, 0, 39653),
('Maker? Oh no... please don\'t be him...', '', 109445, 0, 0, 6, 64, 0, 62587, 0, 0, 0, 0, 0, 0, 0, 39653),
('Well done, $p! You are now prepared to do battle as an elemental shaman.', '', 109444, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Unleash the elements to achieve victory, $p!', '', 109443, 0, 0, 0, 64, 0, 59998, 0, 0, 0, 0, 0, 0, 0, 39653),
('System status: functional. Rerouting commands to maker\'s console.', '', 109442, 0, 0, 0, 64, 0, 62586, 0, 0, 0, 0, 0, 0, 0, 39653),
('Use Healing Surge to replenish your health to full.', '', 109441, 0, 0, 0, 64, 0, 60005, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'ve taken damage, but this presents no problem for you.', '', 109440, 0, 0, 0, 64, 0, 60004, 0, 0, 0, 0, 0, 0, 0, 39653),
('Very well, shaman. I will join the fight to save this world.', '', 109439, 0, 0, 0, 64, 0, 66828, 0, 0, 0, 0, 0, 0, 0, 39653),
('There was a time, long ago, when the elements fought as one... perhaps there is still hope.', '', 109438, 0, 0, 0, 64, 0, 67044, 0, 0, 0, 0, 0, 0, 0, 39653),
('Use Chain Lightning against several enemies at once.', '', 109437, 0, 0, 0, 64, 0, 60003, 0, 0, 0, 0, 0, 0, 0, 39653),
('There are times you\'ll face multiple opponents on the battlefield. Fortunately, you have a potent ability called Chain Lightning.', '', 109436, 0, 0, 0, 64, 0, 60002, 0, 0, 0, 0, 0, 0, 0, 39653),
('Turn my soldier into a frog!', '', 109435, 0, 0, 0, 64, 0, 60001, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ever wanted to turn someone into a frog? Hex allows you to do just that!', '', 109434, 0, 0, 0, 64, 0, 60000, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ahh yes... I have seen you before! There is power in you... but not enough to defeat the Burning Legion alone.', '', 109433, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Come forward then. Let me look upon this champion!', '', 109432, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'An\'anora!', 109431, 0, 0, 0, 64, 0, 0, 67226, 0, 0, 0, 0, 0, 0, 39653),
('What do you suggest, little orc? Shall I fight the Burning Legion myself?', '', 109430, 0, 0, 0, 64, 0, 67043, 0, 0, 0, 0, 0, 0, 0, 39653),
('Foolish mortals! There is no unity among the Lords of Elements!', '', 109429, 0, 0, 0, 64, 0, 67042, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Burning Legion has come. You should make use of the little time you have left, mortals.', '', 109426, 0, 0, 0, 64, 0, 67041, 0, 0, 0, 0, 0, 0, 0, 39653),
('Use Earth Shock on this target dummy.', '', 109425, 0, 0, 0, 64, 0, 59997, 0, 0, 0, 0, 0, 0, 0, 39653),
('Earth Shock is one of your most powerful spells. Casting it requires Maelstrom, a resource generated by your other attacks.', '', 109424, 0, 0, 0, 64, 0, 59996, 0, 0, 0, 0, 0, 0, 0, 39653),
('Shaman of the Earthen Ring, you have called, but I already know the threat we face.', '', 109423, 0, 0, 0, 64, 0, 66827, 0, 0, 0, 0, 0, 0, 0, 39653),
('Back to the depths with you, Ozumat. Your master commands it!', '', 109422, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('By the Earthmother!', '', 109421, 0, 0, 0, 64, 0, 67040, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'They\'re coming to life!', 109420, 0, 0, 0, 64, 0, 0, 62585, 0, 0, 0, 0, 0, 0, 39653),
('Efrina, find your brother and rally at the tomb.', '', 109419, 0, 0, 1, 64, 0, 63345, 0, 0, 0, 0, 0, 0, 0, 39653),
('Remote relay observer unit XR9-47 active. System status: damaged. Rebooting. Please stand by.', '', 109418, 0, 0, 0, 64, 0, 62584, 0, 0, 0, 0, 0, 0, 0, 39653),
('Now let\'s see... plug this in over here... realign the power unit...', '', 109417, 0, 0, 0, 64, 0, 62583, 0, 0, 0, 0, 0, 0, 0, 39653),
('As a Leatherworker, you recognize this type of tannin. Exposing it to the night air should ruin it for any future use.', 'As a Leatherworker, you recognize this type of tannin. Exposing it to the night air should ruin it for any future use.', 109416, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Lookee here... a mechagnome! Brann told me all about these things. It might be able to help us find Titanstrike!', '', 109415, 0, 0, 603, 64, 0, 62596, 0, 0, 0, 0, 0, 0, 0, 39653),
('By Magni\'s beard! This Volund sure had a taste for titan relics!', '', 109414, 0, 0, 603, 64, 0, 62595, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Titanstrike is close.', 109413, 0, 0, 1, 64, 0, 0, 62594, 0, 0, 0, 0, 0, 0, 39653),
('Enchanters all have a deep understanding of the arcane. This magic can be rerouted to provide assistance.', 'Enchanters all have a deep understanding of the arcane. This magic can be rerouted to provide assistance.', 109412, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You can make your way there through the portal to Dalaran Crater. I will meet you there with additional forces.', '', 109411, 0, 0, 1, 64, 0, 63344, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hear our words and answer the call of the Earthen Ring!', '', 109410, 0, 0, 0, 64, 0, 67039, 0, 0, 0, 0, 0, 0, 0, 39653),
('I need another invisibility spell applied.', 'I need another invisibility spell applied.', 109409, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'If it weren\'t for Beakbuck I would most certainly be dead.', 109408, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We call upon Neptulon, the great Lord of Tides, in the name of Azeroth!', '', 109407, 0, 0, 0, 64, 0, 67038, 0, 0, 0, 0, 0, 0, 0, 39653),
('Shaman of the Earthen Ring, let our powers combine!', '', 109406, 0, 0, 669, 64, 0, 66826, 0, 0, 0, 0, 0, 0, 0, 39653),
('Be wary, my friend- their constructs do not seem at all effected by my runes.', '', 109405, 0, 0, 1, 64, 0, 68992, 0, 0, 0, 0, 0, 0, 0, 39653),
('Use Lightning Bolt on the target dummy.', '', 109404, 0, 0, 0, 64, 0, 59995, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hurling lightning from your hands is your main weapon for overcoming enemies.', '', 109403, 0, 0, 0, 64, 0, 59994, 0, 0, 0, 0, 0, 0, 0, 39653),
('Use Lava Burst on the target dummy.', '', 109402, 0, 0, 0, 64, 0, 59993, 0, 0, 0, 0, 0, 0, 0, 39653),
('Why stop with fire? Once your enemies are burning, you can hurl molten lava at them.', '', 109401, 0, 0, 0, 64, 0, 59992, 0, 0, 0, 0, 0, 0, 0, 39653),
('Use Flame Shock on the target dummy.', '', 109400, 0, 0, 0, 64, 0, 59991, 0, 0, 0, 0, 0, 0, 0, 39653),
('As an elemental shaman you commune with ancient spirits and command primal elemental forces.', '', 109399, 0, 0, 0, 64, 0, 59990, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You two can yell at each other later! It be time ta get outta dis place!', 109398, 0, 0, 0, 64, 0, 0, 62469, 0, 0, 0, 0, 0, 0, 39653),
('Keep them from entering the chamber! The ritual is almost complete!', 'Keep them from entering the chamber! The ritual is almost complete!', 109397, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Look! The door\'s openin\'!', '', 109395, 0, 0, 5, 64, 0, 62582, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'They grow in strength. Be ready!', 109394, 0, 0, 0, 64, 0, 0, 62581, 0, 0, 0, 0, 0, 0, 39653),
('That\'s the spirit! One down, two to go!', '', 109393, 0, 0, 5, 64, 0, 62580, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hello. Have you come to join the Empyrean Society of Exotic Magical Arts?', 'Hello. Have you come to join the Empyrean Society of Exotic Magical Arts?', 109392, 0, 0, 3, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If I catch you drinking the reagents again, I\'ll turn you over to master!', '', 109391, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do you even call this laboring? The master will have your hides!', '', 109390, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will make this lake beautiful...', 109389, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My husband! Is he alright?', 109388, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Salma! Where\'s my Salma!?', '', 109387, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What are you filthy mortals doing near the master\'s portal? I\'ll rip the answer from your souls!', '', 109386, 0, 0, 0, 68, 0, 69918, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Prophet\'s mercy! What is that?!', 109385, 0, 0, 0, 68, 0, 0, 69919, 0, 0, 0, 0, 0, 0, 39653),
('', 'You pollute this hallowed ground with your greed. Begone!', 109384, 0, 0, 0, 64, 0, 0, 64167, 0, 0, 0, 0, 0, 0, 39653),
('', 'Despoilers! Halt!', 109383, 0, 0, 0, 64, 0, 0, 64166, 0, 0, 0, 0, 0, 0, 39653),
('Will do, Prust!', '', 109382, 0, 0, 273, 64, 0, 62579, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will dispel the runes. Protect me!', 109381, 0, 0, 1, 64, 0, 0, 62578, 0, 0, 0, 0, 0, 0, 39653),
('', 'He dares to send someone in his stead? That accursed wretch.', 109380, 0, 0, 0, 64, 0, 0, 65846, 0, 0, 0, 0, 0, 0, 39653),
('There, up ahead! That door\'s glowin\' with the same energy as all o\' these spirits.', '', 109379, 0, 0, 0, 64, 0, 62577, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My staff... it senses the Light within you! What is it... Nooooo!', 109378, 0, 0, 0, 64, 0, 0, 62452, 0, 0, 0, 0, 0, 0, 39653),
('', 'No! My staff is absorbing the Light! Damn you, priest, and your accursed magic!', 109377, 0, 0, 0, 64, 0, 0, 62449, 0, 0, 0, 0, 0, 0, 39653),
('', 'My darkness will consume you!', 109376, 0, 0, 0, 64, 0, 0, 62440, 0, 0, 0, 0, 0, 0, 39653),
('', 'Are you truly so stupid? You presume to challenge an eredar sorceress of the Burning Legion?', 109375, 0, 0, 0, 64, 0, 0, 62437, 0, 0, 0, 0, 0, 0, 39653),
('', 'What is that noise? Naranoth! If you allow another jailbreak, I\'ll strand you on this pathetic rock and leave you to rot!', 109374, 0, 0, 0, 64, 0, 0, 62434, 0, 0, 0, 0, 0, 0, 39653),
('Wonderful! I feel like we\'re on the cusp of discovering the cure to this curse! Who would\'ve thought that a lush like Garuhod might have held the key to our freedom?', '', 109373, 0, 0, 0, 64, 0, 71440, 0, 0, 0, 0, 0, 0, 0, 39653),
('Fetch me some livers from the bears in the highlands. Only the fat ones will do! Oh, and some hippogryph eggs as well. A little variety can\'t hurt.', '', 109372, 0, 0, 0, 64, 0, 71439, 0, 0, 0, 0, 0, 0, 0, 39653),
('It seems Garuhod\'s recipe was incomplete. My alchemists think some bile might be needed to balance this out. It\'s supposed to have some amazing properties!', '', 109371, 0, 0, 0, 64, 0, 71438, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It\'s just you and me now, little priest! Your pathetic Light won\'t save you!', 109370, 0, 0, 0, 64, 0, 0, 62446, 0, 0, 0, 0, 0, 0, 39653),
('', 'I grow tired of this! Be consumed by the darkness!', 109369, 0, 0, 0, 64, 0, 0, 62443, 0, 0, 0, 0, 0, 0, 39653),
('You are not worthy of Titanstrike\'s might!', '', 109368, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My chosen will protect me for all eternity!', '', 109367, 0, 0, 0, 64, 0, 62575, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am ready to begin.', 'I am ready to begin.', 109366, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The time has come to use the Idol of the Wilds and call upon the great god, Malorne. Never did I believe I would see the great ancient himself. This is a moment that we will speak of for ages to come.', '', 109365, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Heretic! I will slay you in Volund\'s name!', 109364, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Out of the rolling ocean I rise. The Lord of Tides has answered your call, Farseer of the Earthen Ring.', '', 109363, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('To honor your courage, I offer passage into the pure heart of the Dream. As you feel the essence of life blooming beneath your feet, know that it endures thanks to what you achieved this day.', '', 109362, 0, 0, 0, 64, 0, 58738, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your triumph restores the Dream and safeguards your world. The allies of Xavius will never relent, but this road, at least, is closed to them.', '', 109361, 0, 0, 0, 64, 0, 58739, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Nightmare has long been a cancer eager to consume the Emerald Dream. Had Xavius succeeded, his corruption would have overwhelmed Azeroth, giving rise to a living Nightmare.', '', 109360, 0, 0, 0, 64, 0, 58740, 0, 0, 0, 0, 0, 0, 0, 39653),
('Heroes! Champions! Step forth and hear me!', '', 109359, 0, 0, 0, 64, 0, 58741, 0, 0, 0, 0, 0, 0, 0, 39653),
('There is no escape!', '', 109358, 0, 0, 0, 64, 0, 58756, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your torment will be unending!', '', 109357, 0, 0, 0, 64, 0, 58755, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your dreams are mine!', '', 109356, 0, 0, 0, 64, 0, 58754, 0, 0, 0, 0, 0, 0, 0, 39653),
('Give in to the Nightmare!', '', 109355, 0, 0, 0, 64, 0, 58753, 0, 0, 0, 0, 0, 0, 0, 39653),
('Succumb to the madness!', '', 109354, 0, 0, 0, 64, 0, 58752, 0, 0, 0, 0, 0, 0, 0, 39653),
('Time to crush your dreams!', '', 109353, 0, 0, 0, 64, 0, 58751, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll level you one by one!', '', 109352, 0, 0, 0, 64, 0, 58750, 0, 0, 0, 0, 0, 0, 0, 39653),
('Feel the devastation of the Nightmare!', '', 109351, 0, 0, 0, 64, 0, 58749, 0, 0, 0, 0, 0, 0, 0, 39653),
('Time to cut the last tether to your mortal life!', '', 109350, 0, 0, 0, 64, 0, 58748, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will sever you from the waking world!', '', 109349, 0, 0, 0, 64, 0, 58747, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll slice into the heart of you!', '', 109348, 0, 0, 0, 64, 0, 58737, 0, 0, 0, 0, 0, 0, 0, 39653),
('Nightmares are... never... forgotten...', '', 109347, 0, 0, 0, 64, 0, 58736, 0, 0, 0, 0, 0, 0, 0, 39653),
('My work... left... unfinished...', '', 109346, 0, 0, 0, 64, 0, 58746, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your respite is over! Awaken and face your doom!', '', 109345, 0, 0, 0, 64, 0, 58735, 0, 0, 0, 0, 0, 0, 0, 39653),
('No more dreams! Only Nightmare!', '', 109344, 0, 0, 0, 64, 0, 58734, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let the Dreaming wash away his darkness!', '', 109343, 0, 0, 0, 64, 0, 58733, 0, 0, 0, 0, 0, 0, 0, 39653),
('Embrace the Dreaming, champions! It can save you!', '', 109342, 0, 0, 0, 64, 0, 58732, 0, 0, 0, 0, 0, 0, 0, 39653),
('They are mine, Ysera! You cannot save them!', '', 109341, 0, 0, 0, 64, 0, 58745, 0, 0, 0, 0, 0, 0, 0, 39653),
('NO! I will not permit it!', '', 109340, 0, 0, 0, 64, 0, 58731, 0, 0, 0, 0, 0, 0, 0, 39653),
('My victory is absolute. The power of Nightmare grows!', '', 109339, 0, 0, 0, 64, 0, 58744, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will not fail you, master! More power... just need more power...', '', 109338, 0, 0, 0, 64, 0, 58776, 0, 0, 0, 0, 0, 0, 0, 39653),
('Those ghosties are stirrin\' up the winds! Might need ta stop \'em the ol\' fashioned way!', '', 109337, 0, 0, 0, 64, 0, 62576, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your souls are mine, woven for all time into the fabric of the Nightmare!', '', 109336, 0, 0, 0, 64, 0, 58730, 0, 0, 0, 0, 0, 0, 0, 39653),
('My victory draws near!', '', 109335, 0, 0, 0, 64, 0, 58743, 0, 0, 0, 0, 0, 0, 0, 39653),
('This fate awaits you all!', '', 109334, 0, 0, 0, 64, 0, 58729, 0, 0, 0, 0, 0, 0, 0, 39653),
('Eternal slumber! Eternal madness!', '', 109333, 0, 0, 0, 64, 0, 58728, 0, 0, 0, 0, 0, 0, 0, 39653),
('Why won\'t you die? Why do you keep resisting?', '', 109332, 0, 0, 0, 64, 0, 58775, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will never stir again!', '', 109331, 0, 0, 0, 64, 0, 58742, 0, 0, 0, 0, 0, 0, 0, 39653),
('You failed, heroes! The ritual is upon us! But first, I\'ll indulge myself a bit... and finish you!', '', 109330, 0, 0, 0, 64, 0, 58774, 0, 0, 0, 0, 0, 0, 0, 39653),
('Another dreamer for my Nightmare!', '', 109329, 0, 0, 0, 64, 0, 58727, 0, 0, 0, 0, 0, 0, 0, 39653),
('Never underestimate a master warlock!', '', 109328, 0, 0, 0, 64, 0, 58801, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let the storm rain death upon you!', '', 109327, 0, 0, 0, 64, 0, 58800, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Nightmare has corrupted dragons, gods, and legends. Your downfall will be simple and swift!', '', 109326, 0, 0, 0, 64, 0, 58726, 0, 0, 0, 0, 0, 0, 0, 39653),
('A taste of the master\'s might!', '', 109325, 0, 0, 0, 64, 0, 58799, 0, 0, 0, 0, 0, 0, 0, 39653),
('Burn from within!', '', 109324, 0, 0, 0, 64, 0, 58798, 0, 0, 0, 0, 0, 0, 0, 39653),
('Drink in the glory!', '', 109323, 0, 0, 0, 64, 0, 58797, 0, 0, 0, 0, 0, 0, 0, 39653),
('Behold... power given form!', '', 109322, 0, 0, 0, 64, 0, 58796, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'ll never escape my grasp!', '', 109321, 0, 0, 0, 64, 0, 58795, 0, 0, 0, 0, 0, 0, 0, 39653),
('My will is unbreakable!', '', 109320, 0, 0, 0, 64, 0, 58794, 0, 0, 0, 0, 0, 0, 0, 39653),
('You dare trespass at the heart of the Nightmare itself? Foolish mortals! Here, my will is absolute. Here, I am the master!', '', 109319, 0, 0, 0, 64, 0, 58725, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll make ashes of you!', '', 109318, 0, 0, 0, 64, 0, 58793, 0, 0, 0, 0, 0, 0, 0, 39653),
('Kill them in my master\'s name!', '', 109317, 0, 0, 0, 64, 0, 58792, 0, 0, 0, 0, 0, 0, 0, 39653),
('Rid me of these pests!', '', 109316, 0, 0, 0, 64, 0, 58791, 0, 0, 0, 0, 0, 0, 0, 39653),
('Strike for Sargeras!', '', 109315, 0, 0, 0, 64, 0, 58790, 0, 0, 0, 0, 0, 0, 0, 39653),
('Come forth and serve me!', '', 109314, 0, 0, 0, 64, 0, 58789, 0, 0, 0, 0, 0, 0, 0, 39653),
('No more distractions! I have work to do...', '', 109313, 0, 0, 0, 64, 0, 58788, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thus do the champions of this world fall!', '', 109312, 0, 0, 0, 64, 0, 58787, 0, 0, 0, 0, 0, 0, 0, 39653),
('Surrender! I may yet show mercy!', '', 109311, 0, 0, 0, 64, 0, 58786, 0, 0, 0, 0, 0, 0, 0, 39653),
('You should have bent the knee!', '', 109310, 0, 0, 0, 64, 0, 58785, 0, 0, 0, 0, 0, 0, 0, 39653),
('One by one you fall!', '', 109309, 0, 0, 0, 64, 0, 58784, 0, 0, 0, 0, 0, 0, 0, 39653),
('The vessel must be made ready!', '', 109308, 0, 0, 0, 64, 0, 58773, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will not stop the ritual!', '', 109307, 0, 0, 0, 64, 0, 58772, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let the endgame begin!', '', 109306, 0, 0, 0, 64, 0, 58783, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'None will defile the warlord\'s hoard!', 109305, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The husk of Illidan will prove an ideal vessel for my master\'s glory. Sargeras will rise, and together we will watch your world burn!', '', 109304, 0, 0, 0, 64, 0, 58782, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your pathetic Horde will fall to dust. In the end, death will inherit this world and she will be waiting.', '', 109303, 0, 0, 0, 64, 0, 58781, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your pathetic Alliance will fall to dust. Your new boy-king will bow down and serve me... as will all of you!', '', 109302, 0, 0, 0, 64, 0, 58780, 0, 0, 0, 0, 0, 0, 0, 39653),
('Have you forgotten your humiliation on the Broken Shore? How your mighty warchief was stuck in the belly like a helpless piglet? Will you die slowly as he did, consumed by fel corruption and squealing for a merciful end?', '', 109301, 0, 0, 0, 64, 0, 58779, 0, 0, 0, 0, 0, 0, 0, 39653),
('Have you forgotten your humiliation on the Broken Shore? How your precious high king was bent and broken before me? Will you beg for your lives as he did, whimpering like some worthless dog?', '', 109300, 0, 0, 0, 64, 0, 58778, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ah yes, the heroes have arrived. So persistent. So confident. But your arrogance will be your undoing!', '', 109299, 0, 0, 0, 64, 0, 58777, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You will join the eternal hunt!', 109298, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('For the Alliance!', 'For the Alliance!', 109297, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A little shaken, but I\'ll be alright.', 'A little shaken, but I\'ll be alright.', 109296, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I... I must get back to battle!', 'I... I must get back to battle!', 109295, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('These bandages... thank you.', 'These bandages... thank you.', 109294, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I owe you a debt of gratitude.', 'I owe you a debt of gratitude.', 109293, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('How brave of you, $n.', 'How brave of you, $n.', 109292, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your actions have ensured a future for the blue dragons in Azsuna. With the withered\'s threat subsided, you\'ve given us the time we need to recover.', 109291, 0, 0, 0, 64, 0, 0, 70777, 0, 0, 0, 0, 0, 0, 39653),
('', 'Take back the mana crystals the withered stole and use them to revive the whelplings. Move quickly, friend!', 109290, 0, 0, 0, 64, 0, 0, 70776, 0, 0, 0, 0, 0, 0, 39653),
('', 'Friend, the withered are relentless in their attacks on our whelplands. They\'ve left our captive young starving for mana!', 109289, 0, 0, 0, 64, 0, 0, 70775, 0, 0, 0, 0, 0, 0, 39653),
('He insists that you return it, and that I may use force if necessary.', 'He insists that you return it, and that I may use force if necessary.', 109288, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Welcome to Mornath\'s Manor of Mystery! I have all manner of mysterious curios from before and after the Sundering.', '', 109287, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Use the Bloodstone!', 109286, 0, 0, 1, 64, 0, 0, 66514, 0, 0, 0, 0, 0, 0, 39653),
('', 'True. You will have to make an appearance.', 109285, 0, 0, 0, 64, 0, 0, 67227, 0, 0, 0, 0, 0, 0, 39653),
('I will start the ritual at your command.$B$BThe twins won\'t take too kindly to being summoned, so be prepared for a fight.$B$BOnce they are weakened, use the Bloodstone to enslave them.$B$BAre you ready to begin?', '', 109284, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Hmph... Someone will notice I am missing! They will come looking for me!', 109283, 0, 0, 0, 64, 0, 0, 67232, 0, 0, 0, 0, 0, 0, 39653),
('The lord of ravens will turn the key.', '', 109281, 0, 0, 0, 64, 0, 58934, 0, 0, 0, 0, 0, 0, 0, 39653),
('Flesh is his gift. He is your true creator.', '', 109280, 0, 0, 0, 64, 0, 58933, 0, 0, 0, 0, 0, 0, 0, 39653),
('Five keys to open our way. Five torches to light our path.', '', 109279, 0, 0, 0, 64, 0, 58932, 0, 0, 0, 0, 0, 0, 0, 39653),
('To find him, drown yourself in the circle of stars.', '', 109278, 0, 0, 0, 64, 0, 58931, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thanks, now its time for some payback!', 109277, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Its surface blazes bright, masking shadows below.', '', 109276, 0, 0, 0, 64, 0, 58930, 0, 0, 0, 0, 0, 0, 0, 39653),
('From the earth, he draws strength. Our earth. Our strength.', '', 109275, 0, 0, 0, 64, 0, 58929, 0, 0, 0, 0, 0, 0, 0, 39653),
('At the hour of her third death, she ushers in our coming.', '', 109274, 0, 0, 0, 64, 0, 58928, 0, 0, 0, 0, 0, 0, 0, 39653),
('The king of diamonds has been made a pawn.', '', 109273, 0, 0, 0, 64, 0, 58927, 0, 0, 0, 0, 0, 0, 0, 39653),
('Her heart is a crater, and we have filled it.', '', 109272, 0, 0, 0, 64, 0, 58926, 0, 0, 0, 0, 0, 0, 0, 39653),
('The boy-king serves at the master\'s table. Three lies will he offer you.', '', 109271, 0, 0, 0, 64, 0, 58925, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\INV_Misc_Bell_01:20|tAn alarm has been sounded! A reinforcement has entered the fray!', '|TInterface\\Icons\\INV_Misc_Bell_01:20|tAn alarm has been sounded! A reinforcement has entered the fray!', 109270, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\INV_Misc_Bell_01:20|tA %s has been alerted to your presence!', '|TInterface\\Icons\\INV_Misc_Bell_01:20|tA %s has been alerted to your presence!', 109269, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We appreciate your help, champion. You\'ve allowed my people a moment\'s respite from the naga threat.', 109267, 0, 0, 0, 64, 0, 0, 70730, 0, 0, 0, 0, 0, 0, 39653),
('', 'Our soldiers grow weary of the naga\'s relentless assault. Rally the Nightwatchers, champion, and drive the naga back to the depths where they belong!', 109266, 0, 0, 0, 64, 0, 0, 70729, 0, 0, 0, 0, 0, 0, 39653),
('Strike down the naga filth!', 'Strike down the naga filth!', 109265, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Face the wrath of the Nightwatchers!', 'Face the wrath of the Nightwatchers!', 109264, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Show the naga no mercy!', 'Show the naga no mercy!', 109263, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Drive back the scaled menace!', 'Drive back the scaled menace!', 109262, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('For Nar\'thalas!', 'For Nar\'thalas!', 109261, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Wipe this place clean of their inferior magics. The Moon Guard is finished.', 109260, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I heard what you did for the Rivermane tribe.$b$bWhen we first met in Dalaran I did not expect that you would be as helpful to us as you have been.$b$bIt is much appreciated.', '', 109259, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Scour the stronghold. None escape alive.', 109258, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\inv_feather_05.blp:20|t %s readies |cFFF00000|Hspell:210547|h[Razor Wing]|h|r.', '|TInterface\\Icons\\inv_feather_05.blp:20|t %s readies |cFFF00000|Hspell:210547|h[Razor Wing]|h|r.', 109257, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Moon Guard are finished! Slay them all.', 109256, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'None survive, so says the Grand Magistrix!', 109255, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Find them! Leave no stone unturned!', 109254, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Our work is nearly finished... do not allow these meddling shaman to interfere with the rituals!', 109253, 0, 0, 22, 64, 0, 0, 66831, 0, 0, 0, 0, 0, 0, 39653),
('Bring her back in one piece!', 'Bring her back in one piece!', 109252, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t get too reckless!', 'Don\'t get too reckless!', 109251, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take good care of it.', 'Take good care of it.', 109250, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('By the Earthmother! It is just as a I feared... the Twilight Dragonflight has returned!', '', 109249, 0, 0, 1, 64, 0, 67037, 0, 0, 0, 0, 0, 0, 0, 39653),
('Jale wishes to negotiate with these savages? A bold move, though probably a foolish one.', '', 109248, 0, 0, 0, 64, 0, 0, 0, 11, 1, 0, 0, 500, 0, 39653),
('We need your help negotiating with the Underking.', 'We need your help negotiating with the Underking.', 109247, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have only just returned from Bloodtotem lands, but I have heard of the aid you lent our people. \n\nIt shames me to see the day when outsiders like yourself are more willing to help us than our fellow tribes.', '', 109246, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I was not successful in getting the Bloodtotem tribe to help us with this. I hope Jale has enough leverage.', '', 109245, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Valeera nods.', 109244, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh, my head... Valeera, you okay?', 109243, 0, 0, 396, 64, 0, 0, 63629, 0, 0, 0, 0, 0, 0, 39653),
('', 'No! I\'ve worked too hard to be undermined by the likes of you!', 109242, 0, 0, 0, 64, 0, 0, 63637, 0, 0, 0, 0, 0, 0, 39653),
('', 'Come on, show me the \"legendary fighter\" I\'ve heard so much about!', 109241, 0, 0, 0, 64, 0, 0, 63636, 0, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('', 'You\'re more resilient than I thought. I was hoping to take you somewhere a little less... populated.', 109240, 0, 0, 1, 64, 0, 0, 63624, 0, 0, 0, 0, 0, 0, 39653),
('', 'She wants to preach her traitorous ideals to me further? Fine. Let us go.', 109239, 0, 0, 0, 64, 0, 0, 67231, 0, 0, 0, 0, 0, 0, 39653),
('Come with me. Ly\'leth wants to speak with you.', 'Come with me. Ly\'leth wants to speak with you.', 109238, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Just... finish me off.', 'Just... finish me off.', 109237, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Well done!', 109236, 0, 0, 396, 64, 0, 0, 63621, 0, 0, 0, 0, 0, 0, 39653),
