('I\'m going to pretend I didn\'t see that, Outlander.', 'I\'m going to pretend I didn\'t see that, Outlander.', 104077, 0, 37446, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I hope Tony has something edible back at camp.', '', 104076, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I don\'t think I am cut out to be a hunter.', '', 104075, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I don\'t think I was a hunter in my past life.', 104074, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'By the Dark Lady.', 104073, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
