('', 'Don\'t get so close. Your scent will give me away.', 104066, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'He\'s gone...', 104059, 0, 0, 0, 64, 0, 0, 61869, 0, 0, 0, 0, 0, 0, 39653),
