('Foolish mortal! You are mine now!', '', 101123, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You need not worry. I will not fail, Latosius.', 101122, 0, 0, 0, 64, 0, 0, 54566, 0, 0, 0, 0, 0, 0, 39653),
('The legion will devour you!', '', 101121, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
