('', 'My head... still spinning...', 99795, 0, 0, 0, 64, 0, 0, 67413, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hanging in there, thanks to you...', 99794, 0, 0, 0, 64, 0, 0, 67412, 0, 0, 0, 0, 0, 0, 39653),
