('', 'You can\'t stop him... and you can\'t stop the Burning Legion...', 94703, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You will have to get through me first if you want Gorefiend!', 94702, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Help! They won\'t let me leave!', 'Help! They won\'t let me leave!', 94700, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Anyone? Please help...', 'Anyone? Please help...', 94699, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Help... Help!', 'Help... Help!', 94698, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
