('He\'s not vile! Just... misunderstood.', '', 94612, 0, 0, 0, 64, 0, 51722, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Put that vile thing out of its misery already.', 94611, 0, 0, 0, 64, 0, 0, 51718, 0, 0, 0, 0, 0, 0, 39653),
