('', 'Look, someone approaches!', 94244, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Does it hurt, being so powerless?', 94243, 0, 0, 0, 64, 0, 0, 50596, 0, 0, 0, 0, 0, 0, 39653),
