('What sort of bait would ya like?', '', 93860, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[Lady Liadrin] The Ashbringer is somewhere in the crevice ahead - we need to hold these demons off long enough for someone to make it through their lines!', 93859, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[Lady Liadrin] Champion, move ahead and find Tirion. We will cover your advance!', 93858, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Tirion needs to speak with you, champion. The Ashbringer is lost!', 93857, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tirion needs to speak with you, champion. The Ashbringer is lost!', '', 93856, 0, 924, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[Lady Liadrin] We found him, champion! Tirion is alive!', 93855, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-GRAND CHAMPIONS-ALLIANCE.blp:50:80|t$b[Lord Maxwell Tyrosus] We found him, champion! Tirion is alive!', '', 93854, 0, 924, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[Lady Liadrin] We will scout ahead and try to find some sign of Tirion. We\'re with you!', 93853, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B$B|TINTERFACE\\ENCOUNTERJOURNAL\\UI-EJ-BOSS-COMMANDER SARANNIS.blp:50:80|t$b[Lady Liadrin] By the Light, Tirion is alive!', 93852, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
