('', 'You... you have saved me!', 93828, 0, 0, 0, 64, 0, 0, 60970, 0, 0, 0, 0, 0, 0, 39653),
('', 'I felt myself slipping away...', 93827, 0, 0, 0, 64, 0, 0, 60969, 0, 0, 0, 0, 0, 0, 39653),
