('', 'Ahh... curse you!', 93819, 0, 0, 0, 64, 0, 0, 61241, 0, 0, 0, 0, 0, 0, 39653),
('', 'This land... is.. ours...', 93818, 0, 0, 0, 64, 0, 0, 61243, 0, 0, 0, 0, 0, 0, 39653),
('', 'No... it cannot be!', 93817, 0, 0, 0, 64, 0, 0, 61233, 0, 0, 0, 0, 0, 0, 39653),
('', 'Flay the flesh and scatter the bones!', 93816, 0, 0, 0, 64, 0, 0, 61238, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Witchmother commands it!', 93815, 0, 0, 0, 64, 0, 0, 61235, 0, 0, 0, 0, 0, 0, 39653),
('', 'Fool! Die!', 93814, 0, 0, 0, 64, 0, 0, 61240, 0, 0, 0, 0, 0, 0, 39653),
('', 'Behold my curse!', 93813, 0, 0, 0, 64, 0, 0, 61242, 0, 0, 0, 0, 0, 0, 39653),
('', 'This land is ours now!', 93812, 0, 0, 0, 64, 0, 0, 61232, 0, 0, 0, 0, 0, 0, 39653),
('', 'Flesh and bone to earth and stone!', 93811, 0, 0, 0, 64, 0, 0, 61237, 0, 0, 0, 0, 0, 0, 39653),
('<The body of this nightsaber matriarch is not long dead. It appears to have put up a stalwart fight before eventually succumbing to its wounds.>', '<The body of this nightsaber matriarch is not long dead. It appears to have put up a stalwart fight before eventually succumbing to its wounds.>', 93810, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('All that remains... agony... madness!', '', 93809, 0, 0, 0, 64, 0, 52328, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Nightmare will consume us all!', '', 93808, 0, 0, 0, 64, 0, 52327, 0, 0, 0, 0, 0, 0, 0, 39653),
('Just wanted... a little fun...', '', 93807, 0, 0, 0, 64, 0, 61504, 0, 0, 0, 0, 0, 0, 0, 39653),
('Can\'t see... too much pain...', '', 93806, 0, 0, 0, 64, 0, 61501, 0, 0, 0, 0, 0, 0, 0, 39653),
('You win... this time...', '', 93805, 0, 0, 0, 64, 0, 61493, 0, 0, 0, 0, 0, 0, 0, 39653),
('Arrgh!', '', 93804, 0, 0, 0, 64, 0, 61500, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let\'s kill it!', '', 93803, 0, 0, 0, 64, 0, 61503, 0, 0, 0, 0, 0, 0, 0, 39653),
