('', 'I can feel the dark energy surrounding you. What IS that thing?', 92955, 0, 0, 1, 64, 0, 0, 49593, 0, 0, 0, 0, 0, 0, 39653),
('Play \"Night Song\"', 'Play \"Night Song\"', 92954, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
