INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('', 'Well, ye died, so ye have that goin\' fer ya.', 90636, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Not much of a fight, really.', 90635, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I cannae believe ye were so easy.', 90634, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I may have stabbed ye one too many times.', 90633, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That\'s how a Dark Iron does it.', 90632, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Scream louder, will ye? I can barely hear ye!', 90631, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oops. Did I do that?', 90630, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Very well. I\'ll kill ye first.', 90629, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ye won\'t even know what hit ye.', 90628, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Show me what yer made out of, ye mongrel.', 90627, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ye want tae fight with me, do ye?', 90626, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'m goin\' tae take me time with ye. I want tae savor yer screamin\'.', 90625, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Let me show ye how it\'s done.', 90624, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ye want me tae cut ya here first? How about... here?', 90623, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Don\'t worry, I\'ll only take a moment.', 90622, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will pay... for this...', '', 90621, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, commander?', '', 90620, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your will be done.', '', 90619, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My bow is ready.', '', 90618, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Say the word and consider it done.', '', 90617, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('At your service.', '', 90616, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I shall send your regards to the Dark Lady.', '', 90615, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('May the Dark Lady smile upon you.', '', 90614, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What is your wish, commander?', 'What is your wish, commander?', 90613, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You are unworthy of my mercy.', '', 90612, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I knew you wouldn\'t last long.', '', 90611, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You are unfit to even be raised as a ghoul.', '', 90610, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hardly worth the effort.', '', 90609, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('That\'s it?', '', 90608, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Dark Lady watch over you.', '', 90607, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will serve in death.', '', 90606, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Right between the eyes.', '', 90605, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t make this boring.', 'Don\'t make this boring.', 90604, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let\'s dance.', '', 90603, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re already dead.', '', 90602, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You might feel a slight pinch.', '', 90601, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hold still.', '', 90600, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You won\'t even see me coming.', '', 90599, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('One shot, one kill.', '', 90598, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tremble before the might of the Forsaken.', '', 90597, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|cFFFF0000$n|r has been selected to be |cFFFF0000|Hspell:153954|h[Cast Down]|h|r!', '|cFFFF0000$n|r has been selected to be |cFFFF0000|Hspell:153954|h[Cast Down]|h|r!', 90596, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|cFFFF0000$n|r has been targeted by the Arakkoa\'s |cFFFF0000|Hspell:154043|h[Super Weapon]|h|r!', '|cFFFF0000$n|r has been targeted by the Arakkoa\'s |cFFFF0000|Hspell:154043|h[Super Weapon]|h|r!', 90595, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A Solar Flare |cFFFF0000|Hspell:176544|h[Fixates]|h|r on |cFFFF0000$n|r!', 'A Solar Flare |cFFFF0000|Hspell:176544|h[Fixates]|h|r on |cFFFF0000$n|r!', 90594, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ability_fixated_state_red:20|tA Solar Flare has |cFFFF0000|Hspell:176544|h[Fixated]|h|r on you! If it reaches you it will |cFFFF0000|Hspell:153828|h[Explode]|h|r!', '', 90593, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ranjit uses his secret technique, |cFFFF0000|Hspell:156793|h[Four Winds]|h|r!', 'Ranjit uses his secret technique, |cFFFF0000|Hspell:156793|h[Four Winds]|h|r!', 90592, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ranjit creates a |cFFFF0000|Hspell:153759|h[Windwall]|h|r near |cFFFF0000$n|r!', 'Ranjit creates a |cFFFF0000|Hspell:153759|h[Windwall]|h|r near |cFFFF0000$n|r!', 90591, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Strengthen my armor and weapon so that they do not dull.', 'Strengthen my armor and weapon so that they do not dull.', 90590, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You can make your choice at the drafting table, commander.', '', 90589, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Only the very best for you, commander.', '', 90588, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I want to build a new structure.', 'I want to build a new structure.', 90579, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Is Papa still hunting?', 90577, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s begins to cast |cFFFF0404|Hspell:176464|h[Ripples in Time]|h|r! Seek cover!', '', 90574, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'When is Papa coming home?', 90570, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We draenei are the chosen race... civilized, cultivated, keenly intellectual.$B$BThere is no technology that our minds cannot grasp, and no magic that our arcanists cannot master.$B$BOur civilization on Argus was magnificent to behold.$B$BOur people were never slaves nor cowards, hiding from their potential.$B$BOur people have the means to conquer the stars!$B$BUnite with me, brothers and sisters, and let us take what is rightfully ours!', '', 90569, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Legion\'s work must continue uninterrupted. There are those on Draenor who wish to disrupt their plans, and chief among them are the unbelievers - draenei who still follow the Light.$B$BDestroy our kin, and keep our masters\' work unhindered. Defeat the draenei, and we prove our loyalty to the Legion. Crush Shattrath, and the demons promise us the glory of immortality!', '', 90568, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thousands of years ago, the demons of the Burning Legion came to our homeworld and offered our leaders a great gift.$B$BTwo of them, Kil\'jaeden and Archimonde, saw the wisdom in their offering, but the last leader, Prophet Velen, refused.$B$BHe and his followers fled from that world, forever hunted by those who once offered their hands in friendship.$B$BVelen was a FOOL! And we are descended from those fools, who would turn their backs on paradise!$B$BNo longer, my brethren! Today, we rise up and bow to the demon lords. They have given us another chance to share in their power.$B$BThis, my brothers and sisters, is our TRUE destiny. Today, we walk in the footsteps of our eredar forerunners, and claim the future that is rightfully ours!', '', 90567, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Loot Ahead', 'Loot Ahead', 90566, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stay Calm', 'Stay Calm', 90565, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Visions of Demise', 'Visions of Demise', 90564, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Help Me!', 'Help Me!', 90563, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Allies Required Ahead', 'Allies Required Ahead', 90562, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Dead Inside', 'Dead Inside', 90561, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tears Ahead', 'Tears Ahead', 90560, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Go Away!', 'Go Away!', 90559, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Remember, keep your mouth clenched, so if you\'re struck by lightning then you won\'t bite off your tongue.', '', 90558, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Touch the Time Bombs to send them back into the sky!', 'Touch the Time Bombs to send them back into the sky!', 90557, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stubborn, I see. This is it, soldiers. For the Alliance!', '', 90556, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We\'ve almost got them!', '', 90555, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Spread out! Don\'t let them flank us!', '', 90554, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The first charge is broken.', '', 90553, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Thunderlords are here to give us a lesson in revenge. Instead, let\'s teach them humility.', '', 90552, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Da grunts be tough, it\'s true, but dey don\'t have da smarts to take on such a monsta. I\'ll send da Shadow Huntas in, and we\'ll see how tough dis thing is.', '', 90551, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am a master of persuasion, but it seems the Sargerei value strength, not oratory.$B$BThe quickest way to earn their trust is through battle. I am sure that is why Modera sent you to help me.', '', 90550, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Dey say dere be a giant creature in the mine dat\'s been makin\' short work of any grunts dat look at it twice.', 90549, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We be gettin some strange reports from out scouts over by da big ogre mine.', 90548, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You tell da elf that he get whateva\' volunteers he get. And he better be hurryin\' up before I get tired a\' lookin at him!', '', 90547, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Dat Belloc bein\' lucky dat I haven\'t lost my patience with him! I don\'t jave soldia\'s layin around ta be diggin\' up relics!', '', 90546, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Da elf, Belloc, been sayin\' dat he be needin more men ta find da big artifact.', 90545, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We\'ll be seein how dey feel when da earth below dem comes ta fight at our side!', '', 90544, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hah! If dey think they can scare da Horde with a big tree, den we be havin\' a surprise for dem!', '', 90543, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Boss, our scouts are sayin\' dat da Alliance is empowerin\' a giant ancient ta send into battle!', 90542, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ll be needin\' to have some words with our friends from the Ravenspeakers to figure out da true nature of dese arakkoa.', '', 90541, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Arakkoa outcasts, ya say? Here I thought we be allies with dem.', '', 90540, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Our reports be statin\' dat dere is a group of hostile arakkoa outcasts  jus\' outside da outpost.', 90539, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Right away, boss!', 90538, 0, 0, 66, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You did good bringin\' me dis report. Now, be returnin\' to da field.', '', 90537, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We got reports from da field, mon!', 90536, 0, 0, 66, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Da Alliance think dey so smart. Dey hidin\' behind dis truce of deirs, meanwhile dey searchin\' dis island high and low for a powerful weapon, but dey no askin\' for our help.\n\nSure, dey say da weapon is ta be used against da Iron Horde, but what is ta stop dem from turnin\' it on us once we off dis world?\n\nI say we take da weapon, and we be showin\' dem who has da powah - on dis world as well as ours.\n\nFor da Horde!', '', 90535, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'It\'s a bit warm out today, don\'t you think?', 90534, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Could you conjure me some food?', 'Could you conjure me some food?', 90533, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It looks like $n\'s arrived to help crack some Alliance skulls!', '', 90532, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Is that $n? They say $Ghe\'s:she\'s; the greatest $c that ever was!', 90531, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Look! It\'s $n!', 90530, 0, 0, 25, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Lok\'tar, commander. Would you like to view any recent major events?', '', 90529, 0, 0, 0, 64, 0, 0, 0, 396, 0, 0, 0, 0, 0, 39653),
('', 'Have you heard of me, $n? I am Modera, archmage of the Council of Six, which rules the Kirin Tor and Dalaran.$B$BI could wipe out this entire village if I chose.$B$BBut that is not why we are here. As I have learned through the years, sometimes you need honey to catch a fly.', 90528, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Show me what happened at the Battle for Shattrath.', 'Show me what happened at the Battle for Shattrath.', 90527, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Greetings, commander. Would you like to view any recent major events?', 90526, 0, 0, 0, 64, 0, 0, 0, 396, 0, 0, 0, 0, 0, 39653),
('', 'His new allies have given him a new name, and a new identity - \"Socrethar.\" He is a powerful enemy, and I fear what he is capable of.', 90525, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our task is grim, but necessary.', '', 90524, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve seen enough. Fight your own battles, oh great and powerful king.', '', 90523, 0, 0, 0, 64, 0, 46492, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Exarch Othaar\'s betrayal was sudden. How could a leader of the draenei turn his back on the Light, and embrace the enemies who persecuted his entire race?', 90522, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ghost ogres? I can see why they\'d stay away. Not that I\'m afraid or anything, but I prefer enemies I can actually strike with an axe.', '', 90521, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The grunts that return from there are reporting sighting of strange spirits. They say that necromancers are enslaving the ghosts of the ancient ogres.', 90520, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve toyed with you long enough!', '', 90519, 0, 0, 0, 64, 0, 44517, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oh yeah? Why do you think that is?', '', 90518, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('To arms! To your posts! The Thunderlords want to play.', '', 90517, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I spoke with Warlord Volrath today. He is concerned that our troops are refusing to march into the burial grounds.', 90516, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Sargerei village is like a beehive.$B$BDisturb its denizens, and we will get stung. Destroy it in flames, and we will destroy the precious honeycomb as well.$B$BThe only way to retrieve the information we seek is through sublety.', 90515, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I cannot fathom why anyone would pledge themselves to the Legion.$B$BThere are those who lust for power, and do not know how to wield it.', 90514, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I still bear old wounds from the demons\' first coming to Azeroth. I remember the horror, the madness, and the stillness that descended upon a city destroyed.$B$BI will do anything in my power to prevent that from happening again.', 90513, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'If it were up to me, I\'d be the one to carry out this mission. But Archmage Khadgar insisted that you would have a more delicate touch.', 90512, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It\'s been years since I\'ve been out in the field like this.$B$B<The stately archmage takes a deep breath.>$B$BThere\'s nothing like the smell of clean air and danger.', 90511, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('All I care about is that we get to bring the battle to the humans again. I\'ve been itchin\' for a proper fight!', '', 90510, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Do you even understand why we\'re here in Ashran?', 90509, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bah! Who cares about some old, dusty relics? I came here to bash some Alliance heads in!', '', 90508, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Not an axe, dimwit! They say it\'s part of the big artifact the Alliance is lookin\' for.', 90507, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What, like a really big axe?', '', 90506, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You hear what happened? The blood elves say they found something big in the mines.', 90505, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Not necessarily. I still have my teeth and claws.', 90504, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Dat must make things diffcult for ya on da battlefield.', 90503, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The primal forces of Draenor are wild and untamed. They seem to resist any attempt at control.', 90502, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The fury of nature should not be abused in such a way. In the end, they will pay for their folly.', 90501, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Da Alliance must be desparate to obtain da artifact to unleash such foes upon us.', 90500, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The situation has become very dangerous on Ashran lately. This morning I nearly had my head taken off by an enraged ancient!', 90499, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
