INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('', 'Restless spirits, HEED my command!', 90120, 0, 0, 0, 64, 0, 0, 43547, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your souls will belong to ME.', 90119, 0, 0, 0, 64, 0, 0, 43546, 0, 0, 0, 0, 0, 0, 39653),
('', 'Mmm, yes. The PERFECT sacrifice.', 90118, 0, 0, 0, 64, 0, 0, 43545, 0, 0, 0, 0, 0, 0, 39653),
('', 'For Ner\'zhul...', 90117, 0, 0, 0, 64, 0, 0, 43544, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ancestors of the Shadowmoon, shine in the darkness! Lend me your strength!', 90116, 0, 0, 0, 64, 0, 0, 43539, 0, 0, 0, 0, 0, 0, 39653),
('', 'Rivers of the damned, RISE! RISE in the name of darkness, RISE in the name of Ner\'zhul! The Shadowmoon beckons...', 90115, 0, 0, 0, 64, 0, 0, 43541, 0, 0, 0, 0, 0, 0, 39653),
('You bend to my will!', '', 90114, 0, 0, 0, 64, 0, 43687, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your soul shall serve me!', '', 90113, 0, 0, 0, 64, 0, 43686, 0, 0, 0, 0, 0, 0, 0, 39653),
('My power... Will ripple... Across eternity.', '', 90112, 0, 0, 0, 64, 0, 43683, 0, 0, 0, 0, 0, 0, 0, 39653),
('Feel the void\'s cold embrace.', '', 90111, 0, 0, 0, 64, 0, 43691, 0, 0, 0, 0, 0, 0, 0, 39653),
('Into the abyss!', '', 90110, 0, 0, 0, 64, 0, 43690, 0, 0, 0, 0, 0, 0, 0, 39653),
('A kindling of bone and shadow! Army of the dead, arise!', '', 90109, 0, 0, 0, 64, 0, 43689, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am the herald of the end!', '', 90108, 0, 0, 0, 64, 0, 43688, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Shadowmoon CANNOT be defeated - we walk in the realm of death itself.', '', 90107, 0, 0, 0, 64, 0, 43682, 0, 0, 0, 0, 0, 0, 0, 39653),
('Come, strangers! Cross into the realm of the Shadow Lands! I shall deliver you to your death.', '', 90106, 0, 0, 0, 70, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The darkness... it flows within me. It seeps from every vein.', '', 90105, 0, 0, 0, 70, 0, 48235, 0, 0, 0, 0, 0, 0, 0, 39653),
('The |cFFE86B17|Hspell:175519|h[Essence of Flame]|h|r is knocked from your hands!', 'The |cFFE86B17|Hspell:175519|h[Essence of Flame]|h|r is knocked from your hands!', 90104, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Open a portal to my garrison.', 'Open a portal to my garrison.', 90103, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I admire your morals.  Carry on.', 'I admire your morals.  Carry on.', 90102, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sorry, I still need to train one of my pets to level 25.', 'Sorry, I still need to train one of my pets to level 25.', 90101, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Begin a guiding light ritual. I want to summon my allies to my location.', 'Begin a guiding light ritual. I want to summon my allies to my location.', 90100, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'A tender lesson learned too late.', 90099, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Do not despair. Both you and your pet can learn from this.', 90098, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The moth is delicate, but not without defenses.', 90097, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It is folly to underestimate the stength of nature.', 90096, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Life is full of surprises.', 90095, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The moth is drawn to the flame, it seems.', 90094, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Light has not yet taken her.  She simply rests.', 90093, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Life is full of surprises.', 90092, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Fear not, a simple healing spell will set that to rights.', 90091, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I am sad for the loss, but glad for your victory.', 90090, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I hope you have learned something today.', 90089, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I hope you have learned something today.', 90088, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Pay attention, $n.  Strength is often found where you least expect it.', 90087, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I understand.  Please come back when you are ready.', 90086, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hello $n.  Would you like to dance with my moths?', 90085, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Anzu protects his children.', '', 90084, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The guardians stand strong.', '', 90083, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The raven god blesses us today.', '', 90082, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The strength of the Arakkoa is with us.', '', 90081, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A good omen.', '', 90080, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The curse of Sethe is upon us.', '', 90079, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Doom and gloom!  Dooooooooom and glooooooom!', '', 90078, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('No!  The guardians cannot fall!', '', 90077, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Anzu protect your children!', '', 90076, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A bad omen.', '', 90075, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We are Arakkoa.  We are not broken by a single defeat.', '', 90074, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Glory to Anzu!', '', 90073, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our hopes lie in what these pets will become.  They are sacred to us.', '', 90072, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Very well.  Train and come back to me.', '', 90071, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$R, I am devoted to training the guardians of Anzu.  Will you aid me in this cause?', '', 90070, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That\'s a bit of bad luck there, $gMister:Lady;.', 90069, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That\'s right!  My pets are from the mean streets of Caldeum.', 90068, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Don\'t throw that one away, it can still be fixed up.', 90067, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Sorry, $gMister:Lady;.', 90066, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Bad luck just runs in my family.', 90065, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ll sell ya a Stone of Jordan if you promise not to do that again.', 90064, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Easy now!  I paid a pretty copper for that one.', 90063, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Not the first time someone has hunted that one to the ends of the earth.', 90062, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It\'s okay, they\'re used to dying.', 90061, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'This is just like the time my home town was overrun by demons.', 90060, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thanks $gMister:Lady;!  I bet 100 coppers on this fight.', 90059, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I may be small, but if you hurt my pets, I\'ll hurt you.', 90058, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Come back another time then.', 90057, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hey $gMister:Lady;, you wanna see my pets?', 90056, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is why Tarr is the greatest warlord in all of Nagrand!', '', 90055, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tarr will rock you!', '', 90054, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you not entertained?', '', 90053, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gladiator smash!', '', 90052, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Haha, puny $r has puny pets.', '', 90051, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I told you to kill, not die!', '', 90050, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You make Tarr angry!', '', 90049, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My gladiators fight to the death!', '', 90048, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What is one death when I have an army of three?', '', 90047, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What?  How is this possible?  You must have cheated!', '', 90046, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I remain the greatest warlord in all of Nagrand!', '', 90045, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gladiators, kill!', '', 90044, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'An easy kill.  My wolves will learn nothing.', 90043, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Why are your pets so weak?', 90042, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hardly even a challenge.', 90041, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'A clean kill.', 90040, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'A good kill.', 90039, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That one will need some healing.', 90038, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That one was too slow.', 90037, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That one won\'t make that mistake again.', 90036, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That one did not lack courage.', 90035, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That one was too stupid.', 90034, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Only defeat truly exposes our weaknesses.  This loss will improve their training.', 90033, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You are lucky my wolves are not yet full grown, or else you would have been the meal.', 90032, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'As I thought, $r, you are too weak.', 90031, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Begin a ritual of summoning. I want to summon my allies to my location.', 'Begin a ritual of summoning. I want to summon my allies to my location.', 90030, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You can make your pet all better, right?', 90029, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Is your pet sleeping too?', 90028, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh no!', 90027, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We\'ll put the rainbow bandage on that.', 90026, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'She\'s not dead, she\'s just sleeping.', 90025, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh no!', 90024, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Soup will make you all better!', 90023, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Don\'t worry, I\'ll kiss the boo-boo all better.', 90022, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh, that\'s okay I guess.  Doodle will need a new eye though.', 90021, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh my pets did so good.  They\'re going to get so many extra snuggles for that.', 90020, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Here we go!', 90019, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You don\'t look like you\'re very good at pet battles.  Maybe you should come back when you\'re better.', 90018, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Brightblade?  That name sounds familiar...', 'Brightblade?  That name sounds familiar...', 90017, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I may fall... but the Overgrowth will take you eventually...', '', 90016, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh, you must mean my father, Belloc.  What he and the Reliquary do can hardly be called \'archaeology\'.  Grave robbing is more like it.$b$bTrue archaeology is the search for fact, not treasure.  I want to learn about the past, study where we came from, and rediscover lost knowledge.', 90015, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ll add a special thanks to your pet when I publish this research.', 90014, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The plants will feast on you.', '', 90013, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You have to respect the ingenuity of such an ancient device.', 90012, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ve got bandages in my field kit if you need some...', 90011, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will feed my roots.', '', 90010, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'All in the name of science.', 90009, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Now, was that result the device performing as expected, or did it just explode?', 90008, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Fortunately, Gyraxle can repair anything.  Even himself.', 90007, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Huh, I kinda thought that might happen.', 90006, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'In its native culture, that pet might have been revered as a martyr.', 90005, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Well, what can you expect from something that\'s been buried in the ground for a millennium?', 90004, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Very interesting results.  Thanks for helping me test them out!', 90003, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It\'s easy to see why objects such as these would have been highly prized by their cultures!  Er, sorry about your pets.', 90002, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh, this should be interesting.  You don\'t mind if I take notes, do you?', 90001, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('HAH! Hey Jhorn, remember da poop I made dat looked like a $r? Dat\'s what $n looks like now!', '', 90000, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Was dat a baby $r or da fully growd up kind? Dat died too easy!', '', 89999, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Looks like da janitor gonna be pickin\' up pieces of $n for days!', '', 89998, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oof! Dat little $r died ugly!', '', 89997, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n dead! Looks like der are $9662W gladiators still fighting!', '', 89996, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n down! Dat remind me of da time when dat orc got his stones crushed by dat big elekk. Dat was a good week at da circus!', '', 89995, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What was dat?! Sometin\' exploded on da floor. I tink it was $n!', '', 89994, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Down goes $n! Dat $r left notin\' but doodoo an blood on da floor!', '', 89993, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('To the last gladiator standing goes honor, glory and riches!', '', 89992, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will fight. You will kill. You will salute! 100 LIVES. Live or die.', '', 89991, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You now stand upon hallowed ground. In this place, upon the arena floor, the greatest gladiators of Draenor have spilled blood. Most have given up their lives for such a great honor. Today, you will do the same.', '', 89990, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s escapes!', '', 89989, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I want to check on my followers\' missions.', 'I want to check on my followers\' missions.', 89988, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Interrupting cretins! I\'ll sear that pretty armor right into your skin!', '', 89987, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Raastok cackles with glee.>$B$BDid you see the size of that explosion?! Marvelous!', '', 89986, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will enjoy feasting on your soul...', '', 89985, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Intruders! Someone, inform Keli\'dan!', 89984, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am close to replicating the Apexis interface.', '', 89983, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Come on Brute!', 'Come on Brute!', 89982, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hey! That one no fight fair!', 'Hey! That one no fight fair!', 89981, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bite him! Bite him!', 'Bite him! Bite him!', 89980, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('OUCH! That had to hurt!', 'OUCH! That had to hurt!', 89979, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I got gold on the big guy!', 'I got gold on the big guy!', 89978, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I need you to repair my gear.', 'I need you to repair my gear.', 89977, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I want to check my mail.', 'I want to check my mail.', 89976, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The answers are out there, hiding in dark places.$B$BWe must be bold enough to seek them.', '', 89975, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hold still, I\'ll patch you up.', 89974, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Let me see to that wound...', 89973, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Next time, don\'t pull out the barbed arrow yourself. Find something else to stab your opponent with.', 89972, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Must you orcs always practice with sharpened axes?', 89971, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Powerful, you say? Maybe I should go get my hands on some of them.', '', 89970, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('All I know is da Alliance wants em, and da elves think they big and powerful. We don\'t want da Alliance havin that.', '', 89969, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('So what\'s the deal with these artifacts I keep hearing about?', '', 89968, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Uh, I don\'t think it works that way...', '', 89967, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yeah! I mean come on, it\'s only a foot! Those things are so easy to stitch back on.', '', 89966, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You talkin\' bout da one who kept screamin\' after you chopped off his foot?', '', 89965, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Man, those Alliance soldiers sure are crybabies!', '', 89964, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I need reagents.', 'I need reagents.', 89963, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have a few spells that can mend your equipment - for a price.', '', 89962, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('All gladiators have perished. There will be no champion today.', 'All gladiators have perished. There will be no champion today.', 89961, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Burn in Fel Fire!', '', 89960, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Some think it strange, but I find the rhythmic sound of goblin machinery to be quite relaxing. \n\nThe smell, however, I could do without.', '', 89959, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tired of casting like the puny weakling that you are? Try my patented Rocket Cast system!', '', 89958, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Whoever said proper technique is required for a long cast has obviously never tried rockets!', '', 89957, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Nina, we\'re not getting enough fish! We need more rockets!', '', 89956, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My patented Rocket Cast system works flawlessly. Now if only these fish wouldn\'t be so picky and bite!', '', 89955, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'What can I do for you?', 89954, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '<Rachelle shrugs.>$B$BI\'m not much for words.', 89953, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '<Rachelle looks at her tools.>$B$BThere\'s much work to do.', 89952, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Need something?', 89951, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Good day.', 89950, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hello.', 89949, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Yes?', 89948, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '<Rachelle gives you a polite nod.>$B$BGreetings.', 89947, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What do you think happened to Bozzil? He wasn\'t born looking like that!', '', 89946, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'So Xelganak could melt someone\'s face off?', 89945, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Xelganak is a most peculiar creature indeed! The bioluminescent fluid in Xelganak\'s sac is highly corrosive and can be propelled at high velocity.', '', 89944, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Sure thing, boss! Initiating holo-projection D-100...', 89943, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Twixnee, please intiate the holo-projection for Xelganak!', '', 89942, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Natural fossilization? Ain\'t nobody got time for that!', 89941, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('...instead, it is our duty to lend nature a helping hand and speed up the process!', '', 89940, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Indeed, Twix... and razor sharp! It\'s a shame we don\'t have time to allow Thek\'talon to die naturally and slowly fossilize through the ages...', '', 89939, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Does it have large talons?', 89938, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ahh, yes! Here we have Thek\'talon, a windroc of superb size and ferocity.', '', 89937, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You got it, Mr. G! Initiating holo-projection D-099...', 89936, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let us continue on to the next specimen!', '', 89935, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The things we archaeologists have to deal with these days! Sheesh!', 89934, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let\'s just say that extracting a hippo tooth for preservation is far more dangerous while the hippo is alive...', '', 89933, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Nemesis? Do you and this hippo have some kind of history?', 89932, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Mu\'gra... my old nemesis!', '', 89931, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'D-098 coming right up!', 89930, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Now, let\'s take a look at Mu\'gra! Holo-projection D-098, Twix...', '', 89929, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will destroy you!', '', 89928, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Behold the power of the Legion!', '', 89927, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yeah, beat it!', 'Yeah, beat it!', 89926, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is our town, scrub.', 'This is our town, scrub.', 89925, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Boss, you\'re bringing tears to my eyes!', '', 89924, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Somewhere out there, in a private collection, is an empty place just waiting for Gagrog\'s skull to fill the void.', '', 89923, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hide the women and the children! Hide everybody!', 89922, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Such a magnificently brutal creature! Few Gronn are as feared as Gagrog the Brutal!', '', 89921, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Initiating holo-projection D-097... Gagrog the Brutal!', 89920, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Now, on to the next specimen!', '', 89919, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('As it should, Twixnee... as it should.', '', 89918, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Just hearing you speak makes me proud to be an archaeologist, sir!', 89917, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It\'s our duty as archaeologists to preserve this mighty beast while still in the prime of its life!', '', 89916, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Direhoof is the most dangerous talbuk this side of Nagrand, and a specimen of rare quality...', '', 89915, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Holo-projection D-096 initiated, boss!', 89914, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Now then, let\'s review the deadly and elusive talbuk known as Direhoof...', '', 89913, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That size matters? Uhh... yeah, sure! You bet!', 89912, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Precisely! Did you learn that from me?', '', 89911, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Umm... by the size of its tusks?', 89910, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pop quiz, Twix! How do you tell the age of an Elekk?', '', 89909, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Elekk are one of the oldest living species on Draenor, and Dekorhan sightings have been recorded by the orcs for generations...', '', 89908, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Initiating holo-projection D-095...', 89907, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let\'s move on to Dekorhan, the mysterious and ancient Elekk of Nagrand!', '', 89906, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Not yet! However, there are several collectors that would pay a fortune to acquire it.', '', 89905, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Has anyone actually gotten close enough to measure the thing?', 89904, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ahh yes! Bergruu, the mighty Ironhide of the northern plains! Bergruu\'s horn is said to be the largest clefthoof horn ever seen...', '', 89903, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Next up in the database is Bergruu. Initiating holo-projection D-093...', 89902, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let\'s move on to the next specimen!', '', 89901, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We simply must have Aogexon\'s fangs, Twixnee. They will make fine fossils one day!', '', 89900, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It\'s been said that Aogexon\'s fangs can cut through solid steel! Magnificent!', '', 89899, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You got it boss! Initiating holo-projection D-092!', 89898, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We aren\'t the only ones with Prisoners, $c.$B$BOver at the Alliance base, underneath their main building lies their prison.$B$BWe just need to find those Stormshield Prison Keys to break them out.', '', 89897, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Alright, Twix... let\'s take a look at the fabled predator Aogexon!', '', 89896, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I was dying in there! Thanks!', 89895, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thanks sweetie. Now back to battle!', 89894, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Commander, we did it!', '', 89893, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Give Leorajh back his prayer beads!', '', 89892, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes... excellent. RaAWK!', '', 89891, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There is the one we seek. Her staff is the key.', '', 89890, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Leorajh more powerful than ever!', '', 89889, 0, 0, 71, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes... I grow ever closer to the shadows.', '', 89888, 0, 0, 71, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Leorajh is stronger!', '', 89887, 0, 0, 71, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The shadows have granted me new strength.', '', 89886, 0, 0, 71, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('He asks as if we have an endless supply of adventurers at our disposal. He will get whoever volunteers to aid him. Our soldiers are already spread thin due to the Horde threat.', '', 89885, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('He requests more men to aid in the search.', '', 89884, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Harrison Jones is reports that though he has received several fragments, he is no closer to discovering the location of the artifact we seek.', '', 89883, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Disgusting. Commander, I\'ll watch your back while you grab what\'s left of that... thing.', 89882, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Commander, I suggest we get out o\' here. This is nae a place ye want ta stick around in.', '', 89881, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We will have to alert our men fighting near the cave. Good work, soldier.', '', 89880, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('None of our scouts have been able to get a good look at it, but its so massive it barely fits in the cave!', '', 89879, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Reports are coming in of a massive beast residing in the ogre mine.', '', 89878, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$n has placed a Savage Feast.', '$n has placed a Savage Feast.', 89877, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will have to confer with our druid allies. The ancient that they are awakening may be our only key to defeating such a force.', '', 89876, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A fury of the earth, you say? That is troubling.', '', 89875, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sir, our scouts report that the Horde forces are working to empower an ancient earth fury!', '', 89874, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Something resembling sap drools out of Acanthus\' mouth.', '', 89873, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes sir!', '', 89872, 0, 0, 66, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thank you for your report, soldier. You may return to the field.', '', 89871, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('I\'ll have Sprocket ready one of his tanks to pay them a visit. We\'ll see how their stones fare against steel.', '', 89870, 0, 0, 25, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('So the ogres like to throw stones, do they?', '', 89869, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It seems the ogres at Brute\'s Rise are employing large beasts to hurl giant boulders at our troops!', '', 89868, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Dark Lady save us all... it\'s worse than I thought.', 89867, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'No one pulls a fast one on me.', 89866, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('By all that is unholy, what is that thing?', '', 89865, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'What are you lookin\' at?', 89864, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I shoot to kill.', 89863, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Loosen yer belts, ladies! We\'re eatin\' a feast tonight!', '', 89862, 0, 0, 71, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Plunder their supplies then grab a wyvern back to Warspear Outpost!', 89861, 0, 36471, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Retreat quickly, Alliance reinforcements are arriving soon!', 89860, 0, 36471, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Alliance soldiers, we must leave now! Horde reinforcements are on their way.', 89859, 0, 36470, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Alliance soldiers, take their supplies quickly and take a gryphon back to Stormshield Stronghold!', 89858, 0, 36470, 70, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('De Alliance can\'t have Ashran, $c. Da powa of any Ogre artifacts here will be ours.', '', 89857, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Report from the field, sir!', '', 89856, 0, 0, 66, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The artifact fragments contain enough magical power to restore this Earth Fury to full strength. $B$BHow many have you brought us?', '', 89855, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Look around you. Can you not see that we have already won?', '', 89854, 0, 29905, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Kronus is born! Good work, $n.', '', 89853, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hurry $n, Volrath has ordered you to return to Warspear at once!', 'Hurry $n, Volrath has ordered you to return to Warspear at once!', 89852, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Poisoning', 'Poisoning', 89851, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It\'s quiet over here, don\'t you think? Almost... too quiet.', '', 89850, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('How did you get over here?', '', 89849, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Accidents? What kind of accidents?', '', 89848, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You get no argument from me, there.', '', 89847, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I don\'t like the sound of that. I think I\'ll just stay here at the inn.', '', 89846, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Weird ones. Solid cave walls up and crumbling on a digger. Malfunctioning machinery chewing up its operator. They say it happens more and more the further down you go.', '', 89845, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I spoke to one of the workers, and they think the place is haunted. They say folks are disappearing, and then there\'s the accidents.', '', 89844, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Why do you think that is?', '', 89843, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('So I hear that they\'re uncovering some interesting stuff in the mines. Harrison is staying pretty hush hush about it though.', '', 89842, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Spirit ogres? Geez, this island sure has some creative ways to kill a guy.', '', 89841, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If you think the ogres are bad, you should see the spirit ogres around that altar. Bad news, there.', '', 89840, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I don\'t know why Harrison Jones asked us to come out here and help with the excavation. I can\'t hunt for a single artifact without an ogre trying to cut me in half!', '', 89839, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I... see...', '', 89838, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Where else do you think one of them things would keep its loot?', '', 89837, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You found a knife in the stomach of a goren? What made you even think of cutting it open?', 89836, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Good luck, champions! May the strongest among you earn glory in the Coliseum today!', '', 89835, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Get on the platform! The elevator will begin its glorious ascent into the arena shortly!', '', 89834, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('That\'s it, get bunched up on the platform. You don\'t want to be left behind down here. No, not with the poison gas that we\'ll be releasing in here to clear out cowards.', '', 89833, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Once that elevator starts moving this room will flood with deadly poison gas, killing anyone left behind. I suggest you get aboard the platform.', '', 89832, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Belly of one of them goren.', '', 89831, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh yeah? Where did you find it?', 89830, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I got myself a shiny new knife when I was out scouting today.', '', 89829, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Let me guess, subtlety not your strong suit?', 89828, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Board the platform. It will take you to the arena floor, where glory awaits!', '', 89827, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Fly me to Stormshield Hold.', 'Fly me to Stormshield Hold.', 89826, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yeah, one of em saw me. Knife to the eye took care of that.', '', 89825, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Did you, now? Were you spotted?', 89824, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I came across a Horde patrol trying to sweep around one of our outposts today.', '', 89823, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Welcome, gladiators! You have been hand selected by Imperator Mar\'gok himself to participate in these gladiatorial games! An honor this great is reserved only for the most bloodthirsty and savage fighters of Draenor. May honor and victory be yours today!', '', 89822, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Commander I don\'t know what contractors you\'re using but if you ask me this looks like a Horde base.', '', 89821, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
