('', 'With gear that poor I\'m not surprised you lost.', 88081, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Shoddy equipment, shoddy fighting.', 88080, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Begone!', 88079, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will not let you pass!', 88078, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'In memory of Ared!', 88077, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'This\'ll be easier than working the forge.', 88076, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'For the fallen!', 88075, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('May you rest in pieces.', 'May you rest in pieces.', 88074, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A noble sacrifice.', 'A noble sacrifice.', 88073, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
