INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('Your sacrifice is a valuable lesson to us all.', 'Your sacrifice is a valuable lesson to us all.', 88071, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A most unfortunate end.', 'A most unfortunate end.', 88070, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('And to think... that could have been me.', 'And to think... that could have been me.', 88069, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Such a pity.', 'Such a pity.', 88068, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If only you had some skill.', 'If only you had some skill.', 88067, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'As you wish, commander. The Iron Horde will suffer.', 88066, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('And that\'s... one hundred.', '', 88065, 0, 0, 0, 64, 0, 44513, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'If you play with me, you are playing with fire... literally.', 88064, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('No formations... no tactics... this is a brawl, not a battle!', '', 88063, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Emperor protects me!', '', 88062, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('An Imperial battalion would be done with this fight already!', '', 88061, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is almost too easy!', '', 88060, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Welcome, commander. Please let me know if there is anything I can do to make your stay more comfortable.', 88059, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Vivianne is just down the hill. She\'s a bit of a pyro, but her passion for battle is palpable.', 88058, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It is done! As for you, I think it is fitting that one of my tools dispatches the others...', 88053, 0, 0, 0, 70, 0, 0, 43644, 0, 0, 0, 0, 0, 0, 39653),
('Boss-mon! Ya here too? Phew... I was startin\' ta tink I made da bad call. Let\'s win dis war for da Horde!', '', 88052, 0, 0, 0, 64, 0, 0, 0, 66, 0, 0, 0, 0, 0, 39653),
('Commander! Oh wow, didn\'t expect to see you out here. While you\'re here, you wanna trade for some blueprints?', '', 88051, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Everyone is a little on edge with the Iron Horde\'s presence looming. Your visit here is much appreciated.', 88050, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Lieutenant Kragil is just inside. It\'s been a pleasure serving you, commander.', '', 88049, 0, 0, 0, 64, 0, 0, 0, 66, 0, 0, 0, 0, 0, 39653),
('I greet you, $C. We are the Order of the Awakened, and we represent the best interests of the arakkoa people.\n\nI am certain that you have witnessed the horrors brought upon the arakkoa and others by the Adherents of Rukhmar. We wish to reverse this damage and bring about a peaceful new era for our society. To do this, however, we require the knowledge of the Apexis.\n\nIf you wish to assist us, we will trade valuable items for any Apexis relics you happen upon. What say you, $C?', '', 88048, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Someday, your blood will coat its edge. It is only a matter of time.', 88047, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hey! No registered contenders in the ring, please!', '', 88046, 0, 0, 22, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Shut your mouth, goblin, unless you want me to shut it for you. I just want a taste of this one\'s skill.', 88045, 0, 0, 396, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Find respite in the shadows.', '', 88044, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Only da very best be fightin\' in the ring.', '', 88043, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Don\'t be scared Rosie, we are safe here.', 88042, 0, 0, 1, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You seem surprised to see us here, $C. It is understandable. I am all too familiar with how the arakkoa have treated your people.\n\nThe Adherents of Rukhmar are savage creatures, and their lust for power can only lead to their downfall. We seek a different path.\n\nWe search for artifacts of the Apexis so that we may use them to initiate a peaceful new beginning for the arakkoa. In exchange for these relics, we offer finely crafted goods, which we hope you will find equal in value.\n\nWould you see it fit to aid us, $C?', '', 88041, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stick to the plan, chums!', '', 88040, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('At least I have chicken.', '', 88039, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It\'s not my fault.', '', 88038, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We are pals for life.', '', 88037, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Uh, what did you say?', '', 88036, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sorry, did you say something?', '', 88035, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Great job, guys!', '', 88034, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Time\'s up. Let\'s do this!', '', 88033, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Leeroooooooy! Jeeeeenkins!', '', 88032, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It was... an... honor.', '', 88031, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('How long must we stay in this \'garrison\' of yours?', '', 88030, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Any news of the Burning Blade?', '', 88029, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Honor is everything.', '', 88028, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My blade hungers.', '', 88027, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I miss the grassy plains of Nagrand.', '', 88026, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Throm-Ka, $n.', '', 88025, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Lok-Regar. I am ready for something new.', '', 88024, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It\'s good to see you again, $n.', '', 88023, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I yearn for a true adversary.', '', 88022, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Anyone else?', '', 88021, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A clean death was more than you deserved.', '', 88020, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I salute you.', '', 88019, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('At least you didn\'t run.', '', 88018, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
