INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('So much power! I am invincible!', '', 80594, 0, 0, 0, 64, 0, 43923, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thank you, friend! Till we meet again!', '', 80593, 7, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Please! I have so much more to see before I die.', '', 80592, 7, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I should have stayed in Shadowmoon Valley.', '', 80591, 7, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t bite me! I will not harm you... Seriously, don\'t do it.', '', 80590, 7, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Mole machine, go home!', 'Mole machine, go home!', 80589, 7, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The thunderlord... will rise...  again...', '', 80588, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('No!!! I will tear you apart for that! You will be avenged, Gutgore!', '', 80587, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Lok-Narash!', '', 80586, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You need somethin\' done right? You\'re talkin\' to the right guy...but the right guy ain\'t cheap.', '', 80585, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'That Grulk guy sure is incredible, ain\'t he? Mutated against his will...out for revenge...HUGE rippling biceps...a girl can only dream.', 80584, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thank you for your aid, adventurer. Meet me back at camp and we will discuss matters further.', 80583, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Die beast, and know that whatever hell you fall into will be more merciful than I!', 80582, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Come on! You might like it.', '', 80581, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t knock it till you try it.', '', 80580, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have got to try this!', '', 80579, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m almost done! Just one more time.', '', 80578, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'As for you beast, flee if you must, but my arrows will catch you!', 80577, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '*Sigh*', 80576, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Are you done yet?', 80575, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'This is a waste of time.', 80574, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hurry up... we have work to do.', 80573, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Give your souls to Teron\'gor. Gorge yourselves in his power!', 'Give your souls to Teron\'gor. Gorge yourselves in his power!', 80572, 0, 0, 25, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Nothing can stop our power! Not the Iron Horde, not the draenei, we are invincible!', 'Nothing can stop our power! Not the Iron Horde, not the draenei, we are invincible!', 80571, 0, 0, 53, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The draenei will crumble under our combined might, brothers and sisters!', 'The draenei will crumble under our combined might, brothers and sisters!', 80570, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Witness the infinite power of the Legion!', 'Witness the infinite power of the Legion!', 80569, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pledge yourself to the master and you will receive untold power!', 'Pledge yourself to the master and you will receive untold power!', 80568, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'This isn\'t some romantic \"rescue the princess from the tower\" situation. This is a torture room and I\'m in a freakin\' cage! Get me outta here!', 80567, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Don\'t mind me, I\'ll just wait here in my cage while you continue NOT letting me out! The key is in that chest over there!', 80566, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'m locked in here, you\'ll need to get the key. It\'s in the chest by the wall!', 80565, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Boy am I glad to see you! The key is in that chest over there, be a pal and let me out will yah?', 80564, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'What are you staring at? Go grab the key from the chest and let me out!', 80563, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The key is in the chest by the wall, go grab it and let me out!', 80562, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oh, ye poor thing. You\'ll not be forgotten!', '', 80561, 0, 0, 18, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('GAH!!', '', 80560, 0, 0, 5, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There ye go... easy on the turn now... easy...', '', 80559, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Suit! Go home!', '', 80558, 0, 0, 25, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Champion, take control of the cannon! If they get close, use the flames... hahahahaha!', '', 80557, 0, 0, 0, 64, 0, 45741, 0, 0, 0, 0, 0, 0, 0, 39653),
('It isn\'t safe to fire this thing near kids! But I bet the concussion from shooting blanks would blast open those doors...', '', 80556, 0, 0, 0, 64, 0, 45742, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thaelin, get that tank down here.', 80555, 0, 0, 0, 64, 0, 0, 45589, 0, 0, 0, 0, 0, 0, 39653),
('Barricade! On it!', '', 80554, 0, 0, 0, 64, 0, 44489, 0, 0, 0, 0, 0, 0, 0, 39653),
('I fear that even with the Heart intact, Auchindoun\'s defenses may not be enough. The Shadow Council has eyes everywhere.', '', 80553, 0, 0, 1, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gazlowe...', '', 80552, 0, 0, 0, 64, 0, 45287, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gazlowe, get rid of that barricade!', '', 80551, 0, 0, 0, 64, 0, 45285, 0, 0, 0, 0, 0, 0, 0, 39653),
('NO! Noooooooooooooooooooooooooooooooo!', '', 80550, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My power... it fades!', '', 80549, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('No! The ritual is incomplete! Who dares to interrupt my arrival?', '', 80548, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$ns drop from the ceiling!', '', 80547, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Whispers... slithering behind my EYES!', '', 80546, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Crush, crack, splinter! AHAHAHahahaha...', '', 80545, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wow! Thanks! I can find my way out of here now. I\'m sure I won\'t get captured again. See ya!', '', 80544, 0, 0, 0, 71, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The creatures around here are a pain to deal with.$b$bI\'ve taken to placing some of my food and prized possessions up high to avoid any unwanted incidents.', '', 80543, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m glad you showed up. We were going to be killed next!', '', 80542, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('They killed my family!', 'They killed my family!', 80541, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There\'s no hope! Run!', 'There\'s no hope! Run!', 80540, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Where are the Auchenai? Why is no one saving us?', 'Where are the Auchenai? Why is no one saving us?', 80539, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('They\'re eating us alive... literally!', 'They\'re eating us alive... literally!', 80538, 0, 0, 22, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Run for your lives!', 'Run for your lives!', 80537, 0, 0, 22, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Protector! Destroy these intruders!', 80536, 0, 0, 0, 70, 0, 0, 43645, 0, 0, 0, 0, 0, 0, 39653),
('', 'But nothing will stop my plan, nor that of my masters. And the only things in our way...', 80535, 0, 0, 0, 70, 0, 0, 43640, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your efforts were valiant. I did not think the anchorites could power the defenses with only one of the crystals.', 80534, 0, 0, 0, 70, 0, 0, 43639, 0, 0, 0, 0, 0, 0, 39653),
('', 'Yes, Tuulani. Now you see.', 80533, 0, 0, 0, 70, 0, 0, 43638, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'d better meet back up with the squad. Regroup with us once you\'ve destroyed the lab!', 80532, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We gotta bust up this mutation laboratory before it\'s too late! Grulk will fill you in on the details.', 80531, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Grulk rhyme now!$b$bSmash the baddies! Smash them up!$b$bSmash them till fit in soup cup!', '', 80530, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('SMASH!!!', '', 80529, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Grulk was mutated against his will by the Iron Horde and then locked up for being angry over it. Can you believe that?!', 80528, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Something need smashing?', '', 80527, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('To smash? Or not to smash? Dis Grulk question.', '', 80526, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Do me a favor and release Grulk from his cage...don\'t worry, he\'s cool.', 80525, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thanks pal! I\'d hug yah, but we don\'t have much time...', 80524, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thank the stars you arrived, hero! We are all that is left of Telmor.', 80523, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Take one step closer and I\'ll gut you like a fish, orc!', 80522, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('NOTUSED', '', 80521, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take my sword, which rests upon the stone. May it guide you when your faith falters, hero.', '', 80520, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have delivered me from his curse. You have restored my faith, champion.', '', 80519, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Afterward, I wandered. Blind and alone, and severed from the Light. Even in my dying moment, I felt I had been forsaken.', '', 80518, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I did not see the sun priest arrive, but I heard the flutter of his wings, and felt his gloating breath on my face, and then, moments later, felt him die on my blade.', '', 80517, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('In that moment, I knew true terror.', '', 80516, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I prayed once last time, although where there had once been everlasting divinity, now, I felt only emptiness.', '', 80515, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I alone remained to face him. My sight was nearly gone, and the Light no longer answered my prayers.', '', 80514, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We knew the sun priest would come one last time to claim his victory.', '', 80513, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My village bled slowly. Many fell to his sorcery. I, too, fell under his abominable curse... the \"sun sickness.\"', '', 80512, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('An arakkoa sun priest has come, seeking dominion over our lands.', '', 80511, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I... I can feel the Light again! I am freed of her curse. I... I see the way to Auchindoun.', '', 80510, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The old paladin suddenly gasps. A look of rapture crosses his face and he blinks, seeing you for the first time.', '', 80509, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I alone will stand against you. I will turn you back from these lands!', '', 80508, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The darkness closes in. I can no longer feel the Light. YOU! You did this!', '', 80507, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Auuugghhh! What have you done? The sun... it blinds me! It burns! IT BURNS!', '', 80506, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have seen your kind before, flying among the mountains to the south. Why have you come here?', '', 80505, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Grommar is a perfect example of the Alliance not knowin\' how to get the job done right...', '', 80504, 0, 0, 0, 64, 0, 40026, 0, 0, 0, 0, 0, 0, 0, 39653),
('Defend the shard! It must reach Lord Teron\'gor!', '', 80503, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Explosions, sabotage, demolition...all in a day\'s work friend.', '', 80502, 0, 0, 0, 64, 0, 40026, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'And why do you think we need your help, \'blood elf\'? We Auchenai are sworn to Auchindoun\'s protection.', 80501, 0, 0, 396, 64, 0, 0, 43632, 0, 0, 0, 0, 0, 0, 39653),
('Welcome to Anchorite\'s Sojourn, traveler. It is here that the devout gather for pilgrimage to the Temple of Karabor.', '', 80500, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our town is safe thanks to all of you. Today we have given the arakkoa a taste of our steel. Steady hearts, anchorites! We will stay vigilant.', '', 80498, 0, 0, 1, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Finally, we have drawn out their leader! Face us, you feathered tyrant!', '', 80497, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Will their numbers never cease? Muster your courage, friends. We will not be taken so easily!', '', 80496, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('More birds on the horizon, my comrades. Send them back to the Spires of Arak, where they belong!', '', 80495, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('To arms, anchorites! The arakkoa are coming! Hero, lend us your aid!', '', 80494, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Auchindoun will be mine! I will devour every last soul and bathe the ashes in hellfire!', '', 80493, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It is no matter. These souls are mine. My power grows.', '', 80492, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your head will be mine!', '', 80491, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s calls in a distant |cFFFF0000Siegemaker|r!', '', 80490, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hold your ground. We have to protect the wounded!', 80489, 0, 0, 0, 64, 0, 0, 44642, 0, 0, 0, 0, 0, 0, 39653),
('See what I have?! No mess with me! Or you next.', '', 80488, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I kill you! I eat you!', '', 80487, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You no try and fight me! Now you food!', '', 80486, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m strongest! This food is mine! Stay away!', '', 80485, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You friend to Grulk...Grulk not forget what you done.', '', 80484, 0, 0, 0, 64, 0, 40026, 0, 0, 0, 0, 0, 0, 0, 39653),
('Grulk done wit\' Iron Horde...Grulk go now.', '', 80483, 0, 0, 0, 64, 0, 40026, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pathetic creature! Unhand me!', '', 80482, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Drop me now you beast!', '', 80481, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will give you a swift death!', '', 80480, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Put me down!', '', 80479, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Protect that with your life! We need it to power Auchindoun\'s defenses!', 80478, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Soulbinder Nyami sent me to bring the Shard of Souls to safety.', 'Soulbinder Nyami sent me to bring the Shard of Souls to safety.', 80477, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It is my sworn duty to protect this tomb and its grounds.$B$BWe will fight to the last to prevent these orcs from taking the Shard of Souls!', 80476, 0, 0, 0, 64, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I don\'t know... Roc\'tar doesn\'t look so good.', '', 80475, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bathe in the glory of the Light!', '', 80474, 0, 0, 0, 65, 0, 46438, 0, 0, 0, 0, 0, 0, 0, 39653),
('Light guide you.', '', 80473, 0, 0, 0, 65, 0, 46437, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Light guide my hand!', '', 80472, 0, 0, 0, 65, 0, 46439, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will strike you down.', '', 80471, 0, 0, 0, 64, 0, 46434, 0, 0, 0, 0, 0, 0, 0, 39653),
('None live who assault the holy Auchenai.', '', 80470, 0, 0, 0, 65, 0, 46436, 0, 0, 0, 0, 0, 0, 0, 39653),
('Auchindoun... is... doomed...', '', 80469, 0, 0, 0, 65, 0, 46435, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Agamaggan will rise again!', 80467, 0, 0, 0, 64, 0, 0, 41872, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hah! My power rules here.', 80466, 0, 0, 0, 64, 0, 0, 41874, 0, 0, 0, 0, 0, 0, 39653),
('', 'The undertow will consume you!', 80465, 0, 0, 0, 64, 0, 0, 41877, 0, 0, 0, 0, 0, 0, 39653),
('', 'Drown in venom!', 80464, 0, 0, 0, 64, 0, 0, 41876, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will turn you into ash!', 80463, 0, 0, 0, 64, 0, 0, 41875, 0, 0, 0, 0, 0, 0, 39653),
('', 'Insignificant whelps, what makes you think you can challenge me?', 80462, 0, 0, 0, 64, 0, 0, 41871, 0, 0, 0, 0, 0, 0, 39653),
('', 'I see you, interlopers. You tread on sacred ground...', 80461, 0, 0, 0, 64, 0, 0, 41873, 0, 0, 0, 0, 0, 0, 39653),
('You are weak.', '', 80460, 0, 0, 0, 64, 0, 41571, 0, 0, 0, 0, 0, 0, 0, 39653),
('Who dares wake me?', '', 80459, 0, 0, 0, 64, 0, 41570, 0, 0, 0, 0, 0, 0, 0, 39653),
('The stones spoke of your demise.', '', 80458, 0, 0, 0, 64, 0, 41662, 0, 0, 0, 0, 0, 0, 0, 39653),
('Another trophy for the pen.', '', 80457, 0, 0, 0, 64, 0, 41949, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hunters, arm your traps. I smell something...', '', 80456, 0, 0, 0, 64, 0, 41948, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Keep your eyes open... The stones speak of trouble...', 80455, 0, 0, 0, 64, 0, 0, 41846, 0, 0, 0, 0, 0, 0, 39653),
('Yeah, you\'ll be fine. I just forgot to adjust my sights last time.', '', 80451, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you sure this is a good idea?', '', 80450, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('NO MORE!! GRULK CRUSH!!', '', 80449, 0, 0, 0, 64, 0, 40026, 0, 0, 0, 0, 0, 0, 0, 39653),
('This place where Grulk change...where old self die...', '', 80448, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Grulk is strongest one there is!! Rrrrgh!!', '', 80447, 0, 0, 0, 64, 0, 40026, 0, 0, 0, 0, 0, 0, 0, 39653),
('Grulk so tired...just want nap.', '', 80446, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Grulk Smash!! Rarggah!!', '', 80445, 0, 0, 0, 64, 0, 40026, 0, 0, 0, 0, 0, 0, 0, 39653),
('Feel weak...Grulk need serum...', '', 80444, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Grulk gonna pound you all!! Rargrh!!', '', 80443, 0, 0, 0, 64, 0, 40026, 0, 0, 0, 0, 0, 0, 0, 39653),
('Careful - we have a tough enemy cornered in there.', 'Careful - we have a tough enemy cornered in there.', 80442, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our clan grows stronger by the second.', '', 80441, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Rise and serve your master!', 80436, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Sky Rider\'s have noticed your presence!', 'The Sky Rider\'s have noticed your presence!', 80435, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Find a way to destroy the Supply Depot!', '', 80434, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'There is another I hunt within these caves. I leave this kill to you.', 80433, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If you want something done, you have to do it yourself!', '', 80432, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you sure this is a good idea?', '', 80431, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The hunt comes to an end. Quickly, drink this antidote! The spider\'s venom will no longer affect you!', 80430, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We did it! I... I can\'t thank you enough, stranger. I don\'t have much, but I want you to have this.', '', 80429, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is it, friend. Let\'s cut them off at the head!', '', 80428, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Heh, you\'ve got some fight in you, traveler. Ready for more?', '', 80427, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stay if you want, traveler. I\'ll die before letting these dogs take my home. Watch out! They come!', '', 80426, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do you need help?', 'Do you need help?', 80425, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pardon my rudeness, traveler. I did not know you from the enemy.$B$BThe Shadow Council has tried to raid my home several times now.$B$BThe first time, they didn\'t expect much resistance from an old hermit like me. I put arrows into the throats of three.$B$BThe second time, I was prepared. Four orcs blundered right into my traps. Stupid mongrels.$B$BI made them angry, and now, I\'m waiting for them to come again.$B$BI hope they send more. It just means that many more will die.', '', 80424, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stop! Who goes there? Go away before I put an arrow in your eye!', '', 80423, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ability_fixated_state_red:20|tA %s |cFFFF0000|Hspell:156653|h[Fixates]|h|r on you. Run!', '', 80422, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Feel free to take some fish. They are delicious.', '', 80421, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('When you live in a savage world like we do, sometimes you just want to get away.$b$bThat\'s why we left the war behind.', '', 80420, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I could eat an orc.', 'I could eat an orc.', 80419, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We don\'t want any trouble, $c. We stopped fighting a long time ago.', '', 80418, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Something flickers in the shadows, growing closer...', 'Something flickers in the shadows, growing closer...', 80417, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A chittering sound echoes across the trees, then fades...', 'A chittering sound echoes across the trees, then fades...', 80416, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A chill wind howls across the empty hills...', 'A chill wind howls across the empty hills...', 80415, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s hisses, slinking back into the shadowy depths!', '%s hisses, slinking back into the shadowy depths!', 80414, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Dismantling', 'Dismantling', 80413, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We will take the west!', 80412, 0, 0, 0, 64, 0, 0, 45591, 0, 0, 0, 0, 0, 0, 39653),
('', 'They have children in those buildings!', 80411, 0, 0, 0, 64, 0, 0, 44750, 0, 0, 0, 0, 0, 0, 39653),
('', 'We will hold off Blackhand! Destroy that weapon!', 80410, 0, 0, 0, 64, 0, 0, 45592, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thaelin, use your tank to save them! We will provide escort.', 80409, 0, 0, 0, 64, 0, 0, 45590, 0, 0, 0, 0, 0, 0, 39653),
('For Shattrath!', '', 80408, 0, 0, 0, 64, 0, 44786, 0, 0, 0, 0, 0, 0, 0, 39653),
('It is YOU who would make Draenor burn. It is YOU who must be stopped!', '', 80407, 0, 0, 25, 64, 0, 46071, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will not slay so many innocent people!', '', 80406, 0, 0, 5, 64, 0, 46070, 0, 0, 0, 0, 0, 0, 0, 39653),
('Champion! Speak with me when you are ready to travel to the enemy battleship.', '', 80405, 0, 0, 0, 64, 0, 44899, 0, 0, 0, 0, 0, 0, 0, 39653),
('Only the harbor remains between us and the weapon!', '', 80404, 0, 0, 0, 64, 0, 44898, 0, 0, 0, 0, 0, 0, 0, 39653),
('The children are safe! Their lieutenants are exposed!', '', 80403, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('They\'re retreating to the harbor!', '', 80402, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Prepare for a counter-attack!', '', 80401, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Together, we fight!', '', 80400, 0, 0, 0, 64, 0, 44897, 0, 0, 0, 0, 0, 0, 0, 39653),
('You got it, boss!', '', 80399, 0, 0, 0, 64, 0, 44488, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will get the children to safety!', 80398, 0, 0, 0, 64, 0, 0, 44751, 0, 0, 0, 0, 0, 0, 39653),
('', 'I will hold off reinforcements at the docks!', 80397, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Lok\'tar ogar!', 80396, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, I will see Draenor burn. You, traitor, will not.', '', 80395, 0, 0, 0, 64, 0, 45470, 0, 0, 0, 0, 0, 0, 0, 39653),
('Innocent?!', '', 80394, 0, 0, 15, 64, 0, 45469, 0, 0, 0, 0, 0, 0, 0, 39653),
('Auchindoun will soon be ours. Too bad you won\'t be around to see it, elf.', 'Auchindoun will soon be ours. Too bad you won\'t be around to see it, elf.', 80393, 0, 0, 153, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Brother!', '', 80392, 0, 0, 0, 64, 0, 45288, 0, 0, 0, 0, 0, 0, 0, 39653),
('Orgrim, you will answer for your betrayal!', '', 80391, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We will take the east!', '', 80390, 0, 0, 0, 64, 0, 45286, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gazlowe, buy us some time!', '', 80389, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Lok-Narash!', '', 80388, 0, 0, 0, 64, 0, 45284, 0, 0, 0, 0, 0, 0, 0, 39653),
('Can\'t we talk this through?', '', 80387, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I should have never left Azeroth!', '', 80386, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Nixxie! Help!', '', 80385, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Whoa! What did I do?!', '', 80384, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sorry! I just work here!', '', 80383, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We are all entitled to our own opinion. Yours is just wrong. NOW GET BACK TO WORK!', 80382, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Well done, champion! We will do our best to repair this unit. Thank you.', 'Well done, champion! We will do our best to repair this unit. Thank you.', 80381, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stay back! It\'s on a rampage!', 'Stay back! It\'s on a rampage!', 80380, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pull the third lever to destroy the Ultrabliterator!', '', 80379, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pull the second lever to overdrive the engine!', '', 80378, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pull the first lever to increase combustion!', '', 80377, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Shutting Down', 'Shutting Down', 80376, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thank you, Yrel. I don\'t know what\'s coming over me.', '', 80375, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Very well.', '', 80374, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('And I.', '', 80373, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I, too, will follow you.', '', 80372, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m with you, Yrel.', '', 80371, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Rest now. I will lead our attack on the Naval Base.', 80370, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '[UNUSED]', 80369, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You have been through too much, Maraad. Your thirst for vengeance will only lead to our death.', 80368, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yrel...', '', 80367, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Maraad, my love. That\'s enough.', 80366, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('[UNUSED]', '', 80365, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I saw the naaru\'s vengeance in the Purge of Grommar. I was there as K\'ara herself unleashed holy death upon the filthy hordes.', '', 80364, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Vengeance.', '', 80363, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Light has not left me, Thaelin. No... the Light has finally shown me its true form.', '', 80362, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are any of you more holy than me? I am the LEADER of this expedition, and I will not be questioned any further!', '', 80361, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I carry no particular love for the Light, but I agree. You need to remember what you stand for, Vindicator.', '', 80360, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Light\'s left ye. Even I can see that.', '', 80359, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ye\'ve gone too far, Maraad.', '', 80358, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The prophet is DEAD, Yrel. Look what his teachings did for him.', '', 80357, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '...but perhaps you are taking your vengeance too far. Have you forgotten what the Prophet taught us?', 80356, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Maraad... I am honored...', 80355, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will make them feel the pain I felt when I lost you, Yrel.', '', 80354, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We will slay as many of the vile things as we can. We will burn their homes and show them fear.', '', 80353, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'What is our plan, Maraad?', 80352, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There will never be a better time than this. Let us head to the Naval Base and exact our vengeance on the Iron Horde!', '', 80351, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Iron Horde\'s supply lines are now cut, however temporarily. We have forged our alliance with the Shapers.', '', 80350, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Maraad, you\'re frightening me.', 80349, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('But first, we will make these orcs suffer for what they did to you. Their sins cannot be forgiven.', '', 80348, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, Yrel. You will have a home on Azeroth.', '', 80347, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I was thinking I might go through the portal with you, my love.', 80346, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We are draenei, Yrel. Being without a home is in our nature.', '', 80345, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'With Velen gone, I feel like I don\'t have a home anymore.', 80344, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What about you, lassie? Will ye go home?', '', 80343, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Once I\'ve found me Ellie, I know I\'ll be headed back ta Searin\' Gorge.', '', 80342, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I dunno how much you\'ve heard about Azeroth, ma\'am, but we\'ve got our fair share of war, too.', '', 80341, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '<sigh> This land is plagued by war. Do you think you\'ll return to the safety of home after our mission is done?', 80340, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Quite fine, ma\'am. Just happy to be out o\' combat and back in me Tank.', '', 80339, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thaelin, are you doing alright in there?', 80338, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our work here is done. Next, we head to the Planteau.', '', 80337, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our work here is done. Next, we head to Smokebelcher Depot.', '', 80336, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('Y\'know, that\'s the darkest, coldest, most inspirin\' thing I\'ve ever heard from the lips of a paladin.', '', 80335, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We will find your wife, Hansel. And we will leave a wake of bodies behind us. The orcs will pay with blood for what they did to our families.', '', 80334, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('That\'s half o\'why I\'m here: ta look after Thaelin, and ta get me wife back.', '', 80333, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ach... the Blackrocks took \'er away.', '', 80332, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Do you have a wife, Hansel?', 80331, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sounds like a crap job to me. Life ain\'t worth livin\' if y\'don\'t have lads and a lass t\'come home to.', '', 80330, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A rangari who is not lonely is not doing his job.', '', 80329, 0, 0, 0, 68, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
