('Curses!', 'Curses!', 79810, 0, 0, 14, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What on Draenor?!', 'What on Draenor?!', 79809, 0, 0, 274, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ahhh!', 'Ahhh!', 79808, 0, 0, 430, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Whoa!', 'Whoa!', 79807, 0, 0, 412, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Duck!', 'Duck!', 79806, 0, 0, 6, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('And here\'s where they caught up with her.', '', 79805, 7, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
