('INFERNO!', '', 77921, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Blood of Agamaggan, burn them!', '', 77920, 0, 0, 0, 64, 0, 41665, 0, 0, 0, 0, 0, 0, 0, 39653),
('Shards of earth, blind them!', '', 77919, 0, 0, 0, 64, 0, 41664, 0, 0, 0, 0, 0, 0, 0, 39653),
('The crystals speak to me. Today brings victory.', '', 77918, 0, 0, 0, 64, 0, 41661, 0, 0, 0, 0, 0, 0, 0, 39653),
('Great Boar, grant me strength!', '', 77917, 0, 0, 0, 64, 0, 41663, 0, 0, 0, 0, 0, 0, 0, 39653),
('By Agamaggan, I will END you!', '', 77916, 0, 0, 0, 64, 0, 41659, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m finding it difficult to put my trust in Zipfizzle.$b$bHe seems sincere, and his heart is full of light, but he is clearly using bubblegum to attach some of those wires together.', '', 77915, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gnomes, they seem more interested in their inventions than they do their own lives. Let us hope that ingenuity can actually benefit our efforts.', '', 77914, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We need to activate that crystal. But we can\'t just stand by and watch as these orcs build weapons to attack Karabor.', '', 77913, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653);
