INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('Time to mix business with pleasure.', '', 74627, 0, 0, 0, 65, 0, 38445, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oh, look. You\'re the ones that smashed up my Juggernaut.', '', 74626, 0, 0, 0, 70, 0, 38459, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let\'s see how you like the newest addition to the Warchief\'s arsenal... the Iron Star!', '', 74625, 0, 0, 0, 70, 0, 38460, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do you wish to begin the Norushen Encounter?', 'Do you wish to begin the Norushen Encounter?', 74624, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We are ready, Keeper.', 'We are ready, Keeper.', 74623, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My eternal vigil has kept the corruption of pride at bay. To face this corruption yourself you must purify yourselves in the burning light.  This process will not go easily for you.\n\nAre you ready?', '', 74622, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|cFFFF0000|Hspell:144985|h[Whirling Corruption]|h|r killed you.  Move away from Garrosh to decrease damage taken.', '', 74621, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Chelon has been engaged by $n the $r $c.', '', 74619, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Enter my realm.', '', 74617, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes... yes I can see now...I can see the future of this world...a world ruled by the horde...MY horde.', '', 74616, 0, 0, 0, 65, 0, 38051, 0, 0, 0, 0, 0, 0, 0, 39653),
('Anger. Hatred. Fear!! They are weapons of war - the tools of a Warchief!', '', 74610, 0, 0, 0, 65, 0, 38048, 0, 0, 0, 0, 0, 0, 0, 39653),
('Good! I\'ll just leave you to it!', '', 74608, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Well what are you waiting for?! Let\'s see!', 'Well what are you waiting for?! Let\'s see!', 74607, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oh hello! I was just about to reel in this catch. I have a hunch it\'s going to be a doozy!', '', 74606, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Uhhh.. you can handle this right?', '', 74605, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Well that was unexpected!', '', 74604, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Almost... got... it...', '', 74603, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There is a pained howl from deep within the woods.', '', 74602, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A sorrowful howling floats through the forest.', '', 74601, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('An anguished howl echoes in the twilight.', '', 74600, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You hear a mournful howl in the distance.', '', 74599, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Moonfang, Den Mother of Darkmoon Island, has been slain!', 74596, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '|cFFFF0000BEWARE:|r Den Mother Moonfang has appeared in the woods!', 74595, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '|cFFFF0000BEWARE:|r Moonfang Dreadhowls now prowl the woods!', 74594, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We did it men, we saved The Barnacle! Finally, a moment of rest since we entered this forsaken mist. Turn the sails, men. We\'re goin\' home!', '', 74593, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('By Firallon\'s beard, what is that thing? Kill it!', '', 74592, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pick up the hammer.', 'Pick up the hammer.', 74591, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The hammer is warm to the touch.', 'The hammer is warm to the touch.', 74590, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Fight fer yer lives, mateys! If The Barnacle\'s going down, we\'re going down with her!', '', 74589, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Look out! Another wave comes!', '', 74588, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Steel yourselves, men! We\'re bein\' boarded!', '', 74587, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ability_mage_firestarter.blp:20|t|cFFFF0000Siege Engineers|r appear in the wings and begin to cast |cFFFF0000|Hspell:144616|h[Power Iron Star]|h|r!', '', 74586, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s shifts into Siege Mode!', '', 74585, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s shifts back into Assault Mode!', '', 74584, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s begins to cast |cFFFF0000|Hspell:144590|h[Moonfang\'s Curse]|h|r.', 74580, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hi there, $n!  It\'s great to see you again.  Everyone is still talking about the last time you won the tournament... I didn\'t get to see all of it, but I had to heal a lot of burns and bruises.  But don\'t worry, they\'re fine now!', 74578, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Welcome, traveler! I have treasure from all across the world.$B$BYou want to test your luck? Only a few timeless coins for a key.', '', 74577, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wise hozen say: Don\'t put off until tomorrow what you can do... oh nevermind, I\'ll tell you the rest later.', '', 74576, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wise hozen say: If at first you don\'t succeed, get someone else to do it for you.', '', 74575, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wise hozen say: Actions speak louder than words, unless the person is yelling.', '', 74574, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wise hozen say: Don\'t bite off more than you can chew, unless there are other hungry hozen nearby.', '', 74573, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wise hozen say: Appearances can be deceiving, especially if you have bad eyesight.', '', 74572, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wise hozen say: To seek riches, look within yourself. Or in one of these chests.', '', 74571, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wise hozen say: All that glitters is not gold. Unless it is gold. Then it glitters.', '', 74569, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pay 5 Timeless Coins?', 'Pay 5 Timeless Coins?', 74568, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Pay 5 Timeless Coins for 1 Kukuru\'s Kache Key.', 'Pay 5 Timeless Coins for 1 Kukuru\'s Kache Key.', 74567, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Healing your pets will disqualify your current progress in the scenario, and you\'ll have to battle your opponents again.  Are you sure?', 'Healing your pets will disqualify your current progress in the scenario, and you\'ll have to battle your opponents again.  Are you sure?', 74566, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hello, $n.  My name is Oriana, and I attend the tournament to make sure no pets are grievously injured, and to explain the rules.\n\nYou cannot heal or revive your pets during the tournament.  If you run out of pets to use in battle, you can leave and enter the tournament again.\n\nIf you lose to a challenger, you may fight them again.', 74565, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Like you, I could not resist the opportunity to take part of this ancient Pandaren tradition.  When you are ready, let us see how well you can lead your pets in battle.', '', 74564, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
