('Where did Project C4T come from?', 'Where did Project C4T come from?', 74097, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I never seen this many Kor\'kron in one place before!$b$bThose orcs are as fierce as fierce gets and angry to boot. They must have upped their recruiting program.', '', 74096, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Horde brought back a hozen?! Dinna\' they had enough of those back in Pandaria?', '', 74095, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tell me again about the Warchief and the Darkness...', 'Tell me again about the Warchief and the Darkness...', 74094, 0, 0, 0, 71, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sittin\' in the middle of enemy forces with not much more than this cloaking chicken protectin\' us. This has become my new normal!', '', 74093, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I think I saw trolls being carted off in chains. Why would orcs be cartin\' trolls off in chains?', '', 74092, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tell me again about the King and the Council...', 'Tell me again about the King and the Council...', 74091, 0, 0, 0, 71, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This ol\' cloaking chicken better not fail. She\'s been actin\' up lately.', '', 74090, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What are the Kor\'kron?', 'What are the Kor\'kron?', 74089, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'They used to be an elite band of orcs created to serve the Warchief as protectors and enforcers of his command.$b$bNow they are an army of incredibly well trained destroyers. Garrosh\'s personal legion.', 74088, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('', 'The High King has no intention of letting Garrosh continue his mad campaign. It is costing too many innocent lives.$b$bWe are here to look for vulnerabilities in Orgrimmar\'s defenses. The sort of vulnerabilities that an Alliance army could take advantage of.$b$bUnfortunately, it looks like Garrosh has not been idle. He has stepped up recruitment of Kor\'kron and turned them into a full-fledged war machine.', 74087, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Why are you and Sully out here?', 'Why are you and Sully out here?', 74086, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Deadeye Kail sticks to his guns.', '', 74085, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|cFF0000FFQueue for Dark Heart of Pandaria.|r', '|cFF0000FFQueue for Dark Heart of Pandaria.|r', 74084, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
