('%s has purchased a Rodent Crate!', '%s has purchased a Rodent Crate!', 69469, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s has purchased a box of banners!', '%s has purchased a box of banners!', 69468, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
