('|TInterface\\Icons\\ability_warrior_battleshout.blp:20|tArmsmaster Harlan calls on two of his allies to join the fight!', '', 65526, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A Shado-Pan Novice has chosen you for |cFFFF0000|Hspell:106774|h[Honorable Combat]|h|r! They will attack you until they are defeated!', 'A Shado-Pan Novice has chosen you for |cFFFF0000|Hspell:106774|h[Honorable Combat]|h|r! They will attack you until they are defeated!', 65525, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
