('Tell me about the Tian mistweavers.', 'Tell me about the Tian mistweavers.', 64061, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tell me about the Vale marksmen.', 'Tell me about the Vale marksmen.', 64060, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tell me about the damaged cannons.', 'Tell me about the damaged cannons.', 64059, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tell me about the Tian disciples.', 'Tell me about the Tian disciples.', 64058, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tell me about the festival fireworks.', 'Tell me about the festival fireworks.', 64057, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tell me about Briaw Shan.', 'Tell me about Briaw Shan.', 64056, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tell me about the Krasarang Wild Brew.', 'Tell me about the Krasarang Wild Brew.', 64055, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We have a lot of visitors from all over Pandaria, surely they can help us with these raiders.', 64054, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '$p, let me know if you need any help with the village defenses!', 64053, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
