INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('', 'Your move.  I\'ll follow you in.', 62043, 0, 0, 0, 65, 0, 0, 31369, 0, 0, 0, 0, 0, 0, 39653),
('', 'We couldn\'t have done this without you, $p.  Thank you.', 62042, 0, 0, 396, 65, 0, 0, 31358, 0, 0, 0, 0, 0, 0, 39653),
('His sacrifice inspires us all.', '', 62041, 0, 0, 1, 65, 0, 30793, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Some consider these yaks to be lowly beasts, suitable only for grazing and menial labor. Few recognize the innate beauty that these creatures - the scions of the Black Ox - truly possess.', 62039, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'As is his will.  It is our sworn duty to see you confined, and he sees it done.', 62038, 0, 0, 396, 65, 0, 0, 31357, 0, 0, 0, 0, 0, 0, 39653),
('Clever Shado-Pan... I underestimated you.  But your leader is mine now.  You cannot free him without freeing me as well.', '', 62037, 0, 0, 0, 65, 0, 28343, 0, 0, 0, 0, 0, 0, 0, 39653),
('We are the protectors - immovable and unflappable.$b$bWhen we are moving, nothing can stop us from moving. When we are standing still, nothing can budge us.', '', 62036, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What is this?!  A trap?', '', 62035, 0, 0, 0, 65, 0, 28342, 0, 0, 0, 0, 0, 0, 0, 39653),
('I take pride in the fact that I am continuing my father\'s legacy here.$b$bA still-growing legacy, I might add.', '', 62034, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What brings you to our temple, $r?', '', 62033, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('As fodder for the swarm, perhaps!', '', 62032, 0, 0, 0, 65, 0, 32857, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Shackles, NOW!', 62031, 0, 0, 396, 65, 0, 0, 31356, 0, 0, 0, 0, 0, 0, 39653),
('Taran Zhu, you are a fool.  You escaped me only to return with your hatred broiling inside you.  You... are... MINE!', '', 62030, 0, 0, 0, 65, 0, 28341, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is your moment, Shado-Pan!  This is everything that you\'ve trained for!', '', 62029, 0, 0, 0, 65, 0, 28441, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hatred, come out and face your defeat!', '', 62028, 0, 0, 1, 65, 0, 28440, 0, 0, 0, 0, 0, 0, 0, 39653),
('Keep the mantid back!  We are almost done.', '', 62027, 0, 0, 1, 65, 0, 28439, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hold off the mantid!  This will not take long.', '', 62026, 0, 0, 1, 65, 0, 28438, 0, 0, 0, 0, 0, 0, 0, 39653),
('Demolishers are carrying explosives! Any direct hit will blow them up!', '', 62025, 0, 0, 25, 65, 0, 31504, 0, 0, 0, 0, 0, 0, 0, 39653),
('That mantid is its host.  Chain it down.  We will rip the hatred from its body!', '', 62024, 0, 0, 1, 65, 0, 28437, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Amberwing is flying in, watch out!', '', 62023, 0, 0, 25, 65, 0, 31503, 0, 0, 0, 0, 0, 0, 0, 39653),
('Everything that you are is MINE to destroy!', '', 62022, 0, 0, 0, 65, 0, 28340, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t die!', 'Don\'t die!', 62021, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re almost dead!', 'You\'re almost dead!', 62020, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You are near death!', 'You are near death!', 62019, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You are dying!', 'You are dying!', 62018, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Wakener may prove useful. One way or another.', '', 62017, 0, 0, 0, 65, 0, 31519, 0, 0, 0, 0, 0, 0, 0, 39653),
('No.', '', 62016, 0, 0, 0, 65, 0, 31518, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let\'s give it another shot!', 'Let\'s give it another shot!', 62015, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Right away, Klaxxi\'va.', '', 62014, 0, 0, 0, 65, 0, 30311, 0, 0, 0, 0, 0, 0, 0, 39653),
('We do not need help from the lesser races! Dispose of it!', '', 62013, 0, 0, 0, 65, 0, 32856, 0, 0, 0, 0, 0, 0, 0, 39653),
('This... \"filth\" defeated the adjunct and saw to my Wakening.', '', 62012, 0, 0, 0, 65, 0, 30310, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Klaxxi\'va you sent has fallen to an adjunct of Her majesty.', '', 62011, 0, 0, 0, 65, 0, 30309, 0, 0, 0, 0, 0, 0, 0, 39653),
('And what is this filth you\'ve brought to our sanctuary?', '', 62010, 0, 0, 0, 65, 0, 32855, 0, 0, 0, 0, 0, 0, 0, 39653),
