('|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFFFF0000$n has defended the Diamond Depot!|r', '', 60129, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I feel much safer with a $c like you around.', 60128, 0, 16137, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFF00AEEF$n has Defended the Diamond Depot!|r', '', 60127, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We hear so many conflicting stories about what\'s happening just out of sight. Tell me, $n, is it as bad as it sounds?', 60126, 0, 16137, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\inv_misc_gem_diamond_04.blp:20|t|cFFFF0000$n has assaulted the Diamond Depot!|r', '', 60125, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You look remarkably well, $n. I\'m exhausted. A healer\'s work is never done.', 60124, 0, 16137, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
