('', '$n, if you have the time later, perhaps you and I could sit and talk over tea?', 60122, 0, 16137, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Admiral Taylor and I were just speaking about you. How are you, $n?', 60121, 0, 16137, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Do you have any news from afar, $n? Has the war against the yaungol finally been won?', 60120, 0, 16137, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your prowess as a $c is unquestionable.', 60119, 0, 16137, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
