INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('', 'Finally! THERE\'S the Uncle Chen I\'ve been waiting for.', 56107, 0, 0, 11, 65, 0, 0, 30388, 0, 0, 0, 0, 0, 0, 39653),
('', '%s smiles.', 56106, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Li Li... let\'s go. Your uncle has got something to prove.', '', 56105, 0, 0, 1, 65, 0, 29681, 0, 0, 0, 0, 0, 0, 0, 39653),
('There is perhaps a way...', '', 56104, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('... indeed it was.', '', 56103, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It was a short time, for our part...', '', 56102, 0, 0, 18, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The grain we gather needs to be in large quantities for the brewery. But I may know of a grain that would suit your needs.', '', 56101, 0, 0, 1, 65, 0, 31031, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I have awakened only to sleep once again.', 56100, 0, 0, 18, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'They have failed us sister.', 56099, 0, 0, 18, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Why is all of your grain so bland?', 56098, 0, 0, 1, 65, 0, 0, 30400, 0, 0, 0, 0, 0, 0, 39653),
('Teleport to the garden entrance.', 'Teleport to the garden entrance.', 56097, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Welcome to the Temple of the Jade Serpent, stranger. Our doors are open to all who seek knowledge.', 56096, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You\'ve been a really big help here at the Temple!$B$BI heard the Elder Sage say that he\'s glad you arrived when you did.', 56095, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I would like to return to the temple grounds.', 'I would like to return to the temple grounds.', 56094, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you finding everything you need at the Temple?', '', 56093, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have a message for the Jade Serpent.', 'I have a message for the Jade Serpent.', 56092, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'d like to go inside the Temple of the Jade Serpent.', 'I\'d like to go inside the Temple of the Jade Serpent.', 56091, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Welcome to the Temple of the Jade Serpent. How may I help you?', 56090, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Careful with that there vial. She\'s a bit leaky.', '', 56089, 0, 0, 1, 65, 0, 32505, 0, 0, 0, 0, 0, 0, 0, 39653),
('So delicious!', '', 56088, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('More power!', '', 56087, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hee hee hee hee hee!', '', 56086, 0, 0, 0, 65, 0, 0, 0, 11, 0, 0, 0, 0, 0, 39653),
('Investigating', 'Investigating', 56085, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It is no use, the power of the Soul is too great. I cannot wield it safely; the raging forces within it may be the doom of us all.', '', 56084, 0, 0, 0, 64, 0, 25904, 0, 0, 0, 0, 0, 0, 0, 39653),
('The scrolls! I must save the scrolls!', '', 56083, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This library holds thousands of years of history and lore. The greatest knowledge in all of Pandaria is kept here.$B$BThat is why we must keep this great treasure safe.', '', 56082, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'They... are my clutch no longer.  Bring them down.', 56081, 0, 0, 18, 64, 0, 0, 26505, 0, 0, 0, 0, 0, 0, 39653),
('It is good to see you again, Alexstrasza. I have been busy in my absence.', '', 56080, 0, 0, 457, 64, 0, 26360, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our engines are damaged!  We\'re sitting ducks up here!', '', 56079, 0, 0, 0, 65, 0, 26303, 0, 0, 0, 0, 0, 0, 0, 39653),
('You may begin your ritual, we will defend you.', 'You may begin your ritual, we will defend you.', 56078, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Heroes, we must place this burden on your shoulders once again.  You must protect us from Deathwing\'s forces while we imbue the Soul with the powers of the great Aspects of Azeroth.', '', 56077, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Choose a pet to fight for you in battle!', 'Choose a pet to fight for you in battle!', 56076, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Azure Serpent needs some love!', '', 56075, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Azure Serpent licks itself.', '', 56074, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Azure Serpent wonders if you have a treat.', '', 56073, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Azure Serpent wants a snack.', '', 56072, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Azure Serpent is hungry!', '', 56071, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Azure Serpent plays with its own shadow.', '', 56070, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Emerald Serpent wants to play a game!', '', 56069, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Emerald Serpent is sleepy.', '', 56068, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Emerald Serpent tumbles through the air.', '', 56067, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Emerald Serpent tries to eat your hair, and then spits it out. Yuck!', '', 56064, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Emerald Serpent sniffs you.', '', 56063, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Emerald Serpent looks around curiously.', '', 56062, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Crimson Serpent is bored.', '', 56061, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Crimson Serpent nips at you experimentally.', '', 56060, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Gold Serpent pounces at the air.', '', 56059, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Crimson Serpent roars with vigor.', '', 56058, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Crimson Serpent makes a fearsome face.', '', 56057, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Crimson Serpent licks you.', '', 56056, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Gold Serpent chases its own tail.', '', 56055, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Gold Serpent rubs affectionately against your arm.', '', 56054, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Gold Serpent wants to be petted.', '', 56053, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Gold Serpent nips at you playfully.', '', 56052, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Gold Serpent makes a fancy flip.', '', 56051, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Playful Gold Serpent licks you.', '', 56050, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ve never seen anyone get a vision from these waters so easily.$B$BThen again, I can\'t remember the last time a jinyu came to visit us and then stuck his face in the water...', 56049, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'Could it be? Can the jinyu really tap into the water\'s power that easily?', 56048, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s ambushes his helpless prey!', '', 56047, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I can\'t even begin to describe it... you have to see this, $n.', '', 56046, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Something has disturbed the waters. They are normally so well-behaved.', '', 56045, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I know what your friend has seen, $n - he will need to rest for now. Come speak with me.', 56044, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Jinyu and their crazy rituals...', 'Jinyu and their crazy rituals...', 56043, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Water is life. When the waters feel torment, then so shall we.', '', 56042, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do not fear, little ones. Come shadow or light, the waters will always flow.', '', 56041, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Darkness comes. I can feel it within my bones.', '', 56040, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Little waters, if you would just stop moving so quickly, perhaps I could help you!', '', 56039, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I must speak to the waters to understand their turmoil.', '', 56038, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What... what is this place? It is beautiful... But... something is not right.', '', 56037, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There is nothing more that I can do for you, $n. Take what I have taught you, and use it elsewhere.', '', 56036, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('How can I serve, $n?', '', 56035, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you here for more training, $n?', '', 56034, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Welcome, $n.', '', 56033, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s plunges the bottom end of his staff into the pool before resting his head on the top.', '', 56032, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve only done this once before... Hopefully this works.', '', 56031, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Strike the stack of stone when the meter is full!', '', 56030, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Strike the stack of wood when the meter is full!', '', 56029, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do not let the stone intimidate you. It is stone, you are $r.', '', 56028, 0, 0, 0, 65, 0, 29116, 0, 0, 0, 0, 0, 0, 0, 39653),
('Mind over matter, $n.', '', 56027, 0, 0, 0, 65, 0, 29115, 0, 0, 0, 0, 0, 0, 0, 39653),
('Try again.', '', 56026, 0, 0, 0, 65, 0, 29114, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your fists are strong, but your mind is still weak.', '', 56025, 0, 0, 0, 65, 0, 29113, 0, 0, 0, 0, 0, 0, 0, 39653),
('Clear your mind, $n.', '', 56024, 0, 0, 0, 65, 0, 29112, 0, 0, 0, 0, 0, 0, 0, 39653),
('Patience is the key.', '', 56023, 0, 0, 0, 65, 0, 29111, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wait until the moment is right... THEN you strike!', '', 56022, 0, 0, 0, 65, 0, 29110, 0, 0, 0, 0, 0, 0, 0, 39653),
('We must not waste time, traveler.', '', 56021, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('No, you must focus!', '', 56020, 0, 0, 0, 65, 0, 29109, 0, 0, 0, 0, 0, 0, 0, 39653),
('Well done.', '', 56019, 0, 0, 0, 65, 0, 29122, 0, 0, 0, 0, 0, 0, 0, 39653),
('I could not have done better myself.', '', 56018, 0, 0, 0, 65, 0, 29121, 0, 0, 0, 0, 0, 0, 0, 39653),
('You learn quickly.', '', 56017, 0, 0, 0, 65, 0, 29120, 0, 0, 0, 0, 0, 0, 0, 39653),
('Excellent focus, $n.', '', 56016, 0, 0, 0, 65, 0, 29119, 0, 0, 0, 0, 0, 0, 0, 39653),
('An excellent strike.', '', 56015, 0, 0, 0, 65, 0, 29118, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, just like that!', '', 56014, 0, 0, 0, 65, 0, 29117, 0, 0, 0, 0, 0, 0, 0, 39653),
('You would be wrong. With clarity and focus, nothing is impossible.', '', 56013, 0, 0, 5, 65, 0, 29106, 0, 0, 0, 0, 0, 0, 0, 39653),
('\"But that\'s impossible!\", you might say.', '', 56012, 0, 0, 6, 65, 0, 29105, 0, 0, 0, 0, 0, 0, 0, 39653),
('This test is simple. All you need to do is strike the stone, until it breaks.', '', 56011, 0, 0, 1, 65, 0, 29104, 0, 0, 0, 0, 0, 0, 0, 39653),
('But it is not too hard. You are ready for this, $n.', '', 56010, 0, 0, 397, 65, 0, 29103, 0, 0, 0, 0, 0, 0, 0, 39653),
('\"But it\'s too hard!\", you might say.', '', 56009, 0, 0, 6, 65, 0, 29102, 0, 0, 0, 0, 0, 0, 0, 39653),
('This test is simple. All you need to do is strike the wood, until it breaks.', '', 56008, 0, 0, 1, 65, 0, 29101, 0, 0, 0, 0, 0, 0, 0, 39653),
('Strike the stack of bamboo when the meter is full!', '', 56007, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('..then, STRIKE!', '', 56006, 0, 0, 511, 65, 0, 29100, 0, 0, 0, 0, 0, 0, 0, 39653),
('That is part of the test. Yes... to succeed, you must focus all your energy into one fist...', '', 56005, 0, 0, 1, 65, 0, 29099, 0, 0, 0, 0, 0, 0, 0, 39653),
('\"But it\'s too thick around!\", you might say.', '', 56004, 0, 0, 6, 65, 0, 29098, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ahhh... this test is simple. All you need to do is strike the bamboo, until it breaks.', '', 56003, 0, 0, 1, 65, 0, 29097, 0, 0, 0, 0, 0, 0, 0, 39653),
('A dark force from within the Dragon Soul reacts violently to the cleansing!', 'A dark force from within the Dragon Soul reacts violently to the cleansing!', 56001, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We have a situation on our hands. Help defend our allies!', '', 56000, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Snowpuff and I\'ll be waitin\'! Please hurry!', '', 55999, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh, and $r! Come back with the goods, okay? I\'ve got to make sure they\'re up to snuff.', 55998, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '$n, you did well. I\'m going back to camp to take care of the wounded. Check in with the Commander when you\'re done out here.', 55995, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Maybe I\'ll see you up there, $n!', 55994, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Watch Commander, I will be leaving now. I\'m finally going to go continue my training!', 55993, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Did you hear that!? The Hidden Master, to the north of here!?', 55992, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bronze Dragonshrine', 'Bronze Dragonshrine', 55991, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Obsidian Dragonshrine', 'Obsidian Dragonshrine', 55990, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Azure Dragonshrine', 'Azure Dragonshrine', 55989, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Emerald Dragonshrine', 'Emerald Dragonshrine', 55988, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ruby Dragonshrine', 'Ruby Dragonshrine', 55987, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Entryway of Time', 'Entryway of Time', 55986, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Select your destination.', 'Select your destination.', 55985, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Eyes of Peroth\'arn are looking for you.', '', 55984, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s vanishes into the shadows!', '', 55983, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You crawl unwitting, like a blind, writhing worm, towards endless madness and despair. I have witnessed the true End Time. This? This is a blessing you simply cannot comprehend.', '', 55982, 0, 0, 0, 65, 0, 25935, 0, 0, 0, 0, 0, 0, 0, 39653),
('The \"End Time,\" I once called this place. I had not seen, by then; I did not know. You hope to... what? Stop me, here? Change the fate I worked so tirelessly to weave?', '', 55981, 0, 0, 0, 65, 0, 25934, 0, 0, 0, 0, 0, 0, 0, 39653),
('All that matters... is this moment.', '', 55980, 0, 0, 0, 65, 0, 25947, 0, 0, 0, 0, 0, 0, 0, 39653),
('What matters is that Azeroth did not fall; that we survived to fight another day.', '', 55979, 0, 0, 0, 65, 0, 25946, 0, 0, 0, 0, 0, 0, 0, 39653),
('Still, in time, I will... fall to madness. And you, heroes... will vanquish me. The cycle will repeat. So it goes.', '', 55978, 0, 0, 0, 65, 0, 25945, 0, 0, 0, 0, 0, 0, 0, 39653),
('At last it has come to pass. The moment of my demise. The loop is closed. My future self will cause no more harm.', '', 55977, 0, 0, 0, 65, 0, 25944, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'WHAT? FOLLOW YOU? OKAY!', 55976, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('AWAY!', '', 55975, 0, 0, 0, 65, 0, 26111, 0, 0, 0, 0, 0, 0, 0, 39653),
('I WILL NOT BE DENIED!', '', 55974, 0, 0, 0, 65, 0, 26109, 0, 0, 0, 0, 0, 0, 0, 39653),
('Nooooo...away...', '', 55973, 0, 0, 0, 65, 0, 26110, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The power of the Soul is tearing him apart!', 55972, 0, 0, 0, 65, 0, 0, 26510, 0, 0, 0, 0, 0, 0, 39653),
('', 'He is lost to us, sister. He is Neltharion no longer.', 55971, 0, 0, 0, 65, 0, 0, 26151, 0, 0, 0, 0, 0, 0, 39653),
('IT IS MINE!!', '', 55970, 0, 0, 0, 65, 0, 26108, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Neltharion! What have you done? You have doomed us all to the madness of the Old Gods!', 55969, 0, 0, 0, 65, 0, 0, 26509, 0, 0, 0, 0, 0, 0, 39653),
('How DARE you touch my creation?! It is mine...mine...MINE!', '', 55968, 0, 0, 0, 65, 0, 26107, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It is too powerful!', 55967, 0, 0, 0, 65, 0, 0, 26150, 0, 0, 0, 0, 0, 0, 39653),
('', 'Come sister, it is time to end this. We will cleanse the Dragon Soul of the Old Gods\' dark influence!', 55966, 0, 0, 0, 65, 0, 0, 26508, 0, 0, 0, 0, 0, 0, 39653),
('This seems like a good spot to consult the water!', '', 55965, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ll stick with you a little longer, $n. I saw many injured crewmen who may be in need of my aid.', 55964, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oof! I reckon we fared better\'n Amber and Nimm. Saw their plane burn up further inland. Thanks, $c.', '', 55963, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Woohoo, that was some crash! All my parts seem accounted for. Thanks, rookie.', '', 55962, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Keep your eyes open and your head in the mission, recruit.', '', 55961, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('They\'ll take this camp over my dead body!', '', 55960, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<The dwarf is unconscious, but otherwise unharmed.>', '', 55959, 0, 0, 66, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What\'s yer mission? I got the tools that you need.', '', 55958, 0, 0, 66, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<The gnome\'s face is streaked with smoke and burns, but he\'s alive.>', '', 55957, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wake him up.', 'Wake him up.', 55956, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Loudly explain how to get back to camp.', 'Loudly explain how to get back to camp.', 55955, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'HEY ROOKIE! DID YOU SAY SOMETHING TO ME? SORRY, MY EARS ARE STILL RINGING FROM THE EXPLOSION!', 55954, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Is there anyone in need of medical aid?', 55953, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve reconsidered... it\'s too dangerous to stay here. No piece of land is worth losing your life over. Let me see those evacuation orders.', '', 55952, 0, 13296, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, they\'re right here. Let\'s go.', 'Yes, they\'re right here. Let\'s go.', 55951, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do you have those evacuation papers?', '', 55950, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I apologize for the mess. Things are a little hectic right now.$b$bHow can I be of service to you?', 55949, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Welcome to Stoneplow. What can we do for you?', 55948, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Those had better not be evacuation papers I see.', 55947, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have my wife, two strong daughters, and two strong sons. Thank you, but we can protect this farm ourselves.', '', 55946, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will not do it. My grandfather knew what he was getting into when he first planted seed in the shadow of the Serpent\'s Spine.', '', 55945, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('All we have is our land. And that commander wants us to give it up to the mantid?', '', 55944, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am a farmer, $c. It\'s all I know.', '', 55943, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s sighs.', '', 55942, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Loon Mai has issued evacuation orders.', 'Loon Mai has issued evacuation orders.', 55941, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('How can I help you, $c?', '', 55940, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you?', '', 55939, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I don\'t know, dear.', '', 55938, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Daddy, is this nice person going to kill all the bad mantid soldiers?', 55937, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh, honey...', 55936, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ying, Huizhong... gather your things. We\'re leaving the farm until it\'s safe.', '', 55935, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I see. I\'d hoped that we could wait out this invasion, but if the authorities want us to leave, we will leave.', '', 55934, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Loon Mai has issued evacuation orders.', 'Loon Mai has issued evacuation orders.', 55933, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Stay back!$b$bWait... you\'re not one of them. We\'re not accustomed to outsiders, and with the mantid breaking through the wall, I...$b$bAnyhow, what can we do to help you?', '', 55932, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('That\'s right. Now please, $r, leave and let us defend our property.', '', 55931, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We\'re proud. We\'re strong. We are descended from the blood of the Tiller himself... and we don\'t run from trouble.', 55930, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Pshh... outsiders. You know nothing about the Stoneplow way.', 55929, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, Commander Mai sent me, and I carry his evacuation orders.', 'Yes, Commander Mai sent me, and I carry his evacuation orders.', 55928, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What, another one? Did Commander Mai send you?$b$bHow many times do I have to tell that bonehead - we\'re not evacuating!', '', 55927, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I feared that this day would come. I will pack up my things.', '', 55926, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Look out! Mantid!', '', 55925, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oh, I don\'t know. I am old, and I have always...', '', 55924, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Loon Mai has issued evacuation orders.', 'Loon Mai has issued evacuation orders.', 55923, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Such insolence. My temper grows short.', 55922, 0, 0, 5, 64, 0, 0, 26015, 0, 0, 0, 0, 0, 0, 39653),
('Yes?', '', 55921, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Serve Azshara, puppets, and rejoice.', 55920, 0, 0, 273, 64, 0, 0, 26026, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ah, welcome. You are here to join us in the coming celebration? No? A pity.', 55919, 0, 0, 274, 64, 0, 0, 26013, 0, 0, 0, 0, 0, 0, 39653),
('', 'The link to the portal must be broken! Quickly, to Stormrage!', 55918, 0, 0, 0, 65, 0, 0, 26036, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Old Gods protect the Soul!', 55917, 0, 0, 0, 65, 0, 0, 26035, 0, 0, 0, 0, 0, 0, 39653),
('', 'The aspects!', 55916, 0, 0, 0, 65, 0, 0, 26033, 0, 0, 0, 0, 0, 0, 39653),
('', 'Sister, look! The artifact is surrounded by an aura of darkness!', 55915, 0, 0, 0, 65, 0, 0, 26031, 0, 0, 0, 0, 0, 0, 39653),
('', 'Heroes! We have been sent by Nozdormu! Quickly, on our backs, we must get you to the Dragon Soul!', 55914, 0, 0, 0, 65, 0, 0, 26032, 0, 0, 0, 0, 0, 0, 39653),
('', 'It is them!', 55913, 0, 0, 0, 65, 0, 0, 26030, 0, 0, 0, 0, 0, 0, 39653),
('At your side, my queen!', '', 55912, 0, 0, 0, 65, 0, 26136, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My noble Varo\'then, do return and dispose of this murderous band.', 55910, 0, 0, 25, 64, 0, 0, 26019, 0, 0, 0, 0, 0, 0, 39653),
('Be free of doubt, priestess...', 'Be free of doubt, priestess...', 55909, 0, 0, 0, 65, 0, 28559, 28559, 0, 0, 0, 0, 0, 0, 39653),
('', 'The haze has been lifted from my eyes... forgive me for doubting you...', 55908, 0, 0, 0, 65, 0, 0, 27604, 0, 0, 0, 0, 0, 0, 39653),
('', 'Leave this place.', 55907, 0, 0, 0, 65, 0, 0, 27609, 0, 0, 0, 0, 0, 0, 39653),
('', 'The heart is MINE!', 55906, 0, 0, 0, 65, 0, 0, 27608, 0, 0, 0, 0, 0, 0, 39653),
('', 'The cycle must continue, the Jade Serpent must be reborn!', 55905, 0, 0, 0, 65, 0, 0, 27606, 0, 0, 0, 0, 0, 0, 39653),
('', 'The heart of the Great Serpent will not fall into your hands!', 55904, 0, 0, 0, 65, 0, 0, 27603, 0, 0, 0, 0, 0, 0, 39653),
('Who crashing Ook party!?', '', 55903, 0, 0, 0, 65, 0, 28798, 0, 0, 0, 0, 0, 0, 0, 39653),
('BOOM shakalaka!', '', 55902, 0, 0, 0, 65, 0, 29342, 0, 0, 0, 0, 0, 0, 0, 39653),
('BOOM! Explosion! Overpowering!', '', 55901, 0, 0, 0, 65, 0, 29348, 0, 0, 0, 0, 0, 0, 0, 39653),
('Things that make you go... BOOM!', '', 55900, 0, 0, 0, 65, 0, 29347, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re the bomb!', '', 55899, 0, 0, 0, 65, 0, 29345, 0, 0, 0, 0, 0, 0, 0, 39653),
('I need to follow this map to Dawn\'s Blossom.', 'I need to follow this map to Dawn\'s Blossom.', 55898, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This will be the bomb.', '', 55897, 0, 0, 0, 65, 0, 29346, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gate?! I\'m going to bring this whole wall down!', '', 55896, 0, 0, 0, 65, 0, 29341, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ookin\' flapper dropped a dooker!', '', 55895, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is a flawlessly etched jade statue of An Windfur\'s friend Shin, eyes wide with terror.', '', 55894, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('More please?', '', 55893, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('My boom boom is too small! Can I have another?', '', 55892, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Should have had more fiber in your diet then.', 55891, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 1, 0, 39653),
('', 'Obviously you have mistaken me for someone who cares.', 55890, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 1, 0, 39653),
('', 'Be glad I only gave you a bomb. Ingrate.', 55889, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 1, 0, 39653),
('Boom boom too small! Wikket being sticky with the boom booms.', '', 55888, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'I never would have thought that these grunts could be trained.', 55887, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The kodos are waiting on the road. Safe journey, $Gbrother:sister;.', 55882, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 50, 0, 0, 39653),
('What you want?', '', 55881, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve lost my balloon.', 'I\'ve lost my balloon.', 55880, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve lost my panther cub.', 'I\'ve lost my panther cub.', 55879, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve lost my lashtail hatchling.', 'I\'ve lost my lashtail hatchling.', 55875, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have done NOTHING. I will tear your world APART.', '', 55860, 0, 0, 0, 64, 0, 26527, 0, 0, 0, 0, 0, 0, 0, 39653),
('At this rate I would die faster of natural causes.', '', 55859, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Does it hurt being as dumb as you are?', '', 55858, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You through like a land walker!', '', 55857, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You ookin nugs missed the wikket! AGAIN!', '', 55856, 0, 0, 0, 65, 0, 0, 0, 22, 480, 0, 0, 1, 0, 39653),
('FLING!', '', 55855, 0, 0, 0, 65, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('Aim!', '', 55854, 0, 0, 0, 65, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s begins to cast |cFFFF0000|Hspell:107018|h[Assault Aspects]|h|r!', '', 55853, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ready!', '', 55852, 0, 0, 0, 65, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s assaults |cFF5858FA|Hspell:107018|h[Kalecgos]|h|r!', '', 55851, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s assaults |cFF04FC32|Hspell:107018|h[Ysera]|h|r!', '', 55850, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s assaults |cFFFFFF00|Hspell:107018|h[Nozdormu]|h|r!', '', 55849, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\ability_deathwing_assualtaspects.blp:20|t%s assaults |cFFFF0000|Hspell:107018|h[Alexstrasza]|h|r!', '', 55848, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My thanks, $p, for saving me from that vile jade witch.$b$bEven now my legs still feel stiff. I can command soldiers, if we can call these creatures that. But I think I will be of little use in any battle.', '', 55847, 0, 0, 0, 65, 0, 0, 0, 66, 0, 0, 0, 0, 0, 39653),
('Don\'t give up! We are counting on you to push Deathwing back.', '', 55846, 0, 0, 0, 64, 0, 25897, 0, 0, 0, 0, 0, 0, 0, 39653),
('These champions are our only hope for exposing Deathwing\'s weakness. Together, we can prevail.', '', 55845, 0, 0, 0, 64, 0, 25896, 0, 0, 0, 0, 0, 0, 0, 39653),
('Only you can give us our opening!', '', 55844, 0, 0, 0, 64, 0, 25902, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will bring you closer to the Emerald Dream. Seek safety there when the fight becomes too intense.', '', 55843, 0, 0, 0, 64, 0, 26142, 0, 0, 0, 0, 0, 0, 0, 39653),
('Alright, let\'s get a move on!', '', 55840, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Welcome to the Temple of the Jade Serpent, traveler.$B$BWe welcome all within our doors, and offer knowledge freely to any who seek it.', '', 55839, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('SIT!', '', 55838, 0, 0, 0, 65, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('This staff holds powers passed down through my ancestors. Thank you for returning it to me.', '', 55837, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Elder, I found your staff.', 'Elder, I found your staff.', 55836, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thanks to you, my work can now continue.', '', 55835, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I must speak to the waters to understand their turmoil.', '', 55834, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The waters are wild and chaotic. Something agitates them.', '', 55833, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am bested.  Give me a moment and we will venture forth together to face the Sha.', '', 55832, 0, 0, 0, 65, 0, 27623, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hey, stranger! Pssst! Come over here!', 55831, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('When I was but a cub I could scarcely throw a punch, but after years of training I can do so much more!', '', 55830, 0, 0, 0, 65, 0, 27630, 0, 0, 0, 0, 0, 0, 0, 39653),
('Skill with a weapon is but a physical manifestation of one\'s martial strength. Let me show you what spiritual power is!', '', 55829, 0, 0, 0, 65, 0, 27629, 0, 0, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('Very well then, outsiders. Let us see your true strength.', '', 55828, 0, 0, 0, 65, 0, 27628, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hey there!$B$B<The little girl squints at you.>$B$BI overheard you talking to the Elder Sage. He\'s pretty serious, isn\'t he?$B$BWell you\'re in luck, because I hear just about everything that happens around here.', 55827, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('|TInterface\\Icons\\spell_fire_meteorstorm.blp:20|t%s begins to cast |cFFFF0000|Hspell:105651|h[Elementium Bolt]|h|r!', '', 55826, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve done all that you\'ve asked of me. I\'m ready for the trial of stone.', 'I\'ve done all that you\'ve asked of me. I\'m ready for the trial of stone.', 55823, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My fists are ready. Bring on the trial of wood.', 'My fists are ready. Bring on the trial of wood.', 55822, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m ready for the trial of bamboo.', 'I\'m ready for the trial of bamboo.', 55821, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You wish to train? YOU!?', '', 55820, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My wrath knows no bounds!', '', 55819, 0, 0, 0, 65, 0, 25916, 0, 0, 0, 0, 0, 0, 0, 39653),
('There will be no escape!', '', 55818, 0, 0, 0, 65, 0, 25915, 0, 0, 0, 0, 0, 0, 0, 39653),
('Suffer for your arrogance!', '', 55817, 0, 0, 0, 65, 0, 25914, 0, 0, 0, 0, 0, 0, 0, 39653),
('A just punishment!', '', 55816, 0, 0, 0, 65, 0, 25913, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is the price you pay!', '', 55815, 0, 0, 0, 65, 0, 25912, 0, 0, 0, 0, 0, 0, 0, 39653),
('Where... is this place? What... have I done? Forgive me, my father...', '', 55814, 0, 0, 0, 65, 0, 25910, 0, 0, 0, 0, 0, 0, 0, 39653),
('What dark horrors have you wrought in this place? By my ancestors\' honor, I shall take you to task!', '', 55813, 0, 0, 0, 65, 0, 25909, 0, 0, 0, 0, 0, 0, 0, 39653),
('You! Are you the ones responsible for what has happened here...?', '', 55812, 0, 0, 0, 65, 0, 25911, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hello there, $c!$B$BWe cultivate and harvest the finest lotus flowers in all of Pandaria. From here they are sent down to the village of New Cifera where they are sorted and shipped all over the land.$B$BThe lotus has countless culinary, medicinal, and decorative applications - as you can imagine, demand is quite high.', 55811, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I make kegs. Sounds simple to the un-enlightened but you would be surprised how much the type of materials used in a keg will affect the flavor of the beverage held within.', '', 55810, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('\"Something profound.\"$b$BThere. Now whenever someone asks you what Lee Mugfinder said to you at your first meeting, it will always be something profound.', '', 55809, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Tapping is an art form passed down through the generations. No need to ask anyone else if that is true or not. Just take my word for it.', 55808, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('And then what happened?', 'And then what happened?', 55805, 0, 13262, 0, 65, 0, 0, 0, 430, 0, 0, 0, 0, 0, 39653),
('Oooooooo!', 'Aaaaaahhhh!', 55804, 0, 13262, 0, 65, 0, 0, 0, 430, 0, 0, 0, 0, 0, 39653),
('With weapons of power and a magnificent regalia our hero unleashed their fury on the beasts. It was glorious!', '', 55802, 0, 13262, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('HUNDREDS OF DECAPITATIONS!', '', 55801, 0, 13262, 0, 65, 0, 0, 0, 22, 0, 0, 0, 0, 0, 39653),
('They stabbed and bit and chomped but nothing they could do would defeat our hero, $p!', '', 55800, 0, 13262, 0, 65, 0, 0, 0, 396, 23, 0, 0, 0, 0, 39653),
('But then, the dark evil spiders rose from their evil layers with eyes full of evil and legs full of evil.', '', 55799, 0, 13262, 0, 65, 0, 0, 0, 396, 0, 0, 0, 0, 0, 39653),
('There they were, marching through the depths of the Silkwood on an errand of peace.', '', 55798, 0, 13262, 0, 65, 0, 0, 0, 396, 0, 0, 0, 0, 0, 39653),
('Gather \'round cubs and hear the tale of \"$p and the dreaded Silken Shadows\"...', '', 55797, 0, 13262, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re the boss.', 'You\'re the boss.', 55796, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sorry, Yue, but that\'s all the full blossoms I could find. Most of the flowers in this pool just aren\'t ready yet.', 'Sorry, Yue, but that\'s all the full blossoms I could find. Most of the flowers in this pool just aren\'t ready yet.', 55795, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s hums a tune while unloading his basket.', '%s hums a tune while unloading her basket.', 55794, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Jade Serpent is nearly complete. You know what that means? Several months of cheering, celebrating, sleeping, and brewing! I can\'t wait!', 'The Jade Serpent is nearly complete. You know what that means? Several months of cheering, celebrating, sleeping, and brewing! I can\'t wait!', 55793, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I need to make sure to get in my sixth and seventh nap today if I expect to be ready for my big snooze.', 'I need to make sure to get in my sixth and seventh nap today if I expect to be ready for my big snooze.', 55792, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('And what are you? I\'ve seen many things in my day but you are certainly a first. Has the turtle returned? I always thought that was a myth.', 'And what are you? I\'ve seen many things in my day but you are certainly a first. Has the turtle returned? I always thought that was a myth.', 55791, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I hear the hozen and jinyu have been increasing their skirmishes. Those poor little creatures will destroy each other if they aren\'t careful. It is quite a vicious cycle they are trapped in.', 'I hear the hozen and jinyu have been increasing their skirmishes. Those poor little creatures will destroy each other if they aren\'t careful. It is quite a vicious cycle they are trapped in.', 55790, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('New to town? You should try Chin\'s noodles. They are the stuff of local legend.', 'New to town? You should try Chin\'s noodles. They are the stuff of local legend.', 55789, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are you an adventurer? We don\'t hear about many adventures around here except the stories Tzu tells us.', 'Are you an adventurer? We don\'t hear about many adventures around here except the stories Tzu tells us.', 55788, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your accent is strange. Are you from the Valley of the Four Winds?', 'Your accent is strange. Are you from the Valley of the Four Winds?', 55787, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will slow the Destroyer\'s attacks when I can.', '', 55786, 0, 0, 0, 64, 0, 25949, 0, 0, 0, 0, 0, 0, 0, 39653),
('I AM DEATHWING, THE DESTROYER, THE END OF ALL THINGS, INEVITABLE, INDOMITABLE; I AM THE CATACLYSM!', '', 55785, 0, 0, 0, 64, 0, 26353, 0, 0, 0, 0, 0, 0, 0, 39653),
('Watch as your world comes to an end.', '', 55784, 0, 0, 0, 64, 0, 26359, 0, 0, 0, 0, 0, 0, 0, 39653),
('I shall show you a true cataclysm.', '', 55783, 0, 0, 0, 64, 0, 26358, 0, 0, 0, 0, 0, 0, 0, 39653),
('I shall tear this world apart.', '', 55782, 0, 0, 0, 64, 0, 26357, 0, 0, 0, 0, 0, 0, 0, 39653),
('The sea will swallow your smoldering remains.', '', 55781, 0, 0, 0, 64, 0, 26356, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your armor means nothing, your faith even less.', '', 55780, 0, 0, 0, 64, 0, 26355, 0, 0, 0, 0, 0, 0, 0, 39653),
('There is no shelter from my fury.', '', 55779, 0, 0, 0, 64, 0, 26354, 0, 0, 0, 0, 0, 0, 0, 39653),
('I will cleanse whatever corruption I can; my fire will not harm you.', 'I will cleanse whatever corruption I can; my fire will not harm you.', 55778, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Destroyer is gathering all his might for a blow that will split the world. Attack him, now! We must stop the final Cataclysm!', '', 55776, 0, 0, 0, 65, 0, 26261, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hurry, heroes. In mere moments Deathwing\'s Cataclysm will complete what he begun and end the world. Join me in the attack, now!', '', 55774, 0, 0, 0, 65, 0, 25951, 0, 0, 0, 0, 0, 0, 0, 39653),
('No! Such power! Deathwing\'s summoning of the final Cataclysm will destroy all life on Azeroth. Quickly, we must interrupt him!', 'No! Such power! Deathwing\'s summoning of the final Cataclysm will destroy all life on Azeroth. Quickly, we must interrupt him!', 55773, 0, 0, 0, 65, 0, 26500, 26500, 0, 0, 0, 0, 0, 0, 39653),
('Inconceivable! He couldn\'t possibly be alive!', 'Inconceivable! He couldn\'t possibly be alive!', 55772, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do you hear that?  What is that noise!', '', 55771, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('...although, you may want to hurry.', '', 55770, 0, 0, 0, 65, 0, 25952, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have accomplished the impossible, succeeded where all Azeroth feared you would fail.', 'You have accomplished the impossible, succeeded where all Azeroth feared you would fail.', 55769, 0, 0, 0, 65, 0, 26501, 26501, 0, 0, 0, 0, 0, 0, 39653),
('It is done; at last the Destroyer has met his end. Now, we can begin to heal our world.', '', 55768, 0, 0, 0, 64, 0, 25901, 0, 0, 0, 0, 0, 0, 0, 39653),
('We defeated the Destroyer!', 'We defeated the Destroyer!', 55767, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have done it!', '', 55766, 0, 0, 0, 64, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Meet me up in the pools whenever you\'re ready!', '', 55765, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Go ahead and speak with the water, Ashyo.', 'Go ahead and speak with the water, Ashyo.', 55764, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sometimes the only way to find something is to stop looking.', '', 55763, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', '|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t%s begins to cast |cFFFF0000|Hspell:106886|h[Cauterize]|h|r!', 55762, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We\'ve gotta stop giving the recruits those red shirts. They\'re just moving targets in them.', '', 55761, 0, 0, 0, 65, 0, 29073, 0, 1, 0, 0, 0, 0, 0, 39653),
('Why didn\'t he listen?', '', 55760, 0, 0, 0, 65, 0, 29070, 0, 5, 0, 0, 0, 0, 0, 39653),
('You\'ll get yourself killed!', '', 55759, 0, 0, 0, 65, 0, 29072, 0, 0, 0, 0, 0, 0, 0, 39653),
('What are you doing?! There\'s no way you\'ll reach it!', '', 55758, 0, 0, 0, 65, 0, 29069, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t worry! I can make it!', '', 55757, 0, 0, 0, 65, 0, 27692, 0, 0, 0, 0, 0, 0, 0, 39653),
('But the mantid have overrun the area. There\'s no clear path!', '', 55756, 0, 0, 0, 65, 0, 29071, 0, 1, 0, 0, 0, 0, 0, 39653),
('We\'ve got to light that signal fire. Without reinforcements, they\'ll destroy the gate!', '', 55755, 0, 0, 0, 65, 0, 29068, 0, 5, 0, 0, 0, 0, 0, 39653),
('The Widow Greenpaw is NOT a witch. She just makes very lifelike jade statues.', '', 55754, 0, 13227, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('The Hourglass\' power is exhausted. No more games, mortals. Relent, or perish.', '', 55753, 0, 0, 0, 65, 0, 25933, 0, 0, 0, 0, 0, 0, 0, 39653),
('Again...? Is this your plot, your scheme?', '', 55752, 0, 0, 0, 65, 0, 25932, 0, 0, 0, 0, 0, 0, 0, 39653),
('Another chance will make no difference. You will fail.', '', 55751, 0, 0, 0, 65, 0, 25931, 0, 0, 0, 0, 0, 0, 0, 39653),
