('', 'Go away, marmots!', 55122, 0, 13092, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Shoo!', 55121, 0, 13092, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
