('', 'Can we go yet? Are you done with your beer?', 55070, 0, 13118, 1, 65, 0, 0, 30379, 0, 0, 0, 0, 0, 0, 39653),
('Over here!', '', 55069, 0, 0, 0, 65, 0, 32863, 0, 0, 0, 0, 0, 0, 0, 39653),
