('Return to the shadows!', '', 54831, 0, 0, 0, 65, 0, 26048, 0, 0, 0, 0, 0, 0, 0, 39653),
('Nothing will stop me. Not even you, demon.', '', 54829, 0, 0, 0, 65, 0, 26049, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Now you see me...', 54828, 0, 0, 0, 65, 0, 0, 25826, 0, 0, 0, 0, 0, 0, 39653),
('', 'Surprise.', 54827, 0, 0, 0, 65, 0, 0, 25827, 0, 0, 0, 0, 0, 0, 39653),
('', 'Bye-bye.', 54826, 0, 0, 0, 65, 0, 0, 25825, 0, 0, 0, 0, 0, 0, 39653),
