('', 'Mmm, too much fun!', 54824, 0, 0, 0, 64, 0, 0, 25823, 0, 0, 0, 0, 0, 0, 39653),
('', 'I hope your friends can do better.', 54823, 0, 0, 0, 64, 0, 0, 25822, 0, 0, 0, 0, 0, 0, 39653),
('', 'Tch!  So soon?', 54822, 0, 0, 0, 64, 0, 0, 25821, 0, 0, 0, 0, 0, 0, 39653),
('', 'You\'re much... better... than I thought...', 54821, 0, 0, 0, 65, 0, 0, 25817, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ah. Well. That was even easier than I thought!', 54820, 0, 0, 392, 65, 0, 0, 25820, 333, 392, 0, 0, 1, 0, 39653),
