('Are you ready?', '', 54451, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('COME AT ME, BROKKERS!', '', 54450, 0, 0, 1, 64, 0, 31084, 0, 0, 0, 0, 0, 0, 0, 39653),
