INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('Yarrr!', '', 51107, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am... a tauren... of the SEA!', '', 51106, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Come and get your pain!', '', 51105, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve always wanted my very own dragon!', '', 51104, 0, 0, 1, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('For the Crusade! Hyaaah!', '', 51103, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take that, ye stinkin\' fire-donkey!', '', 51102, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Nobody told me how big these guys were going to be.', '', 51101, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh yeah. Slinky\'s going to cut you.', 51100, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'What\'s that? I can\'t hear you with my KNIFE IN YOUR FACE!', 51099, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Stabby stabby stab stab!', 51098, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You never stood a chance!', '', 51097, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Johnny! Awesome!', '', 51096, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Haha! Yes!', '', 51095, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re about to enter your own personal arena of pain, jerk!', '', 51094, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Behold the might that is Gurgthock!', '', 51093, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oh, don\'t MAKE me summon my troll-servant.', '', 51092, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Maybe after this, they\'ll take away my \"Initiate\" title.', '', 51091, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yeesh! These guys are really hot!', '', 51090, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve got a history with fire elementals, you know. I consider myself somewhat of an expert on the subject.', '', 51089, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Look out Ragnaros! You\'re next!', '', 51088, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Too bad for you... I brought my fists with me!', '', 51087, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take that, dangerous enemy!', '', 51086, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('mmmmmMMMMMMRRRF!', '', 51085, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
