INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('The darkness beneath Tirisfal will consume us all...', '', 50847, 6, 0, 274, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('There is NOTHING random about what I say!  Nothing!', '', 50846, 1, 0, 4, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I was head editor of the Tinker Town Tattler!', '', 50845, 37, 0, 15, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hand me the wizzlesproket, you dwarf-brained son of a human!  No, not that one, the other one!', '', 50844, 7, 0, 25, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The score is fourty-six to fifty-two!', '', 50843, 13, 0, 1, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hi!  You there!  Does it smell green to you?', '', 50842, 13, 0, 6, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tadpoles!  Tadpoles is the winner!', '', 50841, 13, 0, 4, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('While I miss Gilneas greatly, there\'s ancient ruins to explore!', 'While I miss Gilneas greatly, there\'s ancient ruins to explore!', 50840, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Of course, $c. What is the young warrior\'s name?$B$BI wish more of our people shared your concern for the orphans of Orgrimmar.', '', 50839, 0, 0, 1, 65, 0, 0, 0, 432, 0, 0, 0, 0, 0, 39653),
('Warchief, you are a hero to my young ward. Would you mind signing an autograph for him?', 'Warchief, you are a hero to my young ward. Would you mind signing an autograph for him?', 50838, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Maybe I need a new nickname.', '', 50837, 0, 0, 6, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I suppose sometimes y\'need to hit rock bottom before y\'can crawl yer way back up.', '', 50836, 0, 0, 38, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A mop?  Really?', '', 50835, 0, 0, 38, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I can\'t believe it\'s come to this.', '', 50834, 0, 0, 38, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is humiliating.', '', 50833, 0, 0, 18, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Having some trouble there, sailor?  Need some help?', '', 50832, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Will you pay \"Pretty Boy\" Duncan 1 gold to swab the decks for you?', 'Will you pay \"Pretty Boy\" Duncan 1 gold to swab the decks for you?', 50831, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
