('Disarming', 'Disarming', 46935, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take the weapons!', '', 46934, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('C\'mon then lads, set up a perimeter. We hold \'em here or Thundermar is next!', '', 46933, 7, 0, 5, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('So... difficult!', '', 46932, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
