('', 'Away, creature of the depths!', 41846, 0, 11800, 5, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You\'ll not be eating me today!', 41845, 0, 11800, 25, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Smell blood, do you?', 41844, 0, 11800, 6, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I don\'t want to hurt you, but I will!', 41843, 0, 11800, 5, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Shoo!', 41842, 0, 11800, 5, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
