('Kill them all!', 'Kill them all!', 40183, 0, 11411, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Crush!', 'Crush!', 40182, 0, 11411, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Kill!!!', 'Kill!!!', 40181, 0, 11411, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
