('Death!', 'Death!', 40179, 0, 11411, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Blood!', 'Blood!', 40178, 0, 11411, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yea... I don\'t know about this.', 'Yea... I don\'t know about this.', 40177, 0, 11411, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('*yawn*', '*yawn*', 40176, 0, 11411, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Meh.', 'Meh.', 40175, 0, 11411, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m not quite convinced.', 'I\'m not quite convinced.', 40174, 0, 11411, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Icecrown', 'Icecrown', 40173, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Wrathgate', 'Wrathgate', 40172, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
