('Portal Stone', 'Portal Stone', 40170, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Paint Bomb', 'Paint Bomb', 40169, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Blazing Hippogryph', 'Blazing Hippogryph', 40168, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
