('Champions! I cannot hold her back any longer.', '', 37165, 0, 0, 0, 65, 0, 16827, 0, 0, 0, 0, 0, 0, 0, 39653),
('Augh! I must rest for a moment. \n', '', 37164, 0, 0, 0, 65, 0, 16826, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'They died so easily. No matter.', 37163, 0, 0, 0, 65, 0, 0, 17022, 0, 0, 0, 0, 0, 0, 39653),
('Forward!', '', 37162, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
