('', 'Enough! I tire of these games!', 37140, 0, 0, 0, 65, 0, 0, 17011, 0, 0, 0, 0, 0, 0, 39653),
('', 'Free... at last....', 37139, 0, 0, 0, 65, 0, 0, 17010, 0, 0, 0, 0, 0, 0, 39653),
('', 'Suffer, mortals, as your pathetic magic betrays you!', 37138, 0, 0, 0, 65, 0, 0, 17014, 0, 0, 0, 0, 0, 0, 39653),
('', 'Can you feel the cold hand of death upon your heart?', 37137, 0, 0, 0, 65, 0, 0, 17013, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your incursion ends here! None shall survive!', 37136, 0, 0, 0, 65, 0, 0, 17012, 0, 0, 0, 0, 0, 0, 39653),
('', 'Perhaps... you were right, Crok. ', 37135, 0, 0, 0, 65, 0, 0, 17023, 0, 0, 0, 0, 0, 0, 39653),
