('Are you up to the challenge? I will not hold back.', '', 35347, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<The Hippogryph looks anxious and ready to go!>', '', 35346, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Mount the Hippogryph and prepare for battle!', 'Mount the Hippogryph and prepare for battle!', 35345, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I knew I should have paid my earthquake insurance!', 'I knew I should have paid my earthquake insurance!', 35344, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Did you feel that?', 'Did you feel that?', 35343, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Whatever, I\'ve felt worse.', 'Whatever, I\'ve felt worse.', 35342, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Run for your lives!', 'Run for your lives!', 35341, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
