('You\'ll never make it to Stonetalon!', '', 34910, 0, 8548, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We have not lost hope...', '', 34909, 0, 8548, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Death to the Horde!', '', 34908, 0, 8548, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bomb Condition: Fully Repaired', 'Bomb Condition: Fully Repaired', 34907, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your days are numbered, shapeshifter!', 'Your days are numbered, shapeshifter!', 34906, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our wolves will feast on your bones!', 'Our wolves will feast on your bones!', 34905, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Lok\'tar!', 'Lok\'tar!', 34904, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
