('<Snort!>', '', 34737, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You waste your strength! Tortusk train us warriors never to talk.', '', 34736, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ow-oooh! I not talk for nothing!', '', 34735, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
