('', '%s bites back a laugh.', 29548, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh. Oh... I see. How nice!', 29547, 7, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
