('', 'And $gbrother:sister;, be wary of scourge ambushes.', 29480, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Spread the word that another artifact  will soon be brought to our defenders.', 29479, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
