INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('At last some good luck. Market Row has not caught fire yet. Mal\'Ganis is supposed to be in Crusaders\' Square, which is just ahead. Tell me when you\'re ready to move forward.', '', 28048, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('That\'s enough; we must move again. Mal\'Ganis awaits.', '', 28047, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Zim\'Torga is able to provide us with a certain level of protection, but she has been greatly weakened by the presence of the Scourge and the actions of the Drakkari.$B$BIt falls to me and Ahunae to see to the rest of our defenses.', 28046, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Rest a moment and clear your lungs, but we must move again soon.', '', 28045, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('For Lordaeron!', 'For Lordaeron!', 28044, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
