INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('I have lost my Zandalar Illusionist\'s Robe and need a new one, Al\'tabim.', 'I have lost my Zandalar Illusionist\'s Robe and need a new one, Al\'tabim.', 12677, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Al\'tabim, my Zandalar Confessor\'s Wraps have gone missing. Can you replace them?', 'Al\'tabim, my Zandalar Confessor\'s Wraps have gone missing. Can you replace them?', 12676, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I no longer possess my Zandalar Confessor\'s Bindings. Can you provide a replacement?', 'I no longer possess my Zandalar Confessor\'s Bindings. Can you provide a replacement?', 12675, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have lost my Confessor\'s Mantle and require a replacement, Al\'tabim.', 'I have lost my Confessor\'s Mantle and require a replacement, Al\'tabim.', 12674, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I require assistance in recovering a piece of my Demoniac\'s Threads, Al\'tabim.', 'I require assistance in recovering a piece of my Demoniac\'s Threads, Al\'tabim.', 12673, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I require assistance in recovering a piece of my Illusionist\'s Attire, Al\'tabim.', 'I require assistance in recovering a piece of my Illusionist\'s Attire, Al\'tabim.', 12672, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If you have lost a piece of your Zandalarian armor, I may be able to help you.', '', 12671, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I need assistance in recovering a piece of my Confessor\'s Raiment, Al\'tabim.', 'I need assistance in recovering a piece of my Confessor\'s Raiment, Al\'tabim.', 12670, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve misplaced my Zandalar Haruspex\'s Bracers and require another pair.', 'I\'ve misplaced my Zandalar Haruspex\'s Bracers and require another pair.', 12669, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Maywiki, I no longer have my Zandalar Haruspex\'s Belt. Can you help?', 'Maywiki, I no longer have my Zandalar Haruspex\'s Belt. Can you help?', 12668, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have lost my Zandalar Haruspex\'s Tunic, Maywiki. Do you have a replacement?', 'I have lost my Zandalar Haruspex\'s Tunic, Maywiki. Do you have a replacement?', 12667, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have misplaced my Zandalar Augur\'s Bracers and require another pair.', 'I have misplaced my Zandalar Augur\'s Bracers and require another pair.', 12666, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Maywiki, a dastardly little gnome made off with my Zandalar Augur\'s Belt. Can you provide a replacement?', 'Maywiki, a dastardly little gnome made off with my Zandalar Augur\'s Belt. Can you provide a replacement?', 12665, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Maywiki, I\'ve lost my Zandalar Augur\'s Hauberk and need a new one.', 'Maywiki, I\'ve lost my Zandalar Augur\'s Hauberk and need a new one.', 12664, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am missing a piece of my Augur\'s Regalia and I need a replacement.', 'I am missing a piece of my Augur\'s Regalia and I need a replacement.', 12663, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'If you have lost a piece of your Zandalarian armor, I may be able to help.', 12662, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I need help recovering a missing piece of my Haruspex\'s Garb, Maywiki.', 'I need help recovering a missing piece of my Haruspex\'s Garb, Maywiki.', 12661, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Falthir, I no longer have my Zandalar Predator\'s Bracers. Can you provide a new pair?', 'Falthir, I no longer have my Zandalar Predator\'s Bracers. Can you provide a new pair?', 12660, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My Zandalar Predator\'s Belt has gone missing. Can you help, Falthir?', 'My Zandalar Predator\'s Belt has gone missing. Can you help, Falthir?', 12659, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Falthir, I have lost my Zandalar Predator\'s Mantle and need a replacement.', 'Falthir, I have lost my Zandalar Predator\'s Mantle and need a replacement.', 12658, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I seem to have misplaced my Zandalar Madap\'s Bracers. Can you help?', 'I seem to have misplaced my Zandalar Madap\'s Bracers. Can you help?', 12657, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Falthir, I have lost my Zandalar Madcap\'s Mantle. Do you have a replacement?', 'Falthir, I have lost my Zandalar Madcap\'s Mantle. Do you have a replacement?', 12656, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve lost my Zandalar Madcap\'s Tunic and require a new one, Falthir.', 'I\'ve lost my Zandalar Madcap\'s Tunic and require a new one, Falthir.', 12655, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Get in there and help those worthless fools out.', '', 12654, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Falthir, I need assistance in replacing a piece of my Predator\'s Armor.', 'Falthir, I need assistance in replacing a piece of my Predator\'s Armor.', 12653, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If you have lost a piece of your Zandalarian armor, I may be able to help.', '', 12652, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Falthir, I need assistance in recovering a piece of my Madcap\'s Outfit.', 'Falthir, I need assistance in recovering a piece of my Madcap\'s Outfit.', 12649, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '', 12648, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Jin\'rokh, I need assistance in recovering a piece of my Freethinker\'s Armor.', 'Jin\'rokh, I need assistance in recovering a piece of my Freethinker\'s Armor.', 12647, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Jin\'rokh, I am missing my Zandalar Freethinker\'s Armguards. Can you replace them?', 'Jin\'rokh, I am missing my Zandalar Freethinker\'s Armguards. Can you replace them?', 12646, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Jin\'rokh, I have lost my Zandalar Freethinker\'s Belt. Can you help?', 'Jin\'rokh, I have lost my Zandalar Freethinker\'s Belt. Can you help?', 12645, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Jin\'rokh, I fear I\'ve lost my Zandalar Freethinker\'s Breastplate. Can you supply me with a replacement?', 'Jin\'rokh, I fear I\'ve lost my Zandalar Freethinker\'s Breastplate. Can you supply me with a replacement?', 12644, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Jin\'rokh, my Zandalar Vindicator\'s Armguards have gone missing. Do you have a spare set?', 'Jin\'rokh, my Zandalar Vindicator\'s Armguards have gone missing. Do you have a spare set?', 12643, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I think I\'ve lost my  Zandalar Vindicator\'s Belt. Can you help?', 'I think I\'ve lost my  Zandalar Vindicator\'s Belt. Can you help?', 12642, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Jin\'rokh, I need assistance in recovering a piece of my Vindicator\'s Battlegear.', 'Jin\'rokh, I need assistance in recovering a piece of my Vindicator\'s Battlegear.', 12641, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Jin\'rokh, I fear I\'ve lost my Zandalar Vindicator\'s Breastplate. Can you supply me with a replacement?', 'Jin\'rokh, I fear I\'ve lost my Zandalar Vindicator\'s Breastplate. Can you supply me with a replacement?', 12640, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If you have lost a piece of your Zandalarian armor, I may be able to help.', '', 12639, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Lost some of my best soldiers that day...', 'Lost some of my best soldiers that day...', 12638, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('But that\'s not the worst of it. Before I could pull us back, a group of \'em spotted us and attacked.', '', 12637, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I dunno, grunt. I just - don\'t - know...', '', 12636, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('But how, chief? I thought the curse was lifted...\n', '', 12635, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Die, Warlock scum!', 12634, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I wish to stable my pet.', 'I wish to stable my pet.', 12633, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I wish to make Designer Island my home.', 'I wish to make Designer Island my home.', 12632, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I wish to browse your wares.', 'I wish to browse your wares.', 12631, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I desire training.', 'I desire training.', 12630, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Show me the lobsters!', 'Show me the lobsters!', 12629, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Fel orcs...', '', 12628, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s nods.', '', 12627, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You mean...', '', 12626, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Big red suckers! Bigger than any orc I\'d ever seen. Muscles out to here, tusks out to here... ', '', 12625, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You look like just the Warlock I need! The evil goblin chieftain Snarl must be defeated.', 12624, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('What further information do you have?', 'What further information do you have?', 12623, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I see you did it with your pants down and your hammer in your hand.', 12622, 0, 0, 0, 65, 0, 0, 0, 15, 0, 0, 0, 0, 0, 39653),
('', 'Hi, I\'m a newb.', 12621, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('', 'Greetings, $n. ', 12620, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('What kinda orcs, chief?', '', 12619, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sure enough, scout came runnin\' back, talkin\' bout some orcs down the path. They hadn\'t seen us yet so we figured we\'d go get acquainted.', '', 12618, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('So there we were - me and the battalion, doing a routine recon down the bone road. We\'d sent the scout up ahead to look around in case anything dangerous come up.', '', 12617, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hello, $c. If you haven\'t already, you really should speak with Farstrider Solanna.', 12616, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'As you say, sir!', 12615, 0, 0, 0, 65, 0, 0, 0, 66, 0, 0, 0, 0, 0, 39653),
('I\'m not pulling anyone from anything! He can send all of the letters that he wants. I\'m fully aware of his \'strategic\' plan, and he knows that the Dame and I are in full agreement with what the Farstriders need to be doing. Once the Shadowpine trolls have been dealt with then, and only then, will we divert our attentions to Deatholme. I know that the scourge are the greater threat, but Tranquillien is going to have to hold them off for now. It would be suicide to ignore the trolls! Dismissed, Dusking.', '', 12614, 1, 0, 0, 65, 0, 0, 0, 5, 1, 0, 0, 500, 0, 39653),
('I am growing tired of this High Executor Mavren! We dare not pull the Farstriders off of the eastern border and he knows it! He also knows that Dame Auriferous is in full agreement with me on this matter. Until she says otherwise, we stay put. That\'s all, farstrider, dismissed.', '', 12613, 1, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 500, 0, 39653),
('What! If I\'ve told him once, I\'ve told him a thousand times! I do not take orders from him, or any of the forsaken! Send a letter to Dame Auriferous letting her know of the situation. Perhaps she will let him know how things work around here. Thank you for letting me know, Dusking. Dismissed.', '', 12612, 1, 0, 0, 65, 0, 0, 0, 5, 1, 0, 0, 500, 0, 39653),
('', 'Sir, no, sir! Another dispatch has arrived from Tranquillien. It\'s High Executor Mavren again, captain. This time the language in the letter was very \'colorful\'. He reiterates his request that we marshal the Farstriders in support of the efforts against Deatholme, and suggests that you should send a runner north to Farstrider Retreat in Eversong Woods and muster their forces as well.', 12611, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'No, Captain. Another signed letter has arrived by messenger from Tranquillien. It\'s signed again by High Executor Mavren. He wants to know why we haven\'t begun pulling the Farstriders from their missions against the Shadowpine trolls as he previously ordered, sir.', 12610, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'No, sir. A signed letter from the High Executor has come in from Tranquillien. He\'s requesting that we pull all Farstrider forces from the eastern border and the trolls. He wants us to prepare to deploy to Andilien Estate as a staging area for an assault on Deatholme, sir.', 12609, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', '%s looks down at her feet.', 12608, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Is that all, Farstrider?', '', 12607, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', '%s fidgets and looks away from Captain Helios.', 12606, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Sir, Farstrider Solanna informs me that attacks on Zeb\'Tela and Zeb\'Nowa are underway. She was able to recruit a promising, young candidate to help with the situation. Also, the apothecary upstairs has made mention of a solution he believes he has to also help with the trolls.', 12605, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Out with it, Farstrider! What news do you bring?', '', 12604, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('At ease, Farstrider Dusking. What news do you have for me?', '', 12603, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Anything new, Dusking?', '', 12602, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Farstrider Dusking, what business have you to report?', '', 12601, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('A fine offer, Floyd. I wish to make Hellfire Peninsula my home.', 'A fine offer, Floyd. I wish to make Hellfire Peninsula my home.', 12599, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I deal in comfort... Soothe your savage impulse, $r. My inn is your home... ', '', 12598, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('', 'We must remain focused on our work.  Once the sanctum starts producing at full capacity, Silvermoon will be forced to send help.  Functioning arcane sanctums are in short supply.', 12597, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'He\'s got his reasons, Idonis.  He thinks the Farstriders have uncovered something.', 12596, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Calm yourself, Idonis.  Brash actions will get us nowhere!  Take a break, tap into some mana crystals.  You\'ll feel better.', 12595, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Why doesn\'t Kaendris move against Dar\'Khan yet?  What is it we\'re waiting for?', '', 12594, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s peers inside the tower and then clenches his jaw.', '', 12593, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s sighs in apparent frustration.', '', 12592, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s glares at the guards.', '', 12591, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s taps his foot impatiently.', '', 12590, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s looks like he\'d rather be anywhere else but here.', '', 12589, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s fidgets with his armor, clearly uncomfortable at the tone of the discussion.', '', 12588, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s winks slyly at Advisor Valwyn.', '', 12587, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s appears bored with the whole discussion.', '', 12586, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s grins at the High Executor\'s words.', '', 12585, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s looks over at Advisor Valwyn with a smirk on his face.', '', 12584, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s opens his mouth as if to add something, and then apparently thinks the better of it.', '', 12583, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s nods in agreement.', '', 12582, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s concentrates on the wall opposite her, clearly ignoring the looks of the Executor and his assistant.', 12581, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s reddens furiously at what she is hearing in response to her lady\'s question.', 12580, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s blanches as much of the blood drains from her face.', 12579, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s shakes her head in disbelief at what she is hearing out of the Forsaken\'s mouth.', 12578, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s lifts her nose and sniffs in response to the High Executor\'s reply.', 12577, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s glares daggers in the direction of High Executor Mavren and Deathstalker Maltendis.', 12576, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s tries to busy herself with other matters.', 12575, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s looks appalled at the Executor\'s tone!', 12574, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Disagree with me all you like, High Executor. I will weigh your counsel, and then we will take the steps to free all of Quel\'Thalas as I deem necessary. We shall continue this discussion anon.', 12573, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Mavren, I don\'t want excuses, I want results! The Farstriders aren\'t available and we\'ve received all that we\'re going to get from Silvermoon for now. I cannot ignore the Shadowpine trolls and Zul\'Aman... they\'re arrayed across our eastern border!', 12572, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'I hear what you are saying, Mavren. Nevertheless, the final decision is mine. I appreciate your assistance, but the majority of the lives on the line are blood elf. I will not have those lives carelessly thrown away!', 12571, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Perhaps we should let the matter rest for the time being until your chef has prepared your meal? You look a bit piqued if you don\'t mind my saying. We can resume our discussion when you are feeling more yourself.', '', 12570, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('We\'ve been over this before. Only a focused assault upon Deatholme will meet with success. These other targets are distractions that we can ill afford. I suggest that you inform your Captain Helios that he is to leave off his campaign against the Shadowpine trolls and focus solely on the Scourge.', '', 12569, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Spread throughout the Ghostlands, our forces will be of little use in an assault on Deatholme. No, milady, I am here to kill Dar\'khan and that is what I intend to do!', '', 12568, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Again I strongly disagree with your view of the strategic situation. Your plan will spread our forces too thin. It will leave us with only a small force to assault Deatholme. I cannot in good conscience execute such a strategy.', '', 12567, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Didn\'t drag anything in with ya, did ya?', 'Didn\'t drag anything in with ya, did ya?', 12566, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Make sure you weren\'t followed, mon!', 'Make sure you weren\'t followed, mon!', 12565, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Check your tracks!', 'Check your tracks!', 12564, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Watch your back, mon!', 'Watch your back, mon!', 12563, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'No, I was right to begin with. Deatholme must come last. We must secure all of the Ghostlands first. I will not commit the forces here to a battle against Dar\'khan with enemies to our flank and rear!', 12562, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Forsaken reinforcements? Undercity is stretched thin with the Scourge on all sides. No, this will be a matter largely dealt with by the blood elves. We Forsaken are here as backup and advisors.', '', 12561, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You are correct; we must concentrate on the Scourge. Ignore the trolls and the villages, and focus our attentions on Deatholme! With Dar\'khan defeated you will find that the rest of the Scourge \'body\' will fall quickly, lacking their \'head\'.', '', 12560, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Dame Auriferous, we are the reinforcements. It may come to pass that The Lady will send more men in time. Better that you convince Silvermoon City to muster all of its forces and put them at our disposal here.', '', 12559, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I believe that you\'re making my argument for me, but yes it would be nice if we had more reinforcements. I would counter that it would be faster to pull the Farstriders from their senseless skirmishing with the trolls.', '', 12558, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'How long until Forsaken reinforcements arrive? Our position here is tenuous. Your Lady promised us more soldiers. We must be able to concentrate solely on Deatholme and the Scourge!', 12557, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('And if your Farstriders were here to reinforce us, I might agree. But, they are busying themselves instead with the Shadowpine trolls on your eastern border. The longer we wait for them, the stronger the Scourge will become.', '', 12556, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('This is war, Dame Auriferous, and in any war lives will be lost! The only areas that we need to secure are the two ziggurats. We will turtle in and take the Tower of the Damned and its master by brute force. Then you will have your Quel\'Thalas.', '', 12555, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I strongly disagree. Dar\'khan is not going to get reinforcements because he\'ll be bottlenecked. Deatholme has only one way in and out. Your traitor was a fool to corner himself there, and I intend to exploit that weakness!', '', 12554, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('With all due respect, milady, you have not fought the Scourge as I have. The Lady appointed me to assist you in defeating Dar\'khan because of that, and you would do well to consider what I have to say.', '', 12553, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Executor, your direct assault approach will cost us more lives than I am comfortable with. A more nuanced strategy is called for; one that involves us reclaiming the surrounding territory, starting with the villages so as to cut off all points of reinforcement to Deatholme.', 12552, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I\'ve seen gnomes work harder than you, peon! Little girl gnomes - with pig tails! MOVE IT, MOVE IT, MOVE IT!', '', 12551, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If my stomach wasn\'t threatening to dislodge itself from my body and leave me for the refuse that we give to the prisoners, I might be insulted by this... this food.', 'If my stomach wasn\'t threatening to dislodge itself from my body and leave me for the refuse that we give to the prisoners, I might be insulted by this... this food.', 12550, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Is this what it\'s come down to, Cookie? Are we so low on supplies that you\'ve resorted to feeding us dung flavored wood chips?', 'Is this what it\'s come down to, Cookie? Are we so low on supplies that you\'ve resorted to feeding us dung flavored wood chips?', 12549, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It tastes like I died and went to the Nether; where slop that tastes like rotting threshadon carcass is then shoved down my throat by an obese tauren that\'s never washed their hands - or bathed...', 'It tastes like I died and went to the Nether; where slop that tastes like rotting threshadon carcass is then shoved down my throat by an obese tauren that\'s never washed their hands - or bathed...', 12548, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Do I detect a hint of cinnamon? Or is that nutmeg? Whatever it is, one thing\'s for sure - nobody cooks a donkey like you, Cookie.', 'Do I detect a hint of cinnamon? Or is that nutmeg? Whatever it is, one thing\'s for sure - nobody cooks a donkey like you, Cookie.', 12547, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Delicious, Cookie... You\'ve really outdone yourself this time, old-timer. I\'ve never tasted horse this good.', 'Delicious, Cookie... You\'ve really outdone yourself this time, old-timer. I\'ve never tasted horse this good.', 12546, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m sure to receive a commendation upon our return. We may have suffered a few losses, but overall I think we did quite nicely, don\'t you, Valanna?', '', 12545, 1, 0, 0, 65, 0, 0, 0, 1, 6, 0, 0, 500, 0, 39653),
('Take that!', '', 12544, 1, 0, 0, 65, 0, 0, 0, 48, 153, 0, 0, 2000, 0, 39653),
('I tell you now, when we get back to Farstrider Enclave there will be a full accounting of your actions, Ranger Valanna! You alone were responsible for our losses and I\'m certain that the captain will see it my way.', '', 12543, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('This isn\'t Silvermoon City! Where are we? Oh, I was confused there for a moment.', '', 12542, 1, 0, 0, 65, 0, 0, 0, 5, 18, 0, 0, 1000, 0, 39653),
('Did I not yell at them? Pull back! Pull back and regroup with suppressing fire!!', '', 12541, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('They should have listened to me.  Then I\'d receive all of the accolades that are my due!', '', 12540, 1, 0, 0, 65, 0, 0, 0, 1, 18, 0, 0, 1000, 0, 39653),
('We really must perfect a way to deal with those smelly Shadowpine trolls.$B$BOh, no offense, $c.$B$B<The apothecary grins innocently and shrugs.>', '', 12539, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Yer gonna learn why they call this place Hellfire, maggot.', '', 12538, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t say I didn\'t warn ya when I thrust my fist into the back of yer head. It\'ll feel just like home, back in the Valley of Trials.', '', 12537, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This ain\'t daycare, peon. Double time!', '', 12536, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m looking for some specialty goods. Let me browse your wares, Floyd.', 'I\'m looking for some specialty goods. Let me browse your wares, Floyd.', 12535, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('As a matter of fact, I do want to make Hellfire Peninsula my home.', 'As a matter of fact, I do want to make Hellfire Peninsula my home.', 12534, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This ain\'t your vacation getaway, $r. If you want to rest, take a bedroll and shut yer yap.$B$BAnd don\'t tell me that you wanna make Hellfire yer home. You ain\'t gonna last two minutes out in the wilds. We\'ll be shipping you back home in five small boxes.', '', 12533, 0, 0, 0, 65, 0, 0, 0, 1, 25, 1, 0, 0, 0, 39653),
('And if I hear that you palookas complained to Nazgrel again, it\'ll be one of ya\'s that I serve up next time...', 'And if I hear that you palookas complained to Nazgrel again, it\'ll be one of ya\'s that I serve up next time...', 12532, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yer slop is ready. Come n\' get it...', '', 12531, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It\'s not my fault... IT\'S NOT MY FAULT!!!$B$BIf they\'d just done what I told them to do everything would have been fine. But no! They wouldn\'t listen.$B$BNow they\'re all dead.$B$BI just want to go home. Home to Silvermoon. I\'m so tired.', '', 12530, 0, 0, 0, 65, 0, 0, 0, 5, 18, 0, 0, 500, 0, 39653),
('It is so good to see you, $g brother : sister;!  This place gives me the creeps.  While you\'re here, be sure to avail yourself of the many opportunities that these so-called Forsaken are providing.', '', 12529, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I offer what shelter I can in our shattered lands.', 'I offer what shelter I can in our shattered lands.', 12528, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Show me what I have access to, Vredigar.', 'Show me what I have access to, Vredigar.', 12527, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('As you gain renown with our town, I can make more goods available to you, $n.  With equipment in such short supply we can only afford to provide it to those we trust.', '', 12526, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Many are the paths of the Light, $c.  You must decide which to follow on this world, or any other.', '', 12525, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('$C, I\'m going to need a little time to look into this possible business concerning the blood elves. Perhaps you have other tasks that need doing in the meantime?', '', 12524, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('saved world state is: $2285W', '', 12523, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The %s is agitated by the inoculation.', '', 12522, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The %s didn\'t like what just happened.', '', 12521, 0, 0, 0, 65, 0, 0, 0, 35, 0, 0, 0, 0, 0, 39653),
('The %s doesn\'t look like it minds the crystal\'s effects.', '', 12520, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The %s wanders aimlessly.', '', 12519, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The %s seems disoriented.', '', 12518, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The %s looks confused.', '', 12517, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The %s seems overjoyed.', '', 12516, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The %s nods appreciatively.', '', 12514, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '', 12513, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<High Inquisitor Fairbanks shakes his head.>$B$BNo, $r; only one of his sons is dead. The other lives...$B$B<High Inquisitor Fairbanks points to the sky.>$B$BThe Outland... Find him there... ', '', 12512, 0, 0, 0, 65, 0, 0, 0, 274, 1, 25, 0, 0, 0, 39653),
('But his son is dead.', 'But his son is dead.', 12511, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m afraid that the blade which you hold in your hands is beyond saving. The hatred runs too deep. But do not lose hope, $c. Where one chapter has ended, a new one begins.$B$BFind his son - a more devout and pious man you may never meet. It is rumored that he is able to build the Ashbringer anew, without requiring the old, tainted blade.', '', 12510, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You tell an incredible tale, Fairbanks. What of the blade? Is it beyond redemption?', 'You tell an incredible tale, Fairbanks. What of the blade? Is it beyond redemption?', 12509, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Aye, I did. Much to the dismay of the lesser Mograine, I made my way back to the Scarlet Monastery. I shouted and screamed. I told the tale to any that would listen. And I would be murdered in cold blood for my actions, dragged to this chamber - the dark secret of the order. But some did listen... some heard my words. Thus was born the Argent Dawn...', '', 12508, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('And you did...', 'And you did...', 12507, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The blade and Mograine were a singular entity. Do you understand? This act corrupted the blade and lead to Mograine\'s own corruption as a death knight of Kel\'Thuzad. I swore that if I lived, I would expose the perpetrators of this heinous crime. For two days I remained under the rot and contagion of Scourge - gathering as much strength as possible to escape the razed city.\n', '', 12506, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('You were right, Fairbanks. That is tragic.', 'You were right, Fairbanks. That is tragic.', 12505, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The boy had picked up the Ashbringer and driven it through his father\'s heart as his back was turned. His last words will haunt me forever: \"What have you done, Renault? Why would you do this?\"', '', 12504, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('You mean...', 'You mean...', 12503, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It was all I could do to feign death as the corpses of the Scourge piled upon me. There was darkness and only the muffled sounds of the battle above me. The clashing of iron, the gnashing and grinding... gruesome, terrible sounds. And then there was silence. He called to me! \"Fairbanks! Fairbanks where are you? Talk to me Fairbanks!\" And then came the sound of incredulousness. The bite of betrayal, $r...', '', 12502, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Continue please, Fairbanks.', 'Continue please, Fairbanks.', 12501, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<High Inquisitor Fairbanks shakes his head.>$B$BNo... He stood in the background, watching as the legion of undead descended upon us. Soon after, my powers were exhausted. I was the first to fall... Surely they would tear me limb from limb as I lay there unconscious; but they ignored me completely, focusing all of their attention on the Highlord. ', '', 12500, 0, 0, 0, 65, 0, 0, 0, 274, 1, 1, 0, 0, 0, 39653),
('And did he?', 'And did he?', 12499, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It was not enough.$B$B<Fairbanks smirks briefly, lost in a memory.>$B$BA thousand came and a thousand died. By the Light! By the might of Mograine! He would smite them down as fast as they could come. Through the chaos, I noticed that the lesser Mograine was still there, off in the distance. I called to him, \"Help us, Renault! Help your father, boy!\"', '', 12498, 0, 0, 0, 65, 0, 0, 0, 1, 22, 22, 0, 4, 2, 39653),
('Yet? Yet what??', 'Yet? Yet what??', 12497, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This was the Ashbringer, fool! As the Scourge began to materialize around us, Mograine\'s blade began to glow... to hum... the younger Mograine would take that as a sign to make his escape. They descended upon us with a hunger the likes of which I had never seen. Yet...', '', 12496, 0, 0, 0, 65, 0, 0, 0, 5, 1, 1, 0, 0, 0, 39653),
('A thousand? For one man?', 'A thousand? For one man?', 12495, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<High Inquisitor Fairbanks lifts up his tabard revealing several gruesome scars.>$B$BBecause I was there... I was the Highlord\'s most trusted advisor. I should have known... I felt that something was amiss yet I allowed it to happen. Would you believe that there were a thousand or more Scourge?', '', 12494, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('How do you know all of this?', 'How do you know all of this?', 12493, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<High Inquisitor Fairbanks nods.>$B$BAye, the lesser Mograine, the one known as the Scarlet Commander, through - what I suspect - the dealings of the Grand Crusader. He led his father to the ambush like a lamb to the slaughter.', '', 12492, 0, 0, 0, 65, 0, 0, 0, 273, 1, 1, 0, 0, 0, 39653),
('You mean...', 'You mean...', 12491, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The only way a hero can die, $r: Through tragedy. The Grand Crusader struck a deal with Kel\'Thuzad himself! An ambush would be staged that would result in the death of Mograine. The type of betrayal that could only be a result of the actions of one\'s most trusted and loved companions.', '', 12490, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Incredible story. So how did he die?', 'Incredible story. So how did he die?', 12489, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Highlord was the lynchpin of the Crusade. Aye, Mograine was called the Ashbringer because of his exploits versus the armies of the Lich King. With only blade and faith, Mograine would walk into whole battalions of undead and emerge unscathed - the ashes of his foes being the only indication that he had been there at all. Do you not understand? The very face of death feared him! It trembled in his presence!', '', 12488, 0, 0, 0, 65, 0, 0, 0, 1, 273, 5, 0, 0, 0, 39653),
('I still do not fully understand.', 'I still do not fully understand.', 12487, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It was High General Abbendis, High Inquisitor Isillien, and Highlord Mograine that formed the Crusade. In its infancy, the Crusade was a noble order. The madness and insane zealotry that you see now did not exist. It was not until the one known as the Grand Crusader appeared that the wheels of corruption were set in motion.', '', 12486, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('What do you mean?', 'What do you mean?', 12485, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Aye, the Highlord Mograine: A founder of the original order of the Scarlet Crusade. A knight of unwavering faith and purity; Mograine would be betrayed by his own son and slain by Kel\'Thuzad\'s forces inside Stratholme. It is how I ended up here...', '', 12484, 0, 0, 0, 65, 0, 0, 0, 273, 1, 1, 0, 0, 0, 39653),
('Mograine?', 'Mograine?', 12483, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You mean, you don\'t know? The sword that you carry on your back - it is known as Ashbringer; named after its original owner.', '', 12482, 0, 0, 0, 65, 0, 0, 0, 6, 1, 0, 0, 0, 0, 39653),
('Curse? What\'s going on here, Fairbanks?', 'Curse? What\'s going on here, Fairbanks?', 12481, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('At last, the curse is lifted. Thank you, hero.', '', 12480, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Where else are we battling the Scourge?', 'Where else are we battling the Scourge?', 12479, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have another question.', 'I have another question.', 12478, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Are the Eastern Plaguelands currently under attack?', 'Are the Eastern Plaguelands currently under attack?', 12477, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Is Azshara currently under attack?', 'Is Azshara currently under attack?', 12476, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('The Scourge infestation grows in the Eastern Plaguelands. Every able bodied warrior is needed to stem the tide of their invasion.$B$BNumber of Necropolises remaining: $2282W', '', 12475, 0, 0, 0, 65, 0, 0, 0, 25, 0, 0, 0, 0, 0, 39653),
('The Scourge infestation grows in Azshara. Every able bodied warrior is needed to stem the tide of their invasion.$B$BNumber of Necropolises remaining: $2279W', '', 12474, 0, 0, 0, 65, 0, 0, 0, 25, 0, 0, 0, 0, 0, 39653),
('You are forgiven...', '', 12473, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Forgive me, father! Please...', '', 12472, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Did you think that your betrayal would be forgotten? Lost in the carefully planned cover up of my death? Blood of my blood, the blade felt your cruelty long after my heart had stopped beating. And in death, I knew what you had done. But now, the chains of Kel\'Thuzad hold me no more. I come to serve justice. I AM ASHBRINGER.\n', '', 12471, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Father... But... How?', '', 12470, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Renault...', '', 12469, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Who dares invade the Shattered Halls? Prepare to meet the might of the Fel Horde!', '', 12468, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Though I cannot offer you training, young $c, I can give you my blessing. Walk boldly in the Light!', 'Though I cannot offer you training, young $c, I can give you my blessing. Walk boldly in the Light!', 12467, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('In the Light we all cast shadows, my $g brother : sister;.  Do you seek further guidance today?', 'In the Light we all cast shadows, my $g brother : sister;.  Do you seek further guidance today?', 12466, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('By the Naaru, you are no mage! If you are looking for training, you must seek out a $c trainer.', 'By the Naaru, you are no mage! If you are looking for training, you must seek out a $c trainer.', 12465, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('We practitioners of the arcane and elemental ways follow a never ending path of discovery. Is that why you seek my counsel? You wish further training?', 'We practitioners of the arcane and elemental ways follow a never ending path of discovery. Is that why you seek my counsel? You wish further training?', 12464, 0, 0, 0, 65, 0, 0, 0, 1, 6, 0, 0, 1000, 0, 39653),
('I would train you, but you are no warrior.', 'I would train you, but you are no warrior.', 12463, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Do you seek further training in the ways of the warrior?', 'Do you seek further training in the ways of the warrior?', 12462, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('I\'m a hunter trainer. You\'ll want to find the $c trainer.', 'I\'m a hunter trainer. You\'ll want to find the $c trainer.', 12461, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You come in search of training, hunter?', 'You come in search of training, hunter?', 12460, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('We are one in the Light, $g brother : sister;, but I cannot train you.', 'We are one in the Light, $g brother : sister;, but I cannot train you.', 12459, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Ours is the path of purity and righteousness in the Light.', 'Ours is the path of purity and righteousness in the Light.', 12458, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered how to transmute primal earth into life.', 'DISCOVERY!   $n has discovered how to transmute primal earth into life.', 12457, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered how to transmute primal life into earth.', 'DISCOVERY!   $n has discovered how to transmute primal life into earth.', 12456, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered how to transmute primal fire into mana.', 'DISCOVERY!   $n has discovered how to transmute primal fire into mana.', 12455, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered how to transmute primal mana into fire.', 'DISCOVERY!   $n has discovered how to transmute primal mana into fire.', 12454, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered how to transmute primal water into shadow.', 'DISCOVERY!   $n has discovered how to transmute primal water into shadow.', 12453, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered how to transmute primal shadow into water.', 'DISCOVERY!   $n has discovered how to transmute primal shadow into water.', 12452, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$C, you saved me!  I owe you a debt that I can never repay.  I\'ll go see if I can help the others.', '$C, you saved me!  I owe you a debt that I can never repay.  I\'ll go see if I can help the others.', 12451, 35, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('Many thanks to you, $c.  I\'d best get to the crash site and see how I can help out.  Until we meet again.', 'Many thanks to you, $c.  I\'d best get to the crash site and see how I can help out.  Until we meet again.', 12450, 35, 0, 0, 65, 0, 0, 0, 3, 0, 0, 0, 0, 0, 39653),
('Huh?  What happened?  Oh... my head feels like it\'s going to explode!  I\'d best get back to the crash site.', 'Huh?  What happened?  Oh... my head feels like it\'s going to explode!  I\'d best get to the crash site.', 12449, 35, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Light be praised!  I would have died out here if it weren\'t for you, $c!  I must get to the ship.', 'The Light be praised!  I would have died out here if it weren\'t for you, $c!  I must get to the ship.', 12448, 35, 0, 0, 65, 0, 0, 0, 4, 0, 0, 0, 0, 0, 39653),
('You don\'t see too many apprentices around these parts, do you?  I\'m beginning to think it\'s because the magisters give us all the dangerous work they\'d rather not do themselves.', '', 12447, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'We are very fortunate to be alive, you and I!', 12446, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered the Flask of Pure Death recipe!', 'DISCOVERY!   $n has discovered the Flask of Pure Death recipe!', 12445, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered the Flask of Blinding Light recipe!', 'DISCOVERY!   $n has discovered the Flask of Blinding Light recipe!', 12444, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered the Flask of Relentless Assault recipe!', 'DISCOVERY!   $n has discovered the Flask of Relentless Assault recipe!', 12443, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered the Flask of Mighty Versatility recipe!', 'DISCOVERY!   $n has discovered the Flask of Mighty Versatility recipe!', 12442, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered the Flask of Fortification recipe!', 'DISCOVERY!   $n has discovered the Flask of Fortification recipe!', 12441, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('DISCOVERY!   $n has discovered the Super Rejuvenation Potion recipe!', 'DISCOVERY!   $n has discovered the Super Rejuvenation Potion recipe!', 12440, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Nevermind my injuries, $g brother : sister;. It\'s a miracle that any of us are alive!', '', 12439, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Do you wish to learn the blacksmithing profession or is there something else you wish to tell me?', 12438, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'What brings you here, $n?  We don\'t see too many people around these parts.  With good reason, I suppose.', 12437, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Haha... I gonna kill puny $r and make trophy of your skull!', '', 12436, 0, 0, 0, 65, 0, 0, 0, 15, 0, 0, 0, 0, 0, 39653),
('The Lich King brought only small forces to bear against each of Azeroth\'s capital cities, while their main forces periodically attack the following lands:$B$BAzshara, the Blasted Lands, the Burning Steppes, the Tanaris Desert, the Eastern Plaguelands and Winterspring.', '', 12435, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Where are we battling the Scourge?', 'Where are we battling the Scourge?', 12434, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You wouldn\'t believe some of the rabble that we\'ve had come through here lately. Most are more trouble than the supposed help that they provide. Nothing at all like you.$B$BYou sure you don\'t want to sign up with the Farstriders?', 12433, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'One set of trolls dealt with, one yet to go. You have no idea how much I appreciate what you\'re doing, $n! Before you came along I didn\'t think we\'d ever get the Shadowpine problem under control.', 12432, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('', 'I\'m glad that you\'re here to help, $c. The faster we can deal with these trolls, the faster we\'ll get to send the scourge back to where they came from.', 12431, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'We must maintain a state of vigilance, $c! Between Dar\'Khan the Betrayer and his Scourge, and the Shadowpine trolls backed by the might of Zul\'Aman, we\'re barely keeping our heads above water here. We really shouldn\'t have to be dividing our attentions!$B$BI hope you\'re here to help.', 12430, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Thank you for becoming my next victim!', '', 12429, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I shall find you mortals!  You shall pay for destroying the Ash\'ari Crystals!', '', 12428, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('World of Warcraft and Coca-Cola (R) have teamed up to bring you the iCoke-World of Warcraft Summer Promotion.  Look for codes under the caps of specially marked bottles of Coca-Cola.  Then return here and enter the code to win a virtual item.', 'World of Warcraft and Coca-Cola (R) have teamed up to bring you the iCoke-World of Warcraft Summer Promotion.  Look for codes under the caps of specially marked bottles of Coca-Cola.  Then return here and enter the code to win a virtual item.', 12427, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Marketing - iCoke Redemption Greeting (S.H.E. non-Quest)', 12426, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I must say, you delivered my poison and dealt with those trolls most ruthlessly, $c. You\'ve got the makings of quite a talented young $g man : lady;!', '', 12425, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('We really must perfect a way to deal with those smelly Shadowpine trolls!', '', 12424, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('Sometimes I stand here, looking into the forest beyond the lake, and I see the land as it once was... green and full of life.', '', 12423, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your battle here is but the smallest mote of a world wide invasion, whelp!  It is time you learned of the powers you face!', '', 12422, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('These heroics mean nothing, $c.  Your future is sealed and your soul is doomed to servitude!', '', 12421, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our dark master has noticed your trifling, and sends me to bring a message... of doom!', '', 12420, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Hold your positions!', 12419, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Enemy sighted!  Ready your weapons!', 12418, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Open fire!', 12417, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$C, you didn\'t happen to see a courier on your way here? We are awaiting word from Silvermoon City and their messenger is late!', '', 12416, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Whatever the courier delivers, I hope that it\'s good news.', '', 12415, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('At this rate I\'m going to pace a rut into the road. I hope the messenger from Kalecgos arrives soon.', '', 12414, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('The courier from Silvermoon City is delayed. Perhaps I should send a scout to look for him?', '', 12413, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('The hour runs late. The message from Silvermoon City is delayed for some reason.', '', 12412, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I don\'t have all day to wait out here for that message. There are things that Dame Auriferous has tasked me with seeing to!', '', 12411, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Where is the messenger from the regent lord?', '', 12410, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('What word from Silvermoon?  The courier is late!', '', 12409, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Where\'s that courier?', '', 12408, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'Marketing - iCoke Redemption Greeting (S.H.E.)', 12407, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Is there no end to these undead?  It seems that for every ghoul or skeleton we kill, two take its place.', 12406, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A list... how intriguing.  Ah yes, the shipment of fireworks for Lord Saltheril.  He hasn\'t paid for them; are you here to purchase them on his behalf, $c?', '', 12405, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('I have all manner of goods for sale, $c.  Browse at your leisure.', '', 12404, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('We have won $2219W battles against the Scourge.  Stand firm, $n!  We must persevere!', '', 12403, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We have won $2219W battles against the Scourge.  Take heart, $n.  While many battles lie ahead, heroes, heroes from every realm have risen to fight them.', '', 12402, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Is that a list from Lord Saltheril that you have there? Yes, I can sell you a batch of appetizers, fresh off the fire.', 12401, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'If you have the coin, I have the food and drink to keep that appetite of yours satisfied.  Every copper goes to keeping the Retreat in tip-top shape.', 12400, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('We have won $2219W battles against the Scourge.  Gird yourself, $n, for this war is far from over.', '', 12399, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('How many battles have we won?', 'How many battles have we won?', 12398, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Is that a list from Saltheril\'s Haven?  No doubt, his lordship will require a bottle of my finest.  And, of course, any friend of Lord Saltheril deserves a special price on such a fine vintage.', '', 12397, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('Can\'t you see that I\'m trying to have a conversation with the lady?  Oh, very well, she seems preoccupied anyway.$B$BI deal in only the finest drinks, both local and exotic in vintage.  Care to have a look?', '', 12395, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Dar\'Khan thinks we\'ll roll over for the Scourge without putting up a fight.  We shall prove him wrong, $n.', '', 12394, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Let\'s go.', 12393, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Phase 3! <PH>', '', 12392, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s flees after seeing Kel\'Thuzad fall!', '', 12391, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You hold my father\'s blade, $n. My soldiers are yours to control, my $g Lord:Lady;. Take them... Lead them... The impure must be purged. They must be cleansed of their taint.', '', 12390, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Bow down! Kneel before the Ashbringer! A new dawn approaches, brothers and sisters! Our message will be delivered to the filth of this world through the chosen one!', '', 12389, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ya Rly! <PH>', 'Ya Rly! <PH>', 12388, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Oh Rly? <PH>', '', 12387, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I look into the eye...', 'I look into the eye...', 12386, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Port back to center', '', 12385, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take me with you, $g sir:ma\'am;.', 'Take me with you, $g sir:ma\'am;.', 12384, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('And so it begins...', 'And so it begins...', 12383, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My $g Lord:Lady;, please allow me to live long enough to see you purge this world of the infidels.', 'My $g Lord:Lady;, please allow me to live long enough to see you purge this world of the infidels.', 12382, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Have you come to save this world? To cleanse it?', 'Have you come to save this world? To cleanse it?', 12381, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am unworthy, $g sir:ma\'am;.', 'I am unworthy, $g sir:ma\'am;.', 12380, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Kneel! Kneel before the Ashbringer!', 'Kneel! Kneel before the Ashbringer!', 12379, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ashbringer...', 'Ashbringer...', 12378, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This is holy ground, heathen.', 'This is holy ground, heathen.', 12377, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You risk destroying us all, $r! You must be terminated!', 'You risk destroying us all, $r! You must be terminated!', 12376, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You hold evil in your hands, fool! REPENT!', 'You hold evil in your hands, fool! REPENT!', 12375, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The dead walk among us!', 'The dead walk among us!', 12374, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Destroy the Scourge invader now, before it\'s too late!', 'Destroy the Scourge invader now, before it\'s too late!', 12373, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Will these unrelenting Scourge attacks never end?', 'Will these unrelenting Scourge attacks never end?', 12372, 7, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('This has gone too far.  How dare the Scourge attack Stormwind!  Destroy it before more come!', 'This has gone too far.  How dare the Scourge attack Stormwind!  Destroy it before more come!', 12371, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('There\'s one of the Scourge, right over there!', 'There\'s one of the Scourge, right over there!', 12370, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('How can I get anything done with the Scourge running amok around here?!', 'How can I get anything done with the Scourge running amok around here?!', 12369, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Did you see that?  There\'s a Scourge over there!', 'Did you see that?  There\'s a Scourge over there!', 12368, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('I just saw a Scourge!  Kill it!', 'I just saw a Scourge!  Kill it!', 12367, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Scourge spotted nearby!', 'Scourge spotted nearby!', 12366, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Welcome back, $n.  You\'ve proven a worthy ally against Ragnaros and your presence is always welcome among us.', '', 12365, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'ve served our cause with great loyalty, $n.  Allow me to present you with an unending source of our elemental quintessence.', '', 12364, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I desire this eternal quintessence, Duke Hydraxis.', 'I desire this eternal quintessence, Duke Hydraxis.', 12363, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Destroy the Scourge invader now, before it\'s too late!', 'Destroy the Scourge invader now, before it\'s too late!', 12362, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Will these unrelenting Scourge attacks never end?', 'Will these unrelenting Scourge attacks never end?', 12361, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('This has gone too far.  How dare the Scourge attack Undercity!  Destroy it before more come!', 'This has gone too far.  How dare the Scourge attack Undercity!  Destroy it before more come!', 12360, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('There\'s one of the Scourge, right over there!', 'There\'s one of the Scourge, right over there!', 12359, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('How can I get anything done with the Scourge running amok in here?!', 'How can I get anything done with the Scourge running amok in here?!', 12358, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Did you see that?  There\'s a Scourge over there!', 'Did you see that?  There\'s a Scourge over there!', 12357, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('I just saw a Scourge!  Kill it!', 'I just saw a Scourge!  Kill it!', 12356, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Scourge spotted nearby!', 'Scourge spotted nearby!', 12355, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Scourge inside Trade Quarter!  Destroy!', '', 12354, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('There Scourge outside Trade Quarter!', '', 12353, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Leave no survivors!', '', 12352, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Take no prisoners! Drive these heathens from our lands!', '', 12351, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Frostwolf forces gain the General\'s Warcry.', '', 12350, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Stormpike forces gain the General\'s Warcry.', '', 12349, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s devours all nearby zombies!', '', 12348, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s belches out a disgusting Bile Sludge!', '', 12347, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What can I do for you?  No, wait!  What can you do for me?', '', 12346, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What can I do for you, $n?  Make it quick, I don\'t have all day!', '', 12345, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You\'d better not be causing trouble, $n!', 12344, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('No worry, we find you.', '', 12343, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Why you run away? We make your corpse into Scourge.', '', 12342, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Gangway, ye scurvy dog!  Revilgaz has spared me from the gallows but my punishment might be nearly as bad.', 'Gangway, ye scurvy dog!  Revilgaz has spared me from the gallows but my punishment might be nearly as bad.', 12341, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It\'s a testament to our race\'s tenacity that Fairbreeze Village still stands.  We shall never concede defeat to the Scourge ever again.', '', 12340, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our Sanctums syphon arcane power from ley-line currents that traverse our lands invisible to the naked eye.$B$BWith the Sunwell gone, they provide us with a steady and reliable source of energy.', '', 12339, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s drops its weapon.', '', 12338, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Scourge are at the entrance to the Royal Quarter!  Kill them!!', 'The Scourge are at the entrance to the Royal Quarter!  Kill them!!', 12337, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Rogues\' Quarter attacked by Scourge!  Help!', '', 12336, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Scourge attack Magic Quarter!', '', 12335, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Scourge in sewers!  We need help!', '', 12334, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Dreadguard, hold your line.  Halt the advance of those Scourge!', '', 12333, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My Royal Dreadguard, you will deal with this matter as befits your station.  That, or you will wish that you had.', 12332, 1, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('', 'The Scourge attack against my court has been eliminated.  You may go about your business.', 12331, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You spare parts!  We make more Scourge in necropolis.', '', 12330, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What?  This not Naxxramas!  We not like this place... destroy!', '', 12329, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hahaha, your guards no match for Scourge!', '', 12328, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Raaarrrrggghhh!  We come for you!', '', 12327, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Lich King say to tell you... DIE!', '', 12326, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We come destroy puny ones!', '', 12325, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s skitters out from the shadows...', '', 12324, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s howls through the halls...', '', 12323, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s flaps down from the ceiling...', '', 12322, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'What have you done? FOOL! You brought it... NO!', 12321, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '%s scratches at her throat.', 12320, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Good work, one and all!  The Scourge at the castle have been defeated.', '', 12318, 7, 0, 0, 65, 0, 0, 0, 71, 0, 0, 0, 0, 0, 39653),
('Hold the line!  Protect the King at all costs!', '', 12317, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('The Scourge are at the castle entrance!  For Stormwind!  For King Anduin!', 'The Scourge are at the castle entrance!  For Stormwind!  For King Anduin!', 12316, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Light help us... the Scourge are in the Park!', 'Light help us... the Scourge are in the Park!', 12315, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('%s scratches at his throat.', '', 12314, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What is it Tarsis? I don\'t know what to do!', 'What is it Tarsis? I don\'t know what to do!', 12313, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You... The frame! How? You must not... It... the Destroyer...', '', 12312, 0, 0, 0, 65, 0, 0, 0, 5, 274, 0, 0, 0, 0, 39653),
('Scourge in the Trade District!  Have at them!', 'Scourge in the Trade District!  Have at them!', 12311, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('To arms!  Scourge spotted in the Cathedral of Light!', 'To arms!  Scourge spotted in the Cathedral of Light!', 12310, 7, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Haven\'t you been listening? No, I very much doubt we would be having this conversation had Kel\'Thuzad formed the staff. Kel\'Thuzad holds the head. His underlings hold forty splinters of Atiesh. The last piece - the base - was uncovered by Brann Bronzebeard. He was last seen in the Silithus desert; undoubtedly doing his best to stay as far away as possible from the relentless seekers Kel\'Thuzad has dispatched into the world.', '', 12309, 0, 0, 0, 65, 0, 0, 0, 274, 1, 1, 0, 0, 0, 39653),
('So Kel\'Thuzad holds all of the pieces?', 'So Kel\'Thuzad holds all of the pieces?', 12308, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Kel\'Thuzad has put forth considerable effort in attempting to reform the staff. The pieces were once scattered across this world, from Kalimdor to the South Seas. I myself held twenty of the pieces at one point in time - until they were stolen from me by Kel\'Thuzad\'s minions. It is why I am here.', '', 12307, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('So what has led you to Naxxramas?', 'So what has led you to Naxxramas?', 12306, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It was lost when the Violet Citadel fell... splintered into forty-two pieces.', '', 12305, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('What happened to the staff?', 'What happened to the staff?', 12304, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I put at your disposal whatever assistance I can offer.', 'I put at your disposal whatever assistance I can offer.', 12303, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('Give me one of your magic items.', 'Give me one of your magic items.', 12302, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('The first steps of our fight against the Scourge go well. We have had some successes, and hopefully my assistance can aid you in bringing future success to the battle.', 'The first steps of our fight against the Scourge go well. We have had some successes, and hopefully my assistance can aid you in bringing future success to the battle.', 12301, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('The battle goes well. The Scourge forces seem weakened. I believe it will only be a matter of time before we drive them from our shores. I will turn my magics to you, to aid in this struggle.', 'The battle goes well. The Scourge forces seem weakened. I believe it will only be a matter of time before we drive them from our shores. I will turn my magics to you, to aid in this struggle.', 12300, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('The battle is won. For the time being, the Scourge threat has been pushed back. Our resources can be channeled into aiding you, in thanks and preparation for the future.', 'The battle is won. For the time being, the Scourge threat has been pushed back. Our resources can be channeled into aiding you, in thanks and preparation for the future.', 12299, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('<Wake Tarsis up.>', '<Wake Tarsis up.>', 12298, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Tarsis is badly injured.>', '', 12297, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s sits down.', '', 12296, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s gets to one knee.', '%s gets to one knee.', 12295, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Tarsis\'s eyes light up.>$B$BI held it once... I held it despite the warnings of the Kirin Tor. I held it, mortal... Power unending. Power to do what I desired, as I desired. And just as quickly, it was taken from me. But I had tasted... And that taste was all that it took.  ', '', 12294, 0, 0, 0, 65, 0, 0, 0, 1, 1, 273, 0, 0, 0, 39653),
('You said you would have it back. What does that mean?', 'You said you would have it back. What does that mean?', 12293, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Atiesh, Greatstaff of the Guardian. The staff handed down through the ages to each of the Guardians of Tirisfal. The staff corrupted by Sargeras. The staff of the last Guardian. The staff of Medivh.\n', '', 12292, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('What staff?', 'What staff?', 12291, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Tarsis grabs you weakly by the collar. Even in death you see power unimaginable in his eyes.>$B$BAm I? Then listen closely, for more nonsense is about to escape my lips. Within this citadel you will find my life\'s work: The exact location of every fragment of the splintered staff.', '', 12290, 0, 0, 0, 65, 0, 0, 0, 53, 273, 0, 0, 0, 0, 39653),
('You are talking nonsense, mage. ', 'You are talking nonsense, mage. ', 12289, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I would have it back, mortal. Atiesh... From it I would create the Highborne anew. I would have it all back. Even the Queen...', '', 12288, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('I still do not understand.', 'I still do not understand.', 12287, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am Highborne, $r. It has no meaning now. There was a time, though, when this world was ruled by Highborne. Ten thousand years past...', '', 12286, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Why have you done such horrible things?\n', 'Why have you done such horrible things?\n', 12285, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The things I have done... such horrible things...$B$B<Tarsis begins to sob.>\n', '', 12284, 0, 0, 0, 65, 0, 0, 0, 1, 18, 0, 0, 0, 0, 39653),
('What are you talking about, mage?', 'What are you talking about, mage?', 12283, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Tarsis groans.>$B$BThere may still be time... Listen closely, mortal.$B$BThrough time and across the Nether I have searched. Deals made with a host of evil and villainy so wretched...$B$B<Tarsis coughs blood into his hands.>$B$BWould you... would you believe that even Elune has turned her back on me, $r? To die here, in this manner now...', '', 12282, 0, 0, 0, 65, 0, 0, 0, 1, 7, 6, 0, 3, 4, 39653),
('Thank you, Omarion. You have taken a fatal blow for the team on this day.', 'Thank you, Omarion. You have taken a fatal blow for the team on this day.', 12281, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Omarion grumbles something under his breath.>$B$BBut of course I can help you, dear $g boy:girl;. It is my dying wish... my final desire. Please, take this handbook. The information on its pages are a compilation of all that I know and have learned in the past 30 some-odd years of my miserable life. Give the handbook to that good for nothing apprentice of mine that\'s probably sitting on his fat duff at Light\'s Hope Chapel.', '', 12280, 0, 0, 0, 65, 0, 0, 0, 14, 1, 1, 0, 0, 0, 39653),
('Omarion, I am not a craftsman. Can you still help me?', 'Omarion, I am not a craftsman. Can you still help me?', 12279, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Sin\'dorei and Forsaken share a common goal in the Ghostlands, $n.  Together we shall defeat the Scourge and who knows... perhaps the Forsaken will be valuable allies in our quest to reach Outland.', '', 12278, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Lay down your weapons, your feuds have no place here!', 'Lay down your weapons, your feuds have no place here!', 12277, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will abide by our rules around here, miscreant!', 'You will abide by our rules around here, miscreant!', 12276, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your actions will not be tolerated!', 'Your actions will not be tolerated!', 12275, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Show me your wares, Wilhelm.', 'Show me your wares, Wilhelm.', 12274, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Master craftsman Omarion just vanished one night. Like a toot in the wind... Poof! Gone! Bah, now I\'m the only one left to craft the goods for the boys on the front lines. ', '', 12273, 0, 0, 0, 65, 0, 0, 0, 1, 14, 1, 0, 0, 0, 39653),
('%s releases the last of its energies into the nearby runestone, successfully reactivating it.', '', 12272, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Show me where I can fly.', 'Show me where I can fly.', 12271, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I need to go. Evil stirs. Die well, Omarion.', 'I need to go. Evil stirs. Die well, Omarion.', 12270, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am a master blacksmith, Omarion.', 'I am a master blacksmith, Omarion.', 12269, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Icebane Bracers.', 'Icebane Bracers.', 12268, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Icebane Gauntlets.', 'Icebane Gauntlets.', 12267, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Icebane Breastplate.', 'Icebane Breastplate.', 12266, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have what you need, $c.', '', 12265, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Polar Bracers.', 'Polar Bracers.', 12264, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Polar Gloves.', 'Polar Gloves.', 12263, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Polar Tunic.', 'Polar Tunic.', 12262, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Icy Scale Bracers.', 'Icy Scale Bracers.', 12261, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Icy Scale Gauntlets.', 'Icy Scale Gauntlets.', 12260, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Icy Scale Breastplate.', 'Icy Scale Breastplate.', 12259, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Perhaps I can teach you something...', '', 12258, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am a master leatherworker, Omarion.', 'I am a master leatherworker, Omarion.', 12257, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Glacial Wrists.', 'Glacial Wrists.', 12256, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Glacial Gloves.', 'Glacial Gloves.', 12255, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Glacial Cloak.', 'Glacial Cloak.', 12254, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Glacial Vest.', 'Glacial Vest.', 12253, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A tailor, eh? Very well. What would you like to learn about, tailor?', '', 12252, 0, 0, 0, 65, 0, 0, 0, 6, 1, 0, 0, 0, 0, 39653),
('I am a master tailor, Omarion.', 'I am a master tailor, Omarion.', 12251, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You honor me with your presence, $r. Alas, it is too late for me. I pass from this world soon, but... I know so much. So much is in this head of mine. So much that could help this world fend off the beasts of this citadel of depravity.$B$BPerhaps if you are a master of a trade... Yes, perhaps you would take the knowledge I hold and use it to save this world.\n', '', 12249, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Could it be? One that passes through these halls with a purpose? Aye, a righteous fire burns in your belly, $r.$B$BMy life may soon end, but the knowledge I hold must be shared with the world. It is, after all, why I am here now.$B$BAre you a master of a trade?\n', '', 12248, 0, 0, 0, 65, 0, 0, 0, 6, 1, 1, 0, 0, 0, 39653),
('Is this the best they could do?$B$B<Omarion musters the strength to laugh.>$B$BYou do not possess the resolve to face a monster like Kel\'Thuzad. You will crumble before his minions - just like those that have come before you...$B$BLeave me here to die. I refuse to return to a world that champions the likes of you.\n', '', 12247, 0, 0, 0, 65, 0, 0, 0, 6, 1, 1, 0, 0, 0, 39653),
('There are those who would say that the Argent Crusade is a thing of the past.  I am one of them, but not because the Scourge have fallen.$b$bNo... it is because of their stubborn ways.  They\'ve become too much like the church that they seceded from: too rigid, too governed by honor and order.  This is what I\'m trying to tell Barthalomew, anyhow.$b$bSure, it may sound a bit jingoistic, but it makes for a good debate.', '', 12246, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('', 'Well, you didn\'t come all this way out here to jaw over a cup of tea. Let\'s see how you might be able to help get us out of this situation.', 12245, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('These Runestones protect the lands in Eversong from becoming tainted by the Scourge.  The Western Runestone failed long ago, forcing us to burn the ground around it.$B$BAs long as I live I won\'t allow the remaining Runestones to fail us.  That is my oath.', '', 12244, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You will not stop our deepening shadow, $c.  Now... join us!  Join the ranks of the Chosen!', '', 12243, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s spots a zombie to devour!', '', 12242, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I have another question.', 'I have another question.', 12241, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Exalted.', 'Exalted.', 12240, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Revered.', 'Revered.', 12239, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Honored.', 'Honored.', 12238, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Friendly.', 'Friendly.', 12237, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Certainly, $n.$B$BAdventurers that the Dawn views as friendly must submit a combined total of 60 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 220 insignias.$B$BI must admit, the price is quite high for adventurers not favored by the Dawn.\n', 12236, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('', 'Certainly, $n.$B$BAdventurers that the Dawn views as exalted must submit a combined total of 12 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 54 insignias.$B$BThose exalted in the eyes of the Dawn receive the greatest discounts.\n', 12235, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Miranda, could you please tell me the insignia cost of items that you are offering for adventurers of exalted reputation?', 'Miranda, could you please tell me the insignia cost of items that you are offering for adventurers of exalted reputation?', 12234, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The situation is more grim than many have been led to believe. The Forsaken are here as allies in the fight against our common enemy, the Scourge.$B$BTrust me when I say this, without them the Ghostlands would be lost and the Scourge would already have overrun all of Eversong Woods!$B$BBut more than anything else, we need your help in reclaiming our once proud lands!', '', 12233, 0, 0, 0, 65, 0, 0, 0, 1, 5, 0, 0, 500, 0, 39653),
('', 'Certainly, $n.$B$BAdventurers that the Dawn views as revered must submit a combined total of 14 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 90 insignias.$B$BThose that are revered by the Dawn will find the cost of superior items quite reasonable! The cost for the more powerful items is still high.\n', 12232, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Miranda, could you please tell me the insignia cost of items that you are offering for adventurers of revered reputation?', 'Miranda, could you please tell me the insignia cost of items that you are offering for adventurers of revered reputation?', 12231, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Arcanist Vandril, what are the Forsaken doing here?', 'Arcanist Vandril, what are the Forsaken doing here?', 12230, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'Certainly, $n.$B$BAdventurers that the Dawn views as honored must submit a combined total of 40 insignias to access superior items. To access items of even greater power, they would be required to submit a total of 150 insignias.$B$BI must admit, the price is high even for those honored amongst the Dawn.\n', 12229, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Miranda, could you please tell me the insignia cost of items that you are offering for adventurers of honored reputation?', 'Miranda, could you please tell me the insignia cost of items that you are offering for adventurers of honored reputation?', 12228, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Certainly, $n. You only need to tell me what reputation you would like to know about.\n', 12227, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Miranda, could you please tell me the insignia cost of items that you are offering for adventurers with other reputations?', 'Miranda, could you please tell me the insignia cost of items that you are offering for adventurers with other reputations?', 12226, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your deaths shall be slow and painful!', '', 12225, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Mortal fools!  The ghouls of Deatholme will feast on your remains!', '', 12224, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Death is the price you shall pay for this insolence!', '', 12223, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Th... thank you.  I thought I was going to die.', '', 12222, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You have my thanks!', '', 12221, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thanks, I should\'ve never left Silverpine Forest.', 12220, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'ve dealt the decisive blow against the Shadowpine trolls, $n. I only hope that we can muster our forces quickly enough to finish them off before they receive reinforcements from Zul\'Aman.$B$BIt would be nice if Tranquillien were to reinforce us.', '', 12219, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Your help with the Shadowpine trolls is proving invaluable, $c. Keep this up and maybe we\'ll be able to turn our attention back to dealing with the Scourge.', '', 12218, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You\'re a one-$g man : woman; rescue machine. That\'s three of my Farstriders that you\'ve saved now!', '', 12217, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('What can I say, $c? You\'re a true $g hero : heroine;! Not only have you personally saved many of my rangers, but you\'ve dealt a decisive blow against the Shadowpine trolls. Are you sure that you don\'t want to stay here and be one of my Farstriders?$B$BFare well, $n.', '', 12216, 0, 0, 0, 65, 0, 0, 0, 1, 2, 0, 0, 1000, 0, 39653),
('Word got back to me through channels concerning Lady Sylvanas\'s reaction to you and the recovery of her necklace. I still think you did the right thing; don\'t worry too much about how the lady reacted.$B$BNow, state your business.', '', 12215, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Good to see you again, $g man! : gorgeous!; I think we would work well together; $g see you around. : I hope we get to do so.;', '', 12214, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('You\'ve done us exemplary service, $n. Between dealing with the gnolls at the Underlight Mines, and the mummified trolls in the Amani Catacombs, you\'ve dealt a mighty blow to our enemies!$B$B$G Good job! : We should get together for drinks sometime, what do you say?;', '', 12213, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('The High Executor is a very busy man, $c.  Maybe I can help you with whatever you need?', '', 12212, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Stray arcane forces can do strange things to the land, the elements and even the spirits of the dead.', '', 12211, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You\'re welcome to stay at the Farstrider Enclave for as long as you\'d like, $c.  We welcome any who would aid us in our endeavors in the Ghostlands.', 12210, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The Scourge are establishing small staging points in the places under attack, receiving communications and other assistance from the necropolises that fly overhead. From what we can tell, the only way to root them out is by killing the ground forces that surround the points.', '', 12209, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Many an advantage can be gained from getting to know your enemy.  Take that lesson to heart, $n.$B$BThe more we learn about the Scourge the better prepared we are to defeat them.', 12208, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What can I do?', 'What can I do?', 12207, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('If additional support is not soon sent to the Burning Steppes, I fear the Scourge will establish a base of operations there. If you can, you should go there to aid the defenders.$B$BNumber of Necropolises remaining: $2281W', '', 12206, 0, 0, 0, 65, 0, 0, 0, 25, 0, 0, 0, 0, 0, 39653),
('Are the Burning Steppes currently under attack?', 'Are the Burning Steppes currently under attack?', 12205, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('The Scourge infestation grows in the Blasted Lands. Every able bodied warrior is needed to stem the tide of their invasion.$B$BNumber of Necropolises remaining: $2280W', '', 12204, 0, 0, 0, 65, 0, 0, 0, 25, 0, 0, 0, 0, 0, 39653),
('Are the Blasted Lands currently under attack?', 'Are the Blasted Lands currently under attack?', 12203, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('It seems the army of the Scourge has come to Tanaris. A significant number of their necropolises and other forces have been dispatched there.$B$BNumber of Necropolises remaining: $2283W', '', 12202, 0, 0, 0, 65, 0, 0, 0, 25, 0, 0, 0, 0, 0, 39653),
('Is Tanaris currently under attack?', 'Is Tanaris currently under attack?', 12201, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('For the time being, that area is free of Scourge influence. I fear it will only be a matter of time before they return.', '', 12200, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Indeed, the hills of Winterspring are currently attempting to withstand a renewed Scourge assault. Your assistance would help them greatly.$B$BNumber of Necropolises remaining: $2284W', '', 12199, 0, 0, 0, 65, 0, 0, 0, 25, 0, 0, 0, 0, 0, 39653),
('Is Winterspring currently under attack?', 'Is Winterspring currently under attack?', 12198, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('OH NO YOU DIDN\'! ITS ON NOW! <PH>', '', 12197, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Amongst the various pieces of parchment containing checklists and other information from the Farstriders, one stands out. It is a drawing of a hideous troll, perhaps the most fearsome creature that you have ever seen!', '', 12196, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s dies.', '', 12195, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Think you could help me to get out of here?', 12194, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Lilatha, get someone to look at those injuries. Thank you for bringing her back safely.', '', 12193, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('%s nods in relief to Ranger Lilatha and her escort.', '', 12192, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thank you for saving my life and bringing me back to safety, $n!', 12191, 1, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('', 'Captain Helios, I\'ve been rescued from the Amani Catacombs. Reporting for duty, sir!', 12190, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'There\'s Farstrider Enclave now, $c. Not far to go... look out!  Troll ambush!!', 12189, 1, 0, 0, 65, 0, 0, 0, 1, 5, 0, 0, 500, 0, 39653),
('', 'I can see the light at the end of the tunnel!', 12188, 1, 0, 0, 65, 0, 0, 0, 25, 0, 0, 0, 0, 0, 39653),
('', '$n, let\'s use the antechamber to the right.', 12187, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Before we can overcome external obstacles like the Scourge and the Amani trolls, we must overcome obstacles from within.  The Wretched have been a nuisance for long enough; it is time we vanquished them.', '', 12186, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Sin\'dorei have lost far too much in the past years.  Our land, our homes, even our identities...$B$BIt\'s about time we started taking it all back.', 12185, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Without delivery of the Underlight ore in such a timely fashion, our research would have failed.$B$BJust wait until Shatharia shows her head here again. I\'ve got some interesting tasks for her, you can be sure of it!', '', 12184, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Where could she possibly be? I sent my apprentice, Shatharia, to the Underlight Mines to the west quite some time ago. We need those ore samples back, and fast or our experiment is going to fail!', '', 12183, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'Thanks for getting that ore and taking it to Magister Quallestis, $c. I suppose that I should head back, but I\'m afraid of the punishment I\'m going to receive because I couldn\'t get the ore myself.$B$BDon\'t tell the magister, ok?', 12182, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Well this is troublesome! How am I supposed to collect the ore samples for the magisters if the mines have been overrun with gnoll vermin?', 12181, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('The tides of war have come again. From the cold north, the Lich King\'s necropolises have laid siege to our lands.  He sends flying necropolises to invade across the world.', '', 12180, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'We\'ve important work to do, $n.  Let us attack our enemies while their guard is down.  Let us show them that sin\'dorei vengeance never forgets nor forgives.', 12179, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s overloads!', '', 12178, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This sign contains various announcements and notices of rewards.', '', 12177, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What\'s happening?', 'What\'s happening?', 12176, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('%s rushes to the aid of Feugen!', '', 12174, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '$C, Dame Auriferous has conveyed to me her great pleasure in the service that you have done us in the past. She wishes to extend to you her hope that you will continue to be a champion of sin\'dorei interests here in the Ghostlands.', 12173, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Normally it would not be my place to speak with you directly; rather, you would seek an audience with milady. However, I did give you a task directly, so what is it that we need to discuss?', 12172, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'If it is a matter of import that you wish to speak on, $c, it may be more appropriate to seek an audience with Dame Auriferous. I warn you though, she is very busy and you may be in for quite a wait.', 12171, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I seek a sample of your restorative draught, apothecary.', 'I seek a sample of your restorative draught, apothecary.', 12170, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('The drafts of fresh air that blow from Eversong from time to time really upset my stomach, if you know what I mean.', '', 12169, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Varnis coughs violently as the restorative draught takes effect.>$B$BThank you for rescuing me.  I must go back to Tranquillien at once!', '', 12168, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Well met, $r. I am here as a resource of advice for the High Executor to make use of as he will. I am confident that together we can forge the Horde into something that is even stronger than before and turn back the Scourge menace once and for all!', '', 12167, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('<The blood elf lies limp on the table.  While he\'s still breathing, he appears to have been the victim of potent sedative toxins.>', '', 12166, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('A bit ungrateful, aren\'t we?  The way out is clear, flee quickly!', 'A bit ungrateful, aren\'t we?  The way out is clear, flee quickly!', 12165, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ahhhhggg... this pain in my head is killing me.$B$BThey must\'ve sent you to rescue me.  Took them long enough!  Do you have any idea of the things they do to prisoners here?', 12164, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '<The Forsaken female is curled up on the floor, her face in a grimace.  She does not appear capable of getting up on her own at the moment.>', 12163, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re free to go now.  The way out is safe.', 'You\'re free to go now.  The way out is safe.', 12162, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Greetings, $r.  I am Ambassador Sunsorrow of the sin\'dorei, or blood elves as we are commonly known.  I have high hopes that this new bond between us and the Horde will be mutually beneficial.', '', 12161, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('<The blood elf lies on the floor in some manner of induced torpor.>', '', 12160, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Administer the restorative draught.>', '<Administer the restorative draught.>', 12159, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<The blood elf quickly regains consciousness as you pour the draught into his mouth.>$B$BI owe you my life, $c.  Without your help I would\'ve succumbed to the Scourge\'s painful torture.', '', 12158, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('That could have gone better. $n, come here, please. I have something I need you to take care of for me.', '', 12157, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s loses its link!', '', 12156, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s is jolted back to life!', '', 12155, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am diseased. Please cure me, medic.', 'I am diseased. Please cure me, medic.', 12154, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve got too much to do and not enough time to do it in, $r! Please, get out of my way.$B$BIf you\'re infected with the maggot slime or ghoul rot, I might be able to help you.', 'I\'ve got too much to do and not enough time to do it in, $r! Please, get out of my way.$B$BIf you\'re infected with the maggot slime or ghoul rot, I might be able to help you.', 12153, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('I\'ve got too much to do and not enough time to do it in, $r! Please, get out of my way.', 'I\'ve got too much to do and not enough time to do it in, $r! Please, get out of my way.', 12152, 0, 0, 0, 65, 0, 0, 0, 5, 1, 0, 0, 0, 0, 39653),
('I cannot stand the pain.  I must find a new source.', 'I cannot stand the pain.  I must find a new source.', 12151, 10, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('More, more, more!  I must feed soon.', 'More, more, more!  I must feed soon.', 12150, 10, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The pain...the need...I hunger for more...', 'The pain...the need...I hunger for more...', 12149, 10, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Our caravans go out \'bout twice a day, but I\'ll be damned if the Scourge haven\'t gone out of their way to stop Didier and his mules from getting shipments to the front lines. Craziest thing I\'ve ever seen. If only we had the heroic adventurin\' types to help protect the shipments...', '', 12148, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('', 'Oh, quite succulent. Many thanks, Mrs. Chambers.', 12147, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The boar is superb!', 12146, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Indeed... lovely dress, Jessica.', 12145, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'And might I add, that dress is lovely! You must tell me where you got it from.', 12144, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thank you, Jessica.', 12143, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'ve really outdone yourself this time, Mrs. Chambers. Not a spot of mold to be found!', '', 12142, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Is this a mango? Stupendous!', '', 12141, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thank you, Mrs. Chambers.', '', 12140, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Delicious!', '', 12139, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The fish is exquisite, Jessica.', '', 12138, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My compliments to the chef!', '', 12137, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Welcome to Light\'s Hope Chapel, stranger.', 12136, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Please let me know if you need anything else!', 12135, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'And for the ladies, roast baby boar. Enjoy!', 12134, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Father, you had the bowl of fruit? Right?', 12133, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ok, you had the fish platter, Commander. Enjoy!', 12132, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$R, report! What news of significance do you bring? Be quick about your business... Dame Auriferous and I are in the middle of a strategic discussion.', '', 12131, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Yes... what do you want, $r? Can\'t you see I am busy here?', '', 12130, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('How can I work under these conditions?! And all of these disgusting Forsaken around here! I weep for Tranquillien and Quel\'Thalas!', '', 12129, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I think I hear something! Chambers must be coming. Make way! Make way!', '', 12128, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Alright, I\'ll sign writs now. Bring \'em to the front, maggots.', '', 12127, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Job well done, soldier. Dismissed!', '', 12126, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<Field Marshal Chambers growls.>$B$BSo you\'re the riff-raff that assisted Didier in getting the supplies here in one piece? Where are the rest of you? I know there\'s gotta be more. Chickens like you generally roam in huge packs.$B$BBah, just give me the damned writ so I can sign off on it.\n', '', 12125, 0, 0, 0, 65, 0, 0, 0, 6, 25, 1, 1, 1, 1, 39653),
('Yes, sir! Thank you, sir!', 'Yes, sir! Thank you, sir!', 12124, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Name, rank and serial number, soldier.\n', '', 12123, 0, 0, 0, 65, 0, 0, 0, 25, 6, 0, 1, 1, 1, 39653),
('Good thing that you deactivated the moon crystal at An\'owyn when you did, $c! Come around any time you feel like pitching in with my research here.', '', 12122, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Are you the reinforcements? The night elves have been routed!', '', 12121, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'We are most pleased with your actions against the night elves. When you uncovered their plot to use the ley-line nexi and their so-called moon crystals to spy upon us, you strengthened our position here by an order of magnitude.$B$BYou have our gratitude, $n.', 12120, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'It is very important that we find out what the the night elves are up to, $c! Please concentrate all of your efforts toward that end.', 12119, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Poor little donkey. It was only a wee lad.', '', 12118, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You won\'t get away this time!', 12117, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Terrible thing, what happened to them mules... Metz is gonna have my hide for this failure.', '', 12116, 0, 0, 0, 65, 0, 0, 0, 18, 1, 0, 0, 0, 0, 39653),
('Look out... the night elves are back!', '', 12115, 1, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Whew! That was some hard work, $r. I haven\'t seen the Scourge this aggressive since...$B$B<Guard Didier swallows hard.>$B$BSince the last war...', '', 12114, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('Onward! The front lines await!', '', 12113, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Use 8 necrotic runes and disrupt his ritual.', 'Use 8 necrotic runes and disrupt his ritual.', 12112, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('This cultist is in a deep trance...', '', 12111, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Don\'t be afraid of the sword, nubling. It\'s the mutton that gets ya!', '', 12110, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('The time has come for Horde and Alliance to look towards Northrend and the invasion of the Lich King. In recent days, territories across Kalimdor and the Eastern Kingdoms have come under attack. Will you take up arms to save your land from destruction at their hands?', '', 12109, 0, 0, 0, 65, 0, 0, 0, 25, 0, 0, 0, 0, 0, 39653),
('', 'Welcome to Tranquillien, $c. I apologize for the state that you find it in. As you can see, we\'ve been having some trouble, but the Forsaken, and their Lady Sylvanas Windrunner, have been gracious enough to lend us a great deal of assistance in our time of need.$B$BIf you can lend a hand please do not hesitate to do so. We can use all of the help that we can get in our struggle against the myriad forces arrayed against us.', 12108, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Such a delight to see you again, $c. No, really. You\'re the reason that I\'m making money here, hand over fist.$B$BNow, what can I sell to you today?', '', 12107, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Ah, hello there, $r. As you can see, I\'m not open for business quite yet. Now, if you\'ll excuse me, I\'m very busy.', '', 12106, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Alright, everything looks in order. Let\'s get this show on the road.', '', 12105, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What can I help you find?', 'What can I help you find?', 12104, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What business brings you here, $c?', '', 12103, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I received word that you were able to help Ranger Valanna and the lieutenant at Zeb\'Sora.$B$BThank you, $c. I suppose I should make my way back to Farstrider Enclave now.', '', 12102, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'I\'m sure that help from Farstrider Enclave will be here soon to help me and this useless lieutenant get to safety. You might not want to stick around; I\'ve heard all sorts of strange sounds coming from the lake and that village over yonder.', 12101, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ah, here\'s the $g hero : heroine; of the hour now! Good to see you again, $n! I trust that you\'re still destroying the Scourge wherever you find them?', '', 12100, 0, 0, 0, 65, 0, 0, 0, 71, 0, 0, 0, 0, 0, 39653),
('Sometimes it feels like I\'ll never go back to being a simple functionary in service to Dame Auriferous. I\'m not cut out for war.$B$BThankfully there are those like you who burn to see Quel\'Thalas restored to its former beauty. Crush the Scourge, $c! Crush them wherever you can!', '', 12099, 0, 0, 0, 65, 0, 0, 0, 1, 5, 0, 0, 500, 0, 39653),
('', 'I sent Ranger Salissa south to the enclave and Ranger Lethvalin west to Tranquillien more than a day ago! Have you seen either of them? Are you the aid that\'s been sent back?', 12098, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The high executor and Dame Auriferous are making me wait, but I don\'t have time for this! My friends are out there dying, $c!', '', 12097, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('I\'m far too busy to be playing \'guess the smell\' with you, $r. State your business or get out of my sight!', '', 12096, 0, 0, 0, 65, 0, 0, 0, 25, 1, 1, 0, 0, 0, 39653),
('', 'It is shameful that we sin\'dorei have lost so much of what we used to call home.  It shall not be long before we regain our strength and retake our southern lands back from the Scourge!', 12095, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Who are you?  I feel... so... cold.', '', 12094, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It\'s going to take a bit of work, but I think we can save this blood elf\'s life.', 12093, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('$C, look what they\'ve done to our beloved land. The Scourge must be destroyed!', '', 12092, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('', 'If you are one that prefers to hunt in the outdoor world, both Felwood\'s treants and Un\'Goro\'s lashers are an excellent source of fronds.$B$BIf you are more of a risk-taker, the eastern and western wings of Dire Maul will provide you with a nearly limitless supply of savage fronds.', 12091, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Rayne, where should I look for savage fronds?', 'Rayne, where should I look for savage fronds?', 12090, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Is this a serious question? You really don\'t know?$B$BIf you are the cowardly sort, afraid to get their hands too dirty, you will find Dark Iron scraps on the creatures in the Burning Steppes and Searing Gorge.$B$BIf you\'re the bloodthirsty adventuring type, the dungeons of Blackrock Spire and Blackrock Depths hold quite a large supply of the scraps.', '', 12089, 0, 0, 0, 65, 0, 0, 0, 6, 1, 1, 0, 0, 0, 39653),
('Korfax, where can I find Dark Iron scraps?', 'Korfax, where can I find Dark Iron scraps?', 12088, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Ah, a good question.$B$BIf you prefer hunting in the great outdoors, there are elementals here in the Plaguelands, Azshara, Burning Steppes, Felwood, Silithus, Winterspring, and even Un\'Goro Crater.$B$BIf you are the type that laughs in the face of danger, then perhaps you should visit Dire Maul. I have heard that a great many elemental abberations exist within its walls. You would also do well in seeking out the elementals employed by the Dark Iron dwarves of Blackrock Depths.', 12087, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Where can I find core of elements?', 'Where can I find core of elements?', 12086, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, I\'d like to purchase a ride down to the Ghostlands.', 'Yes, I\'d like to purchase a ride down to the Ghostlands.', 12085, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Heading down to Tranquillien today, $c, or is there something else that I can do for you?', 12084, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Hello, friend. How may I be of service to you today?', '', 12083, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('I\'d like to fly back to Silvermoon City.', 'I\'d like to fly back to Silvermoon City.', 12082, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('No greater freedom than to soar through the skies, $c. What can I do for you today?', '', 12081, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Another lovely, gloomy day here in Tranquillien, wouldn\'t you say, $c?$B$BWhat can I do for you?', 12079, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Are you daft? Did you miss the BONY SKELETAL CREATURES littering the landscape on your way over here?$B$B<Rohan sighs.>$B$BIf you\'re the outdoor type, you\'ll find skeletal creatures all over both the Western and Eastern Plaguelands. Trust me, you can\'t miss \'em - they certainly won\'t miss you if they get the chance.$B$BIf you\'re a dungeon type, Stratholme and Scholomance are definitely the place to be for bone fragments.', '', 12078, 0, 0, 0, 65, 0, 0, 0, 6, 1, 1, 0, 0, 0, 39653),
('Where can I find bone fragments?', 'Where can I find bone fragments?', 12077, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Those filthy beasts are all over the place.$B$BIf you prefer hunting outdoors, you\'ll find most of them around Plaguewood and Terrordale, with a good concentration of them in the Terrorweb tunnel. They are also likely to appear at almost any Scourge encampment in the Eastern Plaguelands.$B$BIf you\'re a hearty dungeon crawler, you\'ll find a good lot of them in Stratholme and a few of the necrofiend variety in Scholomance.', '', 12076, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Where can I find crypt fiend parts, Leopold?', 'Where can I find crypt fiend parts, Leopold?', 12075, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I cannot be teachin\' a Tauren to ride a Raptor.', 'I cannot be teachin\' a Tauren to ride a Raptor.', 12074, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Damn all these vermin! I don\'t suppose you could help me with this situation?', '', 12073, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('', 'How wonderful. Time for the party to start.', 12072, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Milord, with much of the sin\'dorei nobility regrettably crushed, does that mean that you are likely to receive an elevation soon?  I\'m so excited for you!', 12071, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'I was just thinking... we really ought to take a trip south one of these nights, maybe have an evening picnic overlooking the fighting at the border? What do you think, milord? Wouldn\'t that just be so exciting?', 12070, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Now be silent and note where you are, lest I inform Lord Fordring and his knights that you are no longer here on amicable terms. I am certain he would take great pleasure in seeing to your \'atonement.\'', '', 12067, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yet you think that recovering Ashbringer will somehow turn the tide of battle? Let me let you in on a little secret, Commander: The power of the Ashbringer came from the man who would wield it... I was there, Commander. I watched him burn legions of undead in righteous fire before he would even unsheathe the blade. Alas, your grasp on history is ... lacking.', '', 12066, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It was your leadership that manipulated a grieving child to try and recover the sword. A child that has grown into a man with nothing but vengeance and hatred in his heart! And for what? You are no closer to the sword now than you were five years ago.\n', '', 12065, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ah, guests of the Master. I hope you\'ve been watching your step in here.', '', 12064, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('The Ashbringer is dead and there will never be another like him. The lesser Mograine is a far cry from the man his father was. You know this, Commander! It was, after all, your own leadership that was responsible for the death of the Scarlet Highlord Mograine. ', '', 12063, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('So this is what you have come for? To try and claim that which is the reason for the Dawn\'s existence and the Crusade\'s downfall? You open old wounds with your words, Commander!', '', 12062, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It\'s been a long day of cutting down the mindless Scourge that endlessly parade down the Dead Scar.  I hope you\'re here to lend a hand and not to waste my time with idle chatter.', 12061, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We\'re too merciful with the Wretched.  We ought to drive a sword through each of them.$B$BTheir boldness in Sunsail Anchorage is unpardonable.', '', 12060, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Greetings, travelers. I have been instructed to treat any bearer of a key to Karazhan as an honored guest of the Master. Feel free to ask any questions you wish of me. How may I assist you?', '', 12059, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('There is always... Ashbringer.', 'There is always... Ashbringer.', 12058, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('So why are you here? What are we to do if there is no hope?', '', 12057, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Too little, too late. The dam has broken. We are a bump in the road at best.', 12056, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You lack tact, Commander. This is not surprising. However, you are right in that the Horde will be forced to act. But not just the Horde. They already come - heroes from across the world.', '', 12055, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Whatever. The revolting, unkempt Horde filth...', 12054, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Tauren.', '', 12053, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The heathens will be forced to react. Orcs, bull-men...', 12052, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Scourge activity in the Plaguelands has increased ten-fold. We are receiving reports of Scourge attacks from as far away as Kalimdor! Now how do you suppose this has happened? How have the wretched undead done that which was previously thought impossible? Is nowhere safe?', '', 12051, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Even demons are capable of fear...', '', 12050, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('%s lowers the sound of his voice to a whisper.', '', 12049, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your leader takes residence at the doorstep to Naxxramas. Do you think he does not feel the pressure?\n', '', 12048, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Your message did reach us, Commander, but by no means is our involvement here sanctioned by the Grand Crusader.', 12047, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Faith... Some have lost it, others have found it. It cannot be destroyed and it cannot be created.$B$BOr perhaps you speak of the vestments of Faith? Armor worn by our priests and most devout warriors into battle against the Scourge during the last war.$B$BAye, much of it is lost... Stolen by the fiends of Naxxramas.', '', 12046, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 1, 1, 0, 39653),
('Tell me about faith, Father.', 'Tell me about faith, Father.', 12045, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I make no pretenses, maggot. The darkness such items hold could very well destroy the both of us. That is why the price is so high. If I\'m going to die, it\'s going to be as a rich man.$B$BAnd I don\'t give an ounce of gnoll spit how you die, only that you do as I ask. Bring me what I require and we will both benefit - or die, but I\'ve already explained this...', '', 12044, 0, 0, 0, 65, 0, 0, 0, 1, 1, 274, 1, 1, 1, 39653),
('I also seek such power.', 'I also seek such power.', 12043, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It is power, imbecile.$B$B<Mataus\'s eyes darken.>$B$BThese fools send idiots like you into Naxxramas to retrieve desecrated armor so that they may purify it and restore the pieces to their former glory.$B$B<Mataus spits.>$B$BJust the thought of such utter stupidity brings the bile up to my throat.$B$BI too seek that armor, but in its most foul and desecrated form.', '', 12042, 0, 0, 0, 65, 0, 0, 0, 275, 1, 25, 1, 2, 2, 39653),
('What is Plagueheart armor?', 'What is Plagueheart armor?', 12041, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I have tracked the various fragments of the staff across this world and in doing so, discovered Kel\'Thuzad\'s plans to reform the staff. He has already collected several of the staff\'s fragments - which are being held by his most trusted lieutenants.$B$BI cannot emphasize enough the importance of keeping the greatstaff of the Guardian out of Kel\'Thuzad\'s grasp. Frankly, I do not know what the result would be, other than a catastrophe of epic proportion.', 12040, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('Is there anything else?', 'Is there anything else?', 12039, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'After the fall of Dalaran, I took my leave from the Kirin Tor. I spent years watching over Atiesh, only to have my purpose amongst the Kirin Tor taken from me in one fell swoop. I would find the staff, though it might take a lifetime. That is how I came to join the Argent Dawn and why I am here now.', 12038, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('Please, tell me more.', 'Please, tell me more.', 12037, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'There is not much more to tell. Dalaran was nearly wholly destroyed by Archimonde, the staff lost, presumably shattered by the barrier\'s fail-safe mechanisms.$B$BThere are those that believe the staff to be the cause of Archimonde\'s reprisal.', 12036, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('This is disturbing. Please continue.', 'This is disturbing. Please continue.', 12035, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '<Angela nods.>$B$BAfter the deaths, the Six decided that the best course of action was to seal the staff behind impenetrable barriers of magic and appoint a watcher: A guardian of the staff... I would be that watcher.', 12034, 0, 0, 0, 65, 0, 0, 0, 273, 1, 0, 1, 1, 0, 39653),
('What?', 'What?', 12033, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'What followed were a series of tragic events, leading to the death of every Kirin Tor mage that came into contact with Atiesh.$B$BYou see, it was an artifact with sentience. A sentience granted to it by Sargeras...', 12032, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 1, 1, 0, 39653),
('Please continue.', 'Please continue.', 12031, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'After the fall of Karazhan, the Kirin Tor dispatched an assembly of mages to search the tower and seize all items of import... for the purposes of \"research.\" It was then that the fabled staff was discovered and brought back to Dalaran.', 12030, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('Please continue.', 'Please continue.', 12029, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The corruption of a fallen titan. The corruption of the Destroyer. After all, the staff was forged from the seed of hate. That is, of course, what has brought me here...', 12028, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('What corruption?', 'What corruption?', 12027, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'It is a story of legend and one that I do not have the time nor the inclination to retell. Just know that Medivh was the last of the Guardians. The greatstaff of Atiesh was a focal point of his power and a focal point of corruption.', 12026, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 1, 1, 0, 39653),
('Please continue.', 'Please continue.', 12025, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Progeny of Aegwynn, he that would be the last Guardian of Tirisfal... Medivh.', 12024, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 1, 0, 0, 39653),
('What Guardian? I don\'t understand any of this.', 'What Guardian? I don\'t understand any of this.', 12023, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Like Kel\'Thuzad, I too was once a mage of the Kirin Tor. And like Kel\'Thuzad, I seek the legendary Atiesh, greatstaff of the Guardian. Our fates are intertwined as such, $c.', 12022, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 1, 1, 0, 39653),
('What is Atiesh?\n', 'What is Atiesh?\n', 12021, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I am a crafter of some renown, $c. With the proper materials, I am able to craft an armor known as Dreamwalker. Druids - and even some shaman - are drawn to this armor due to its magical properties. Are you interested?', 12020, 0, 0, 0, 65, 0, 0, 0, 1, 1, 6, 1, 1, 1, 39653),
('What kind of services?', 'What kind of services?', 12019, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I think not. Rimblat has already proven that new life can grow from the sundered earth. Now we must find a way to reproduce and, more importantly, sustain the growth.$B$BWhile I am here, I am also offering my services to adventurers entering Naxxramas.', 12018, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 1, 1, 0, 39653),
('Are these lands not beyond healing? They look pretty beat up.', 'Are these lands not beyond healing? They look pretty beat up.', 12017, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'We are all drawn here for different reasons, $c.$B$B<Rayne smiles.>$B$BI am here to meet with Rimblat of the Earthen Ring. He has some interesting theories on cleansing these lands.', 12016, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 1, 1, 0, 39653),
('Hello, Rayne. What brings the Cenarion Circle to the Plaguelands?', 'Hello, Rayne. What brings the Cenarion Circle to the Plaguelands?', 12015, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You can\'t do this to me!  We had a deal!', '', 12014, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What?  Oh, not this again!', '', 12013, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Members only, scrub!\n', '', 12012, 0, 0, 0, 65, 0, 0, 0, 273, 25, 0, 1, 1, 0, 39653),
('Hey wait, Gadgetzan has a disco?', 'Hey wait, Gadgetzan has a disco?', 12011, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m as sane as the next guy, $g fella:lady;. Believe what you will, but I AM capable of fashioning this armor. If you\'re interested, maybe we can make a deal. The sooner I can get out of the assassination business, the better.', '', 12010, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 1, 1, 0, 39653),
('Wow, you\'re insane, aren\'t you?', 'Wow, you\'re insane, aren\'t you?', 12009, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Yes, Bonescythe. You see, it was our tenor, an ornery fellow known as Don Julio, who got me started on the whole thing. In his travels throughout Lordaeron, Don Julio picked up many interesting skills, one of them being the ability to take the bones of fallen Scourge and fashion them into a lethal set of leather armor - perfectly suited for an assassin.', '', 12008, 0, 0, 0, 65, 0, 0, 0, 1, 1, 25, 1, 1, 1, 39653),
('What? Bonescythe?', 'What? Bonescythe?', 12007, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Good question, $r. In my younger days I was footloose and fancy free without a care in the world. In those days I would sing in a barber shop quartet out of Stormwind known as the Four Dons. That\'s where I learned how to craft the Bonescythe digs.', '', 12006, 0, 0, 0, 65, 0, 0, 0, 273, 1, 1, 1, 1, 1, 39653),
('So what brings you to Light\'s Hope?', 'So what brings you to Light\'s Hope?', 12005, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Ah, as the title states I am an assassin for the Scarlet Crusade. I spend my days exterminating high priority targets and nights at the Gadgetzan discotheque. Dancing is my true calling. Assassination just pays the bills.', '', 12004, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('What is it that you do exactly, Rohan?', 'What is it that you do exactly, Rohan?', 12003, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Isn\'t this just so much fun? I\'m so glad that Lord Saltheril throws these parties every night, especially with all of that nastiness occurring to the south. Kind of just makes all of that go away, don\'t you think?', 12002, 0, 0, 0, 65, 0, 0, 0, 1, 6, 0, 0, 500, 0, 39653),
('', 'Greetings, my $g lord : lady;. I trust that you are having a pleasant time?', 12001, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('', 'Oh goody! The party\'s about to start!', 12000, 0, 0, 0, 65, 0, 0, 0, 4, 0, 0, 0, 0, 0, 39653),
('Is that so? How very interesting. My dear, why don\'t you run along and powder your nose? I have much to think about.', '', 11999, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Oh, most definitely, Elisara. But please, can you show the least bit of patience?', '', 11998, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Hmm, what was that? I\'m sorry my dear, I must have been daydreaming.', '', 11997, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('As you say, my dear, as you say.', '', 11996, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Lord Saltheril, my dear, did you notice that supplies for the party are a little low? We really should send for one of those couriers from Fairbreeze Village to deliver more of whatever is needed. I especially like those little hors d\'oeuvres wrapped in the smoked bacon. What are those called?', 11995, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'I\'m so tired. We really shouldn\'t have stayed up so late last night,,, well this morning. But it was fun! You do throw the best soirees milord.', 11994, 1, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Oh, my lordship, I do so hope that you\'ve arranged for more of that excellent wine from Silvermoon City. I dare say drinking it makes me feel almost as forward as a common woman!', 11993, 1, 0, 0, 65, 0, 0, 0, 1, 24, 0, 0, 500, 0, 39653),
('', 'Milord, do you think that we can join the party soon? I\'m so bored in here.', 11992, 1, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('<Yawn> Is it dawn already? Ah well, all good things... as they say. I don\'t know about the rest of you, but I\'m going inside.', '', 11991, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Ah, excellent! Let the festivities begin. Let us retire to the terrace. Now, where did I put my drink?', '', 11990, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Hello, $c. I trust that you are enjoying youself? What do you think of the party? I do so hope that we aren\'t running out of anything. Nothing kills a fete faster than running out of drinks and hors d\'oeuvres, wouldn\'t you say?$B$BYes, well, I must be about attending to my other guests. Do enjoy your stay.', '', 11989, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Oh, hello there.. um, what\'s your name?$B$BNo matter, what brings you to my home-away-from-home here out in the beautiful countryside?', '', 11988, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('The name of Earthshatter has been one held by my family for hundreds of years. And like my father and his father before him, I too have inherited the right to create the vestments of my namesake. ', '', 11987, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('I was a young tauren, barely having reached adolescence at the time, but I knew that those that would brave the battles for our freedom were well protected in my namesake\'s vestments.', '', 11986, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('Continue please.', 'Continue please.', 11985, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('In the last war, tauren fought. Shaman were sent in defense of this world against the Scourge invasion. Most lost their lives. Many were otherwise ripped asunder, their body parts used for foul experiments in that cursed citadel. I mourn their passing but my heart swells with pride at their courage.', '', 11984, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 1, 1, 39653),
('What brings a tauren to the Plaguelands?', 'What brings a tauren to the Plaguelands?', 11983, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am unable to teach a Tauren to ride a Skeletal Mount.  I am sorry but there is nothing I can do for you.', 'I am unable to teach a Tauren to ride a Skeletal Mount.  I am sorry but there is nothing I can do for you.', 11982, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I have discovered a use for the carapace of the crypt fiend and its various body parts. I am able to fashion an extremely light and very deadly set of armor by combining the fragments with some of the desecrated magical armors lost in Naxxramas.', '', 11981, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('Continue please.', 'Continue please.', 11980, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The preternatural ability of the crypt fiend to hunt and kill its foe is one studied and vaunted by men in my profession. I, myself, have slain thousands of the beasts in my crusade to rid this world of Scourge.$B$BWhile I loathe the crypt fiend for its merciless nature, its abilities must be admired. It has a job and it does it - very well.', '', 11979, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 1, 1, 1, 39653),
('What is Cryptstalker armor?', 'What is Cryptstalker armor?', 11978, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The armor of Redemption was worn by our most pious knights - armor worthy of the Lightbringer himself!$B$BThousands fell in the last war; their vestments stripped from their corpses and taken to the dread citadel of Naxxramas.$B$BIt is said that the death knights of Naxxramas corrupt the Redemption plate mail for their own use.$B$BSuch tragedy... ', '', 11977, 0, 0, 0, 65, 0, 0, 0, 1, 1, 274, 1, 1, 1, 39653),
('What is Redemption armor?', 'What is Redemption armor?', 11976, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Yes, we shall!', 11975, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Shall we slay them for the impertinence of disturbing our sleep?', '', 11974, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('', 'Would-be interlopers, I\'m afraid.', 11973, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Hello, sister. What have we here?', '', 11972, 0, 0, 0, 65, 0, 0, 0, 2, 0, 0, 0, 0, 0, 39653),
('', 'Hello, brother.', 11971, 0, 0, 0, 65, 0, 0, 0, 3, 0, 0, 0, 0, 0, 39653),
('', 'In life, I focused my energies on healing others. Let us see in death how much pain I can cause!', 11970, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('I\'m what you call a capitalist, $r.', '', 11969, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You think you can summon us? We are the ones that summon, not you! We bash you good for this and suck the marrow from your bones!', '', 11968, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('Muahahahaha! What is this pathetic spectacle I see before me? Well, what are you waiting for? I hunger, and you look as if you may make for a passable appetizer!', '', 11967, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('All of Nature\'s might is at my disposal, puny mortals. Let us see which of my many forms it will be that ends your suffering!', '', 11966, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of this armor worn by heroes.', '', 11965, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('Anything else?', 'Anything else?', 11964, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It was not until after his controversial death that the knights and warriors of Lordaeron would wear similarly fashioned suits in honor of their fallen hero. While the death of Mograine was a great victory for Kel\'Thuzad, the resulting martyrdom would be felt until the end of the war.$B$BWhere one did fall, many would rise...', '', 11963, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 1, 1, 1, 39653),
('Continue please.', 'Continue please.', 11962, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The first suit of Dreadnaught armor was made exclusively for the Scarlet Highlord Mograine.  Whilst donning the full suit, the Highlord looked himself to be a demon from the depths of the Nether.$B$BAye, \'twas quite a sight to behold as Mograine would wade into a hundred Scourge, Ashbringer held high, and come out on the other side in a cloud of dust and flames - enemies left in ashes beneath his feet.', '', 11961, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 1, 1, 39653),
('What is Dreadnaught armor?', 'What is Dreadnaught armor?', 11960, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You so little and puny... you no make good servants for Kormok!', '', 11959, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('First Kormok crush your bones!  Then Kormok burn your soul!', '', 11958, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re but worms beneath my feet.  You dare challenge me?', '', 11957, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Who dares to disturb my eternal rest?  Your deaths will be slow and painful!', '', 11956, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your insolence is appalling, fool!  I shall feast on your soul!', '', 11955, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I crush weaklings like you every day!  Bring it on!', '', 11954, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'m going to kick yer ugly head in!', '', 11953, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You want a fight?  A fight you\'ll get!', '', 11952, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What is it that you want, lemming? Get out of my sight before you find out why I am known as the Wrathcaster.', '', 11951, 0, 0, 0, 65, 0, 0, 0, 6, 1, 25, 0, 0, 2, 39653),
('', 'Hello, $c. Please try not to draw too much attention.', 11950, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'ve been expec...$B$B<Rimblat coughs.>$B$BExcuse me, old habit. I am Rimblat of the Earthen Ring. ', '', 11949, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('They almost sent my brother, Loksey, to this gathering. He cannot even take care of his hounds, let alone represent the Scarlet Crusade in a competent manner.', '', 11948, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('The title is misleading. I\'m really a very nice person once you get to know me.', '', 11947, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Watch, druid. The earth still breathes. It yearns to be cleansed.', '', 11946, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'That is wonderous, Rimblat! Even this foul, sundered earth is not beyond healing.', 11945, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Argent Dawn might be impotent idealists but their delusional leader knows that they are outmatched. I have been sent here as an emissary of the Scarlet Crusade. An ambassador, if you will... It is doubtful that we could even dent the armies of Kel\'Thuzad - united or not - but we might be able to contain them long enough for some sort of miracle to happen.$B$BAs for me? I\'ll die in battle...$B$B<Marjhan shrugs.>\n', 11944, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('What is the Brotherhood of the Light?  Well... We are all members of the Argent Crusade at the core - members of the Argent Crusade that aren\'t held in check by morals, guilt and useless human emotion.', '', 11943, 0, 0, 0, 65, 0, 0, 0, 1, 1, 1, 0, 0, 0, 39653),
('The Lich King is attempting to make his presence known in our world. This must not be allowed to occur.\n', '', 11942, 0, 0, 0, 65, 0, 0, 0, 1, 1, 0, 0, 0, 0, 39653),
('We of the Brotherhood of the Light are not as lenient as our brethren when it comes to meting justice to those that would do this world wrong.', '', 11941, 0, 0, 0, 65, 0, 0, 0, 25, 1, 0, 0, 0, 0, 39653),
('', 'It is said that Kel\'Thuzad seeks the legendary Atiesh, greatstaff of the Guardian.$B$BYes, the very staff once held by Medivh.', 11940, 0, 0, 0, 65, 0, 0, 0, 1, 273, 0, 0, 0, 0, 39653),
('%s goes into a rage after seeing $n fall in battle!', '%s goes into a rage after seeing $n fall in battle!', 11939, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device. Delivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renown for their aeronautical and combustible feats!$B$BIf you\'d like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer on the south edge of Thunder Bluff\'s central rise. She\'ll aim you at the target far to south on Stonebull Lake!', 11938, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device. Delivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renown for their aeronautical and combustible feats!$B$BIf you\'d like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer on the east end of the faire. I hear that she\'s placed a target ring way over on Crystal Lake for you to aim for as you sail through the air!', 11937, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Cannon?', 'Cannon?', 11936, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Our newest attraction, and at no cost to you I might add, these miniature tanks, or Tonks as we\'ve cleverly named them, can be controlled from any of the Tonk Control Consoles spread throughout the faire.$B$BAll that you have to do is activate an available control console. Each tonk will come equipped with a stock set of devices, and a random special power to unleash upon your enemy!$B$BHold epic battles with your friends, cruise around, or just cause wild mayhem... the choice is yours!', 11935, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Tonks?', 'Tonks?', 11934, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Ysida lives thanks to your courage, $n.  I am deeply in your debt and shall assist you as much as it is in my power.', '', 11933, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Talk about making the wrong investment!$B$BLord Valthalak\'s dark book of spells fetched a pretty penny in the black market.  It\'s too bad he didn\'t take too kindly to getting his possessions stolen.  That stinker got us even after he\'d been dead for months!', '', 11932, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You did it... you\'ve slain Baron Rivendare!  The Argent Dawn shall hear of your valiant deeds!', 11931, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I\'ll be fine for now, don\'t worry about me.  I\'ll find a way out of here once I\'ve performed some cleansing rituals in this room.  Foul magic taints this place, $n.', 11930, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Use your tonk action bar above your standard action bar to attack other tonks.', '', 11929, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Friends of yours?', '', 11928, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your meddling ends here, $n!  Lord Valthalak shall have his revenge!', 'Your meddling ends here, $n!  Lord Valthalak shall have his revenge!', 11927, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We broke up afterward, that\'s what happened. Too much bad blood, I guess...it had been building for a while. And the thing with the amulet was the straw that broke the kodo\'s back.$B$BEver since then Valthalak\'s servants have been picking us off one by one. Most of the amulet piece holders are dead, their souls corrupted by the portion of Valthalak\'s spirit contained within it.$B$BThat\'s why I\'m glad that you\'re here, $n. With your help we\'ll be able to recombine the amulet and return it to Lord Valthalak!', '', 11926, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('What happened to your mercenary company, The Veiled Blade?', 'What happened to your mercenary company, The Veiled Blade?', 11925, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Cool your heels!$B$B<Bodley grumbles something under his breath about the impatience of the living>$B$BAs I was saying, Lord Valthalak\'s spirit and spectral assassins, summoned forth through his necromantic dabbling, started to assail us. Let me tell you, at that point we weren\'t in any condition to fight back, so we ran. I can still remember Mor Grayhoof, one of our druids, slip and fall at one point into the lower reaches of the spire.$B$BThe rest as they say, is history.', '', 11924, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I thought you were almost done?', 'I thought you were almost done?', 11923, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('Sheesh, you don\'t have to beg! Anyways, I\'m almost done with the story.$B$BSo, the whole company is in the middle of that massive chamber fighting over this amulet, and you know how it echoes in there! In the end it was broken into three pieces, and we rolled the dice, with it going to various people or groups.$B$BThe rest is a bit of a blur, though, because it was at about that time that old Valthalak\'s spirit decided to make an entrance and start summoning forth all of these spectral assassins.', '', 11922, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Please continue, Bodley.', 'Please continue, Bodley.', 11921, 0, 0, 0, 65, 0, 0, 0, 20, 0, 0, 0, 0, 0, 39653),
('<Bodley looks at you dubiously, but continues...>$B$BThere we are, spellbook in hand, and Kormok, our two-headed ogre necromancer, gets this strange look in all four of his eyes. It was really creepy, because that second set of eyes always kind of looked dead, like a cow\'s eyes, you know? So, all of a sudden he just reaches out and rips this amulet off that Valthalak was wearing.$B$BThe rest of the company went crazy; some of us telling them to leave it alone, and others who wanted it for themselves.', '', 11920, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('No, no, please continue... it\'s just that the air up here is so, um, smoky.', 'No, no, please continue... it\'s just that the air up here is so, um, smoky.', 11919, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Oh yes, that\'s right.$B$BSo, here we are invading deep into the upper reaches of Blackrock Spire, against their lord and leader; this was before Drakkisath. Not too smart if you ask me, but our leader, Anthion Harmon, you met him, was always one who loved a challenge.$B$BSurprisingly, everything went according to plan, right up to the point where we were prying Valthalak\'s spellbook out of his stiff fingers. That\'s when it all went south.$B$BShould I continue? You look like your eyes are glazing over.', '', 11918, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You were telling me about The Veiled Blade and how you took the wrong mission.', 'You were telling me about The Veiled Blade and how you took the wrong mission.', 11917, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653);
INSERT INTO `broadcast_text` (`Text`, `Text1`, `ID`, `LanguageID`, `ConditionID`, `EmotesID`, `Flags`, `ChatBubbleDurationMs`, `SoundEntriesID1`, `SoundEntriesID2`, `EmoteID1`, `EmoteID2`, `EmoteID3`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `VerifiedBuild`) VALUES
('It\'s quite simple, really, $n. My old merc company, The Veiled Blade, took the wrong mission at the wrong time.$B$BWe were hired by a goblin smuggler out of Booty Bay, one Gremnik Rizzlesprang, who was covetous of Lord Valthalak\'s spellbook. Or, maybe there was some old rivalry there? I suppose we\'ll never know now, because Gremnik was killed not too long ago by a group of Valthalak\'s spectral assassins. They really can be very deadly when a large number of them gather.$B$BWhere was I?', '', 11916, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Bodley, tell me what\'s going on.', 'Bodley, tell me what\'s going on.', 11915, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Return the amulet! Return to me what was stolen!!', '', 11914, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hey Vi\'el, show me your wares!', 'Hey Vi\'el, show me your wares!', 11913, 0, 0, 0, 65, 0, 0, 0, 5, 0, 0, 0, 0, 0, 39653),
('I guess it\'s all just about over, right $n? I\'m going to miss you... it\'ll be pretty lonely up here without someone to talk to.$B$BBut that doesn\'t mean that you can\'t come back to see me in the future!', '', 11912, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Anthion, I seem  to have misplaced the banner you created for me. ', 'Anthion, I seem to have misplaced the banner you created for me. ', 11911, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I believe I misplaced that banner you enchanted for me, Falrin.', 'I believe I misplaced that banner you enchanted for me, Falrin.', 11910, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('About that ghost revealer.  Did I happen to leave it here?  I seem to be missing it.', 'About that ghost revealer.  Did I happen to leave it here?  I seem to be missing it.', 11909, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I seem to have misplaced the distiller, Mux.  Did I happen to leave it here?', 'I seem to have misplaced the distiller, Mux.  Did I happen to leave it here?', 11908, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What now?  Can\'t you see I\'m rather busy?', '', 11907, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Greetings, friend!  Can I interest you in some ectoplasmic capacitors?  Or perhaps a nice omni-directional spectral assimilator? ', '', 11906, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Losing my life was a danger I had come to terms with.  Losing Ysida is something I cannot endure, even after my own death.', '', 11905, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Try not to draw too much attention, I\'m waiting for the Council to grant me audience.  Not that I mind waiting, I feel pretty safe around all these burly guards.', 11904, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It is good that I have been allowed to continue my pursuits here.  I do not wish to overstay my welcome, at any rate.  It would be a great dishonor if I brought any trouble to our capital.', '', 11903, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I cannot teach you tribal leatherworking, $n. You must go to Tanaris and find the home of Narain Soothfancy. Once there, consult the book \"Soothsaying for Dummies.\"', '', 11902, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I cannot teach you tribal leatherworking, $n. You must go to Tanaris and find the home of Narain Soothfancy. Once there, consult the book \"Soothsaying for Dummies.\"', 11901, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I cannot teach you elemental leatherworking, $n. You must go to Tanaris and find the home of Narain Soothfancy. Once there, consult the book \"Soothsaying for Dummies.\"', '', 11900, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I cannot teach you elemental leatherworking, $n. You must go to Tanaris and find the home of Narain Soothfancy. Once there, consult the book \"Soothsaying for Dummies.\"', 11899, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('One by one, nearly everyone involved in this matter has fallen prey to these spectres.  I\'ll understand if you decide to walk away from this, $n.', '', 11898, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Trying to find out more about these creatures hasn\'t been easy.  My friend and the person who hired his mercenaries to steal Lord Valthalak\'s spellbook have both been feared dead for a while.', '', 11897, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('It was not my intention to get you involved in this, $n.  I\'ve spent every waking hour looking over my shoulder ever since I helped an old friend in a daring raid on Blackrock Spire.', '', 11896, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Begone foul creatures!  Go back to the void your master shaped you from!', '', 11895, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I cannot teach you dragonscale leatherworking, $n. You must go to Tanaris and find the home of Narain Soothfancy. Once there, consult the book \"Soothsaying for Dummies.\"', '', 11894, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Your fate is sealed, Mokvar!  You will pay for your trespasses against Lord Valthalak!', 'Your fate is sealed, Mokvar!  You will pay for your trespasses against Lord Valthalak!', 11893, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The assortment of images, shapes, and markings come together before your eyes. The book seems to know your skill with leatherworking and offers you a choice - but be warned - you may only select one and once you have done so, may not change your mind!:', '', 11892, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am absolutely certain that I want to learn tribal leatherworking.', 'I am absolutely certain that I want to learn tribal leatherworking.', 11891, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am absolutely certain that I want to learn elemental leatherworking.', 'I am absolutely certain that I want to learn elemental leatherworking.', 11890, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am absolutely certain that I want to learn dragonscale leatherworking.', 'I am absolutely certain that I want to learn dragonscale leatherworking.', 11889, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Come to think about it, most everyone involved is dead.  I\'ll understand if you don\'t want to be involved in any of this, $n.', 11888, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Trying to find out more about my predicament has been nearly impossible.  The smuggler that hired us has vanished and Anthion Harmon, our mercenary company\'s leader, is dead.', 11885, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Teach you gnomish engineering? I don\'t have time for this nonsense. You only get one chance with Oglethorpe and you blew that, didn\'t you?$B$BYou\'ll have to head to Tanaris and find Narain Soothfancy\'s hut. In that hut is a magical book that might be able to jostle whatever is left of your brain and reconnect you with what you\'ve lost.$B$BNow get lost!', '', 11884, 0, 0, 0, 65, 0, 0, 0, 1, 1, 5, 0, 0, 0, 39653),
('', 'I didn\'t mean to drag you into this, $n.  Ever since we took on a job to steal Lord Valthalak\'s spellbook, everyone involved has wound up dead or missing.', 11883, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Teach you the ways of gnomish engineering? Not going to happen! Not this gnome, anyway. You have a stink on you, $n. Maybe this is the pity talking but I will offer some advice.$B$BIn the Tanaris desert you\'ll find a hut that belongs to Narain Soothfancy. In that hut is a magical book that has been known to do wonderous things. Find that book and you may yet learn the gnomish way.', '', 11882, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'You\'re never going to stop coming after me, are you?  Fine, but you won\'t take me down without a fight!', 11881, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('So you\'re looking to relearn what you forgot, eh? Or maybe learn what you were never taught? I know just the thing, $n. Over by Steamwheedle port, to the east, you\'ll find a magical book in Narain\'s hut called \"Soothsaying for Dummies.\" Give it a read.$B$B<Nixx winks.>$B$BYou\'ll find all that you need to know and then some...', '', 11880, 0, 0, 0, 65, 0, 0, 0, 6, 1, 0, 0, 0, 0, 39653),
('Your fate is sealed, Deliana!  You will pay for your trespasses against Lord Valthalak!', 'Your fate is sealed, Deliana!  You will pay for your trespasses against Lord Valthalak!', 11879, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am 100% confident that I wish to learn in the ways of gnomish engineering.', 'I am 100% confident that I wish to learn in the ways of gnomish engineering.', 11878, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', '', 11877, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am 100% confident that I wish to learn in the ways of goblin engineering.', 'I am 100% confident that I wish to learn in the ways of goblin engineering.', 11876, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hundreds of various diagrams and schematics begin to take shape on the pages of the book. You recognize some of the diagrams while others remain foreign but familiar.', '', 11875, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The pages of this book have been destroyed.', '', 11874, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We am free! Thank you little, puny ones.', '', 11873, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Here are the final standings!$B$BThrall: $2200w$B$BCairne: $2201w$B$BSylvanas: $2202w$B$BTotal Horde: $2207w$B$B$BBolvar: $2203w$B$BMagni: $2204w$B$BTyrande: $2205w$B$BTotal Alliance: $2206w$B$BThe Horde and the Alliance tied in total votes!', '', 11872, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('<PH> Incoming Mages <PH>', '', 11871, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('When you give love tokens to townsfolk, you\'ll receive different gifts in return.  Some of those you\'ll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Cairne, Sylvanas and Thrall.', 'When you give love tokens to townsfolk, you\'ll receive different gifts in return.  Some of those you\'ll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Cairne, Sylvanas and Thrall.', 11870, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('We wish to face the Defiler.', 'We wish to face the Defiler.', 11869, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If it is your desire to visit the rise of the Defiler, you have only to ask. I am able to transport you and your comrades.', '', 11868, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If I make a gift collection, what do I do with it?', 'If I make a gift collection, what do I do with it?', 11866, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Can I show you what I have for sale?\n\n', '', 11865, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What? No, I don\'t do armor repairs. Everlook is about a mile to the north, $g brother : sister;.$B$BNow buy something, or move along before I summon my warlock to deal with you!', '', 11864, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Here for the rod? Or, maybe you\'re simply stocking up on runes?$B$BWait a minute! Are you just trying to offload a whole bunch of junk on me?! Curse my never-ending compulsion to buy, buy, buy!', '', 11863, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Very clever how you got in here like that, $n.$B$BWhat? Surprised that I know your name? I\'m a demon, that\'s what we do. I also know your true name, so you\'d better buy something expensive.', '', 11862, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Though I move on in peace, you all have my undying gratitude. Thank you for freeing me from the curse of my folly and greed.', '', 11861, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My torture is ended and now I can join the Goddess. Thank you so very much!', 11860, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Thank you for freeing me, my sister, and all of you! We can finally rest in peace now.', '', 11859, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I am free! Let\'s work together now to save my sister, Jarien!', '', 11858, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Here are the final standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BThe Horde has the most popular hero!', 'Here are the final standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BThe Horde has the most popular hero!', 11857, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Here are the final standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BThe Alliance has the most popular hero!', 'Here are the final standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BThe Alliance has the most popular hero!', 11856, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('The future is cloudy for you two. If you work at your relationship, I\'m sure you can find some measure of happiness.', '', 11854, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('I hear wedding bells in your future.', '', 11853, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You two will have many ups and downs, but if you can hold on, the ride will be worth it.', '', 11852, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('While you may try to make it work, in the end, you will go your separate ways.', '', 11851, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Yikes! Two fiery personalities. You\'ll have many arguments, but your love will burn just as hot!', '', 11850, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You two are surely star-crossed lovers who have found each other. There is much happiness in your future.', '', 11848, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('You there. You\'re welcome to take the contents of my cauldron. It was to be the second stage of my plan - amorous clothing.', '', 11847, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Annalise... You\'re right. I-I can\'t do this. I must find another way.', '', 11846, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('Annalise? Annalise! No, don\'t leave me!', '', 11845, 0, 0, 0, 65, 0, 0, 0, 20, 0, 0, 0, 0, 0, 39653),
('How could you love me, Annalise? Look at me. I am not the man you once knew.', '', 11844, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'And if you do not, then I am truly lost.', 11843, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I pledge my love to you forever. Death cannot erase that, even as I am sure that you still remember your love for me.', 11842, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'But of course I love you, Staffron. And it pains me to see you suffer so.', 11841, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('But I do know this - love makes the heart and body weak. It can be exploited. Without your love, I have only my work, Annalise.', '', 11840, 0, 0, 0, 65, 0, 0, 0, 25, 0, 0, 0, 0, 0, 39653),
('Have I forgotten? Of course I have... I have forgotten about love, happiness... of life itself.', '', 11839, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('', 'Staffron...', 11838, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My dear Staffron, have you forgotten what it is to love? The love that we once shared?', 11837, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Annalise? Is that you?', '', 11836, 0, 0, 0, 65, 0, 0, 0, 6, 0, 0, 0, 0, 0, 39653),
('How are the gift standings?  Who\'s the most popular?', 'How are the gift standings?  Who\'s the most popular?', 11835, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hi!  I\'m Kwee Q. Peddlefeet!  I\'m here to find out who is the most popular of all the heroes in Azeroth!$B$BIt sure warms my heart to see so many adoring fans greet their leaders, but... do you know what would warm me even more?$B$BA kiss!', '', 11834, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Who\'s the most popular hero of the realm, you ask?  Well here are the current standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BVarian: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BIf you want to cast your vote, be sure to turn in your gift collections!', 'Who\'s the most popular hero of the realm, you ask?  Well here are the current standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BVarian: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BIf you want to cast your vote, be sure to turn in your gift collections!', 11833, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Hey, $n. Over here, I want to talk to you.', '', 11832, 0, 0, 0, 65, 0, 0, 0, 70, 0, 0, 0, 0, 0, 39653),
('Welcome back, $n. Have I mentioned how good it is to have someone to talk to?$B$BAlright then, let\'s get down to business. What\'s next that we have to do?', '', 11831, 0, 0, 0, 65, 0, 0, 0, 1, 0, 0, 0, 0, 0, 39653),
('$n! You\'ve returned just to talk to me? That\'s very thoughtful of you, and you look pretty sweet in that outfit, too!$B$BYou don\'t know how good it makes me feel to see you. It can get pretty lonely up here, what with most of these yahoos not being able to see me, and all. It\'s a great thing that you did for all of us, and I\'ll never forget it!$B$BThanks for dropping in and saying hi, and don\'t be such a stranger.', '', 11830, 0, 0, 0, 65, 0, 0, 0, 71, 1, 0, 0, 1000, 0, 39653),
('When you give love tokens to townsfolk, you\'ll receive different gifts in return.  Some of those you\'ll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Bolvar, Magni, or Tyrande.', 'When you give love tokens to townsfolk, you\'ll receive different gifts in return.  Some of those you\'ll want to keep and use, but others can be bundled together and given to your favorite hero!  Visit Kwee Q. Peddlefeet to turn them in.$B$BKwee can be found near Bolvar, Magni, or Tyrande.', 11829, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What can I do with these gifts?', 'What can I do with these gifts?', 11828, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('If you put on cologne or perfume, then you\'ll see who is amorous.  Those are the ones who accept love tokens... and offer a gift in return.$B$BBut remember: to give someone a love token, you have to smell just right!  Men like the scent of perfume, while women prefer cologne.', 'If you put on cologne or perfume, then you\'ll see who is amorous.  Those are the ones who accept love tokens... and offer a gift in return.$B$BBut remember: to give someone a love token, you have to smell just right!  Men like the scent of perfume, while women prefer cologne.', 11827, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Love tokens are small messages of affection you can give to amorous town and city folk.  Such people will reward you with a gift of adoration.$B$BOr, if you are already adored by another, then at the least they\'ll give you a gift of friendship.', 'Love tokens are small messages of affection you can give to amorous town and city folk.  Such people will reward you with a gift of adoration.$B$BOr, if you are already adored by another, then at the least they\'ll give you a gift of friendship.', 11826, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re selling cologne and perfume?', 'You\'re selling cologne and perfume?', 11825, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What are love tokens?', 'What are love tokens?', 11824, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Does that heart mean you\'re looking for love?', 'Does that heart mean you\'re looking for love?', 11823, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('No, I\'m not, but lots of others are looking for love.  You should buy my love tokens, put on some cologne or perfume, and then pass them around!', 'No, I\'m not, but lots of others are looking for love.  You should buy my love tokens, put on some cologne or perfume, and then pass them around!', 11822, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('My mission is compete. I may have some spare supplies if you need any.', '', 11821, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Let\'s see what you have.', 'Let\'s see what you have.', 11820, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Thank you for freeing me, my brother, and all of you! We can finally rest in peace now.', 11819, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'I am free! Let\'s work together now to save my brother, Sothos!', 11818, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'My death means nothing.... light... will... prevail!', 11817, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Don\'t worry about me!  Slay this dreadful beast and cleanse this world of his foul taint!', 11816, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I shall take great pleasure in taking this poor wretch\'s life!  It\'s not too late, she needn\'t suffer in vain.  Turn back and her death shall be merciful!', '', 11815, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('May this prisoner\'s death serve as a warning.  None shall defy the scourge and live!', '', 11814, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('You\'re still here?  Your foolishness is amusing!  The Argent Dawn wench needn\'t suffer in vain.  Leave at once and she shall be spared!', '', 11813, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('Intruders!  More pawns of the Argent Dawn, no doubt.  I already count one of their number among my prisoners.  Withdraw from my domain before she is executed!', '', 11812, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('I\'d talk to you if you smelled better. How about cologne? Maybe perfume?', 'I\'d talk to you if you smelled better. How about cologne? Maybe perfume?', 11811, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('What, you don\'t have a token to give me? Don\'t you love me?', '', 11810, 0, 0, 0, 65, 0, 0, 0, 18, 0, 0, 0, 0, 0, 39653),
('I\'d like you better if you would apply some perfume.', '', 11809, 0, 0, 0, 65, 0, 0, 0, 24, 0, 0, 0, 0, 0, 39653),
('You look like you\'ve had your heart broken. Come back when you\'re not so sad.', '', 11808, 0, 0, 0, 65, 0, 0, 0, 25, 153, 0, 0, 0, 0, 39653),
