('', 'Oh, I wandered off again.  I\'m sorry.', 3913, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Are we taking the scenic route?', 3912, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
