('', 'Are you sure this is the right way? Maybe we should go this way instead...', 3909, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'These trees are quite glorious, aren\'t they? ', 3908, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
('', 'Oh, what a beautiful flower over there...', 3907, 0, 0, 0, 65, 0, 0, 0, 0, 0, 0, 0, 0, 0, 39653),
